window.SEARCH_DATA=window.SEARCH_DATA||{};window.SEARCH_DATA["search/osaki/2026-001.js"]=[{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":1,"text":"会派視察報告書\n\n\n会 派 名   公明党\n\n視 察 日    令和8年7月22日\n\n視 察 者   山田匡身、遠藤彰\n\n視 察 先   北海道砂川市役所4階 委員会室\n\n視察項目   子育て支援サービスについて\n       視察先の北海道砂川市は、「子育てするなら砂川で」をスローガンに掲げ、医療費や\n       学校給食費の完全無償化をはじめ、保育所での「おむつサブスクリプション」や\n       キャッシュレス決済の導入など、先進的な保護者負担軽減策を力強く進めている。大\n選定理由\n       崎市とは規模が異なるものの、現場のニーズに即したソフト面の工夫などは本市の市\n       民サービス向上や今後の施策立案に極めて有用であると判断し、視察先として選定し\n       た。\n       保健福祉部子育て支援課長 兼 子ども家庭センター所長 作田 哲也\n       保健福祉部子育て支援課子育て支援係長 小澤 友祐\n説 明 者   保健福祉部子ども家庭センター主幹 兼 ふれあいセンター主幹 高島 理穂\n       砂川市議会議長 多比良 和伸\n       砂川市議会事務局長 安武 浩美\n       砂川市では、「子育てするなら砂川で」を掲げ、市役所庁舎内に開設した「こども家\n       庭センター」を核とした切れ目のない支援を推進している。医療費・給食費の完全無\n       償化をはじめ、保育所での「おむつサブスクリプション」やキャッシュレス決済の導\n視察概要\n       入など、独自の保護者負担軽減策を展開している。また、小中一貫の義務教育学校\n       「砂川学園」の開校により教育環境も拡充している。視察では事業の経緯や効果の説\n       明を受け、子育て支援の状況を確認した。\n       （1）保護者の経済的・時間的負担の軽減策\n       砂川市では、「子育てするなら砂川で」というスローガンのもと、子育て世帯の負担\n       軽減を最重点施策として強力に推進している。医療費助成を高校生年代まで拡充し、\n       「完全無償化」を実現したほか、小中学校における学校給食費の完全無償化を実施し\n       ている。また、「乳児すこやか応援クーポン券支給事業」を拡充し、支給限度額を年\n        間最大48,000円から60,000円へと増額するとともに、支給期間もおむつが取れる時期\n 詳 細\n       を想定して3年間に延長した。対象品目もおむつに限らず、粉ミルクや離乳食、衣類\n       など多様な育児用品へ拡大している。さらに、紙おむつ等の使用でごみが増えること\n        への配慮として、3歳未満の児童がいる世帯に燃やせるごみ袋を月10枚（年間最大120\n       枚）配布する事業や、産後ケア事業、北海道子どもの国ふしぎの森の大人利用料無償\n       化クーポンの配布（小学校6年生以下の児童がいる世帯対象）など、家計と育児を力\n       強く支える細やかな支援を展開している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":2,"text":"会派視察報告書\n\n\n       （2）保育環境の改善と業務効率化\n      保育所等においては、保護者と保育士双方の負担軽減を図る先進的な取り組みが進め\n      られている。独自の取り組みである「おむつサブスクリプション」の導入により、園\n      内で定額の紙おむつが使い放題となり、保護者が毎朝登園時におむつを持参し、一枚\n      ずつ記名する手間を完全に解消した。同時に、各施設におむつ専用ゴミ箱を設置して\n      使用済みおむつの持ち帰りを廃止したことで、保護者の衛生面・心理面での負担を減\n      らしている。これは保育士にとっても、園児ごとのおむつ管理や仕分け作業をなくす\n       業務改善に結びついている。また、保育所ICTシステムを導入して欠席連絡や登降園\n      管理、お知らせ配信をデジタル化したほか、学童保育の短期利用料や一時預かり事業\n      の支払い等にキャッシュレス決済を導入し、保護者が金融機関等の窓口へ出向く負担\n      の軽減と手続きの利便性向上を図っている。\n       （3）相談拠点の集約と教育・学童保育環境の拡充\n       令和6年4月、市役所庁舎内に総合相談窓口「こども家庭センター」を開設した。これ\n      まで分散していた母子保健機能と児童福祉機能を統合し、専門の相談員（保健師等）\n      を常駐させるとともに、母子手帳アプリ「砂川すくすく子育て応援アプリ」と連携さ\n      せることで、妊娠期から子育て期まで途切れのない支援体制を整備している。教育環\n       境においては、同年4月に市内の全小中学校（6校）を統合した小中一貫の義務教育学\n      校「砂川学園」を開校させた。これに合わせ、スクールバスの運行を開始したほか、\n       市内5箇所にあった学童保育所を2拠点へ再編し、良質な教育環境の提供と保護者の就\n詳 細\n      労支援の両立を図っている。\n\n       （4）質疑応答\n       【Q】 不妊治療費助成事業および妊婦タクシー助成事業の具体的な実績や効果、今後\n      の運用課題はどのようなものか。\n       【A】 不妊治療費助成事業は申請者の約46.4％が妊娠に至るなど高い成果と満足度を\n      得て制限緩和等が今後の課題とされる一方、妊婦タクシー助成事業は自家用車文化に\n       より利用率は約12％にとどまるものの緊急時のセーフティネットとして不可欠な事業\n      となっている。\n       【Q】 様々な子育て支援策を展開している中で、市民アンケート等において特に評価\n      が高い施策は何か。\n       【A】 アンケートでは所得制限や自己負担金のない「子ども医療費無償化」が絶大な\n      支持で最も高く評価され、次いで安心できる学校・保育環境や、子育て支援センター\n       の移転に伴い利用者が約1.5倍に増えた相談体制の充実が上位の評価を得ている。\n       【Q】 病児・病後児保育事業の利用実績や、施設の維持・運営にあたっての課題はど\n      のように捉えているか。\n       【A】 市立病院内（定員3名）で運営されている病児保育事業は、事前受診の手間や\n      費用、開所日の約半分という稼働率の低さが課題となっているものの、市は費用対効\n      果を超えた「地域に不可欠なインフラ」として体制を維持する方針である。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":3,"text":"会派視察報告書\n\n\n       【Q】 おむつサブスクリプション導入やキャッシュレス決済推進の狙いと現場の反応\n      はどうか。\n       【A】 保護者の記名・持参や保育現場の管理負担を解消するDX施策としての「おむつ\n      サブスク」が低年齢児を中心に好評を博しているほか、学童保育等の窓口支払いの手\n      間を省く「キャッシュレス決済」も初期費用を抑えたシステム活用により迅速に導入\n      され、双方で利便性の向上を図っている。\n       【Q】 義務教育学校「砂川学園」開校の経緯と、就学前の保育・幼稚園から小学校へ\n      の連携はどのように取り組んでいるか。\n       【A】 単学級化の解消を目指して開校した義務教育学校が小中一貫教育で児童の成長\n      や好影響を促す一方、幼保小連携では就学時健診や入学前の引き継ぎ会議を通じて情\n      報を事前共有し、スムーズな就学と切れ目のない支援体制を実現している。\n詳 細\n       【Q】 市民から屋内大型遊戯場など「子どもの遊び場」のさらなる拡充を求める声は\n      ないか。\n       【A】 市民から天候に左右されない大型遊戯施設を求める声はあるものの、巨額の財\n      政負担から新規建設は困難であるため、市としては既存施設や空きスペースを賢く活\n      用して機能を高めていく方針である。\n       【Q】 今後さらに力を入れたいと考えている子育て支援策や、現在感じている課題・\n      展望はどのようなものか。\n       【A】 児童数の減少に対して低年齢児の保育需要は高まり続け今年度拡充した枠もす\n      でに満杯に近いため待機児童対策の検討が必要であるほか、依然として要望の多い\n      「経済的負担の軽減」についても財政バランスを考慮しながら引き続き模索していく\n      方針である。\n\n\n      山田 匡身 代表\n      砂川市が掲げる「子育てするなら砂川で」という明確な理念のもと、市長の強いリー\n      ダーシップのもとで実効性の高い施策が次々と展開されている点に深く感銘を受け\n      た。高校生年代までの医療費および小中学校の給食費における所得制限なしの「完全\n      無償化」や、年間上限を増額したおむつ等クーポン券の支給など、子育て世帯の経済\n      的負担を徹底して軽減する姿勢である。また、保護者の時間的・心理的負担と保育士\n所 感\n      の業務負担を同時に解消する「おむつサブスクリプション」の導入や、学童保育等へ\n      のキャッシュレス決済の導入といった現場ニーズに即したDX推進は、大変先進的か\n      つ実用的な取り組みであった。本市においても、こうした柔軟な発想や他自治体の優\n      れた事例を取り入れる重要性を強く認識した。今後の本市における子育て支援のさら\n      なる充実に向けてしっかりと生かしていきたい。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":4,"text":"会派視察報告書\n遠藤彰幹事長\n砂川市視察で最も印象に残ったのは、 「 子育てするなら砂川で 」 の理念のもと、負担\n軽減策が強力に推進されている点である。高校生年代までの医療費や小中学校の給食\n費の完全無償化、おむつクーポン等の手厚い支援は少子化対策の本気度を示すもので\n大変参考になった。また、おむつサプスクや学童でのキャッシュレス決済など、保護\n者の負担軽減と保育士の業務効率化 (DX) を同時に実現している点は大崎市でも取\nり入れるべき先進的な取り組みである。さらに、不妊治療の確かな実績や、妊婦タク\nシーをセーフティネットとして位置づける実効性重視の姿勢にも深く感銘を受けた。\n今回学んだ事を大崎市における子育て支援策の充実にしつかりと生かしていきたい。\n砂川市の視察では、 「 子育てするなら砂川で 」 の理念のもと展開される先進的な支援\n策を直接学び、極めて有意義な機会となった。高校生年代までの医療費や小中学生の\n給食費完全無償化に加え、おむつサプスクやキャッシュレス決済など実効性ある DX 施\n策が徹底されている。また、\n「 こども家庭センター 」 の設置や義務教育学校 「 砂川学\n園 」 の開校など、ハード・、ノフト両面での切れ目のない基盤づくりを確認した。一方\nで、低年齢児の保育需要や病児保育等のリアルな課題も伺え、行政運営を深く考察す\nる契機となった。大崎市においても、本視察で得られた知見や財源活用の先進事例を\n参考に、今後の子育て支援政策のさらなる充実に反映させていきたい。\n視察の様子\n\n[PDFテキスト]\n会派視察報告書\n\n\n\n      遠藤 彰 幹事長\n      砂川市視察で最も印象に残ったのは、「子育てするなら砂川で」の理念のもと、負担\n      軽減策が強力に推進されている点である。高校生年代までの医療費や小中学校の給食\n      費の完全無償化、おむつクーポン等の手厚い支援は少子化対策の本気度を示すもので\n所 感    大変参考になった。また、おむつサブスクや学童でのキャッシュレス決済など、保護\n      者の負担軽減と保育士の業務効率化（DX）を同時に実現している点は大崎市でも取\n      り入れるべき先進的な取り組みである。さらに、不妊治療の確かな実績や、妊婦タク\n      シーをセーフティネットとして位置づける実効性重視の姿勢にも深く感銘を受けた。\n      今回学んだ事を大崎市における子育て支援策の充実にしっかりと生かしていきたい。\n\n\n\n      砂川市の視察では、「子育てするなら砂川で」の理念のもと展開される先進的な支援\n      策を直接学び、極めて有意義な機会となった。高校生年代までの医療費や小中学生の\n       給食費完全無償化に加え、おむつサブスクやキャッシュレス決済など実効性あるDX施\n      策が徹底されている。また、「こども家庭センター」の設置や義務教育学校「砂川学\n総 括\n      園」の開校など、ハード・ソフト両面での切れ目のない基盤づくりを確認した。一方\n      で、低年齢児の保育需要や病児保育等のリアルな課題も伺え、行政運営を深く考察す\n      る契機となった。大崎市においても、本視察で得られた知見や財源活用の先進事例を\n      参考に、今後の子育て支援政策のさらなる充実に反映させていきたい。\n\n\n                  視 察 の 様 子","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":5,"text":"会派視察報告書\n\n\n会 派 名   公明党\n\n視 察 日    令和8年7月23日\n\n視 察 者   山田 匡身、遠藤 彰\n\n視 察 先   北海道札幌市役所本庁舎16階会議室\n\n視察項目   クマ対策について\n       クマ出没やハンター不足が深刻化する本市の課題解決に向け、札幌市の「ヒグマ基本\n選定理由   計画」に基づくゾーニング管理、猟友会・NPOとの手厚い連携、分割式箱罠の運用や\n       教育啓発等の先進事例を本市へ活かすため選定した。\n       札幌市環境局環境都市推進部環境共生担当課長　坂田 一人\n説 明 者   札幌市環境局環境都市推進部環境共生担当課 熊対策調整担当係長　藤田 将\n       札幌市環境局環境都市推進部環境共生担当課 熊対策調整担当係長　朝倉卓也\n\n       森林と街を区分し侵入を防ぐゾーン分け管理や、行政と猟友会が対等なパートナーと\n       して信頼関係を築く手厚い費用委託の仕組みについて説明を受けた。また、重量のあ\n       る箱罠が現場へ運べない課題に対し、軽トラックで運搬・組み立てが可能な「分割式\n視察概要   箱罠」の導入事例や、専門業者（NPO）への初動調査委託による速やかな要因特定な\n       ど、実効性の高い運用手法を学んだ。さらに、学校現場でのヒグマ講座やスクール\n       ガードへの鈴・ホイッスル配備、地域と協働した草刈りや放置果樹の伐採支援など、\n       未然防止に向けた教育・環境整備の重要性についても知見を深めた。\n\n                 (1) 現状について\n       札幌市は市域の3分の2以上を森林が占め、住宅街と直接隣接する都市構造を持つ。積\n       丹地域個体群の生息数増加や北海道の「第2期ヒグマ管理計画」による個体数削減目\n       標を背景に、令和7年度は山の実りの凶作等から363件の出没や人身被害、道内初の\n       「緊急銃猟」の実施など深刻な被害が相次いだ。これに対し、市域を4つのゾーンに\n       分ける「さっぽろヒグマ基本計画」の2026年改定を進め、誘引物対策の強化や都市近\n       郊林での計画的捕獲を明記することで、未然防止型の先手管理体制への転換を図って\n 詳 細    いる。\n                (2) 捕獲・防除体制と地域連携の仕組み\n        110番等の通報時は専門NPOへ初動調査や痕跡鑑識を委託し、猟友会の出動を危険な\n       場面に限定してハンターの負担を軽減している。また、電気柵の補助や道具・処分調\n       整等の行政支援のもと、ボランティアと協働で草刈りや放置果樹伐採による緩衝帯整\n       備を推進。情報発信ではパニックを防ぐため誤報の少ない正確な情報を公式Webサイ\n       ト等で届けるほか、ヘアトラップや糞のDNA分析により個体・移動ルートを特定し、\n       効果的な捕獲や侵入防止に活用している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":6,"text":"会派視察報告書\n\n\n              (3) ハンター確保・現場機材・学校安全教育の具体的運用\n      札幌市では、猟友会札幌支部による清掃活動等の社会貢献を通じて会員数が増加傾向\n       （約700名）にある中、選抜された「ヒグマ防除隊（35名）」と事前準備や罠管理費\n      等を網羅した手厚い包括委託契約を締結して良好な協力体制を築いている。また、軽\n      トラックで搬送し現地で組み立てられる特注・分割型箱罠の導入で搬送・設置の重労\n      働を大幅軽減。学校現場でも電気柵設置や見守り強化に加え、出前講座や小4の地域\n      学習を通じた継続的なヒグマ教育を実施し、捕獲体制の強化から教育まで一体的に展\n      開している。\n\n              (4) 質疑応答\n       【Q】 クマが出没した際の対応や捕獲の判断基準はどうか。\n       【A】 クマの行動を4段階（レベル1：人を見て逃げる～レベル4：人を攻撃・接近）\n      に分けた「有害性判断表」と、4つのゾーン区分を組み合わせた「基本対応方針表」\n      により防除や捕獲等の対応を定めている。現在は後手対応を防ぐため、より低いレベ\n      ルでも捕獲・防除を強化する計画改定を進めている。\n       【Q】 大崎市ではハンターの高齢化・減少が深刻である。札幌市で猟友会会員が増加\n      している要因と、捕獲対価などの費用対応はどうか。\n       【A】 市が特別な勧誘をしているわけではなく、猟友会札幌支部自体がゴミ拾いやイ\n詳 細    ベント参加、ジビエPRなどの社会貢献活動を積極的に行い、地域へアピールしている\n      成果で若い世代や女性の加入が進んでいる。費用面は単発の1頭単価ではなく積算に\n      基づく手厚い包括委託契約を締結しており、費用面の不満は出ていない。\n\n\n\n       【Q】 大崎市ではイノシシ用くくり罠への錯誤捕獲や、地元鉄工所から寄贈された鉄\n      板製箱罠が重すぎて現場へ運べず活用できていない課題がある。札幌市の罠の運用は\n      どうか。\n       【A】 捕獲は原則箱罠で行っている。現場への搬送・設置負担を軽減するため、「軽\n      トラックで搬送し現場で組み立てられる分割型の特注箱罠」を発注・導入した。強度\n      の問題もなく運用できており、職員やハンターの現場負荷を大幅に減らしている。\n       【Q】 学校周辺や通学路におけるクマ対策、児童への安全教育の具体的な取組はどう\n      か。\n       【A】 ハード面では山際の学校への電気柵設置やクルミの木伐採を実施している。見\n      守り面ではスクールガード（ボランティア）へホイッスル、警察OBリーダーへ熊除け\n       鈴を配布し巡回を強化している。教育面ではNPOによる「ヒグマ講座」のほか、小4\n      の地域学習で「共生や安全対策を児童自ら考え発表する」継続的な授業プログラムを\n      取り入れている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":7,"text":"会派視察報告書\n山田匡身\n本市のツキノワグマ対策において、捕獲の後手化やハンターの負担増は喫緊の課題で\nあり、今回の視察を通じて 「 先手管理体制 」 への転換の重要性を痛感した。特に\nゾーン管理による未然防止や、巡回・罠管理も含めた猟友会との 「 包括委託契約 」 、\n分割型箱罠による現場の負担軽減、 NPO ・学校と連携した継続的な安全教育など、\n回の視察で得た先進的な知見を大崎市でもしつかりと生かしていきたい。\n藤早彡\n現場の苦労に寄り添う札幌市の工夫に深く感銘を受けた。本市でも捕獲罠の運搬作業\nやハンターの負担増は深刻な課題である。札幌市では初動調査の NPO 委託や分割型箱\n罠の導入により現場の負担を大幅に削減し、市職員が住民とともに草刈り等を行う\n「 現場主義 」 で支援していた。ハンターや地域住民の負担軽減を最優先に考え、市民\nと行政が一体となって地域を守る仕組みづくりを、大崎市でもしつかりと生かしてい\nきたい。\n本視察を通じ、札幌市のヒグマ対策は単なる駆除にとどまらず、現場の負担軽減と住\n民協働を両立させた 「 先手管理体制 」 へ明確に転換していることが確認できた。 NPO\n委託による初動調査や分割型箱罠の導入によるハンターの負担軽減、行政が伴走する\n住民・学生との草刈りや放置果樹伐採など、現場主義に基づく実効性の高い施策が徹\n底されている。安全対策は行政任せでも市民任せでも成り立たない。ハンターや地域\n住民の負担軽減を最優先とし、市民と行政が一体となって地域を守る持続可能な仕組\nみづくりを、大崎市でもしつかりと生かしていきたい。\n所感\n視察の様子\n4\n\n[PDFテキスト]\n会派視察報告書\n\n\n      山田 匡身\n      本市のツキノワグマ対策において、捕獲の後手化やハンターの負担増は喫緊の課題で\n      あり、今回の視察を通じて「先手管理体制」への転換の重要性を痛感した。特に、\n      ゾーン管理による未然防止や、巡回・罠管理も含めた猟友会との「包括委託契約」、\n       分割型箱罠による現場の負担軽減、NPO・学校と連携した継続的な安全教育など、今\n      回の視察で得た先進的な知見を大崎市でもしっかりと生かしていきたい。\n\n所 感\n      遠藤 彰\n      現場の苦労に寄り添う札幌市の工夫に深く感銘を受けた。本市でも捕獲罠の運搬作業\n       やハンターの負担増は深刻な課題である。札幌市では初動調査のNPO委託や分割型箱\n      罠の導入により現場の負担を大幅に削減し、市職員が住民とともに草刈り等を行う\n      「現場主義」で支援していた。ハンターや地域住民の負担軽減を最優先に考え、市民\n      と行政が一体となって地域を守る仕組みづくりを、大崎市でもしっかりと生かしてい\n      きたい。\n\n\n      本視察を通じ、札幌市のヒグマ対策は単なる駆除にとどまらず、現場の負担軽減と住\n       民協働を両立させた「先手管理体制」へ明確に転換していることが確認できた。NPO\n      委託による初動調査や分割型箱罠の導入によるハンターの負担軽減、行政が伴走する\n総 括    住民・学生との草刈りや放置果樹伐採など、現場主義に基づく実効性の高い施策が徹\n      底されている。安全対策は行政任せでも市民任せでも成り立たない。ハンターや地域\n      住民の負担軽減を最優先とし、市民と行政が一体となって地域を守る持続可能な仕組\n      みづくりを、大崎市でもしっかりと生かしていきたい。\n\n\n                  視 察 の 様 子","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":8,"text":"会派視察報告書\n\n\n会 派 名   公明党\n\n視 察 日    令和8年7月24日\n\n視 察 者   山田匡身、遠藤彰\n\n視 察 先   北海道石狩郡当別町役場会議室、ロイズタウン駅\n\n視察項目   ロイズタウン周辺のまちづくりについて\n       当別町では、民間企業である株式会社ロイズコンフェクトと連携し、JR北海道「ロ\n       イズタウン駅」の開業を契機に、駅周辺のまちづくりや観光振興、交流人口の拡大に\n       取り組んでいる。また、企業版ふるさと納税を活用した駅整備、自動運転バスの実証\n選定理由\n       運行、インバウンド誘客など、官民連携による地方創生を積極的に推進している。人\n       口減少や地域公共交通の維持、観光振興が課題となっている大崎市においても参考と\n       なる先進事例であることから視察先として選定した。\n       企画部事業推進課　課長　遊佐 博憲 氏\n       企画部事業推進課事業推進係　係長　寺田 航平 氏\n説 明 者\n       当別町議会　副議長　稲村 勝俊 氏\n       当別町議会事務局　議会事務局長　熊谷 康弘 氏\n       当別町では、株式会社ロイズコンフェクトとの官民連携により、令和4年3月にJR北\n       海道「ロイズタウン駅」を開業し、新駅を核としたまちづくりを推進している。駅整\n       備には企業版ふるさと納税を活用し、ロイズ工場のリニューアルや道の駅とうべつと\n       連携した地域活性化を進めている。また、自動運転バスの実証運行や地域ブランド\n視察概要\n       化、インバウンド誘客など様々な施策を展開し、観光客数は年間約212万人まで増加\n       している。視察では、事業の経緯や効果、今後の展望について説明を受けるととも\n       に、ロイズタウン駅及び駅前広場を現地視察し、駅を中心としたまちづくりの状況を\n       確認した。\n       （1）ロイズタウン駅整備の経緯\n       当別町では人口減少対策と交流人口の拡大を目的に、民間企業である株式会社ロイズ\n       コンフェクトと連携し、新たなまちづくりを進めている。令和2年1月、当別町とロイ\n       ズが連名でJR北海道へ新駅設置を要望したことを契機に計画が具体化し、令和4年3\n       月に「ロイズタウン駅」が開業した。駅は無人駅で、ホームは6両編成対応（135\n       メートル）となっている。また、令和4年12月には駅前広場も完成し供用を開始し\n       た。駅舎・ホーム整備費は約10億円、駅前広場整備費は約6億円である。駅舎整備費\n       については、ロイズからの企業版ふるさと納税を活用し、町が整備を行った。\n 詳 細\n       （2）ロイズとの官民連携による地域活性化\n       ロイズは平成10年頃に当別町へ工場を建設し、その後も増設・拡張を進めてきた。\n       令和5年8月には「ロイズカカオ＆チョコレートタウン」としてリニューアルオープン\n       し、工場見学ができる体験型施設として全国から多くの観光客が訪れている。さら\n       に、工場周辺の行政地名を「ロイズタウン」に変更し、商品の所在地表示にも活用す\n       ることで地域ブランドの向上につなげている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":9,"text":"会派視察報告書\n\n\n       （3）交流人口拡大への取組\n      町では駅開業と工場リニューアルに合わせ、駅周辺のにぎわい創出事業を実施した。\n      自動運転バスの実証運行や各種イベントを約1か月実施し、約4万人が来場した。観\n       光客数は平成20年代　約40万人道の駅開業後　約83万人令和6年度　約189万人令和\n       7年度　約212万人まで増加している。また、外国人観光客についても位置情報分析\n      では全国トップクラスの伸び率となっている。\n\n       （4）自動運転バスの実証運行\n       令和5・6年度にフランス・Navya社製の8人乗り自動運転バスを使用し、ロイズタウ\n      ン駅、ロイズ工場、道の駅とうべつを結ぶルートで実証運行を実施した。将来的な地\n      域公共交通への活用を見据えた取組であるが、車両価格が高額、雪を障害物として認\n      識する、冬季運行への対応、発進・停止時の乗り心地などが課題として挙げられた。\n\n       （5）ふるさと納税\n       令和6年度の寄附額は約18億円であり、最も多かった令和4年度は約29億円となって\n      いる。返礼品の約9割はロイズ製品であり、地域ブランドがふるさと納税の大きな魅\n      力となっている。\n\n       （6）現地視察\n詳 細    説明終了後、ロイズタウン駅へ移動し、駅舎やホーム、駅前広場について現地説明を\n       受けた。駅はロイズ工場まで徒歩約10分（約600メートル）の位置にあり、観光客の\n      利用を想定したシンプルな無人駅となっていた。駅前広場では、一般車両や観光バス\n      の乗降スペース、自動運転バスの発着場所、歩行者動線などについて説明を受けた。\n      また、ロイズ工場や道の駅とうべつとの回遊性を高めることで、交流人口の拡大や滞\n      在時間の延長を図るまちづくりについて現地で確認することができた。\n\n       （7）主な質疑応答\n      Q　ロイズタウン駅整備のきっかけは。\n          A ロイズ工場の拡張計画に合わせ、当別町とロイズが共同でJR北海道へ新駅設置を\n      要望したことが契機となった。\n      Q　人口への効果は。\n          A 住宅取得支援制度なども実施した結果、令和3年度以降は社会増減がプラスへ転じ\n      ている。\n      Q　自動運転バスの課題は。\n          A 冬季の雪への対応や車両価格の高さ、市街地での安定した運行などが課題であり、\n      現在も実証を継続している。\n       Q　今後の展望は。\n          A 交流人口のさらなる拡大を図り、将来的には定住人口の増加につなげたい。駅周\n      辺についてもロイズや地権者と連携しながら活用を進めていく。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":10,"text":"会派視察報告書\n\n\n\n      山田 匡身　代表\n      今回の視察では、ロイズという民間企業を中心に、行政とJR北海道が一体となって\n      新駅整備から観光振興、地域ブランド化まで推進していることに大きな感銘を受け\n      た。企業版ふるさと納税を活用した駅整備や、行政地名を「ロイズタウン」とするな\n      ど、企業ブランドを地域全体の魅力へ発展させている点は、全国的にも先進的な取組\n      であると感じた。現地ではロイズタウン駅や駅前広場を視察し、駅と工場、道の駅が\n      一体となったまちづくりを実際に確認することができた。大崎市においても、鳴子温\n      泉をはじめとした地域資源を生かし、民間企業や関係機関との連携を強化すること\n      で、交流人口の拡大と地域活性化につなげていく必要性を強く感じた。\n所 感\n      遠藤 彰　幹事長\n      ロイズタウン駅の整備を契機に観光客数が大きく増加し、地域経済へ波及効果をもた\n      らしていることを具体的なデータとともに学ぶことができた。また、自動運転バスの\n      実証運行についても、地域公共交通の将来を見据えた先進的な取組でありながら、冬\n      季走行や車両コストなど現実的な課題についても率直な説明を受け、大変参考となっ\n      た。現地視察では、駅周辺の整備状況や工場との距離感、歩行者動線などを直接確認\n      し、駅を核としたまちづくりの効果を実感することができた。大崎市においても、地\n      域資源を生かした官民連携や公共交通の維持・活性化に向け、今回得た知見を今後の\n      政策提言に生かしていきたい。\n\n\n\n      当別町では、ロイズという地域資源を最大限に活用し、行政・企業・JR北海道が連\n      携したまちづくりを推進していた。新駅整備を契機に観光振興や地域ブランド化、企\n      業版ふるさと納税の活用など、多くの相乗効果を生み出し、交流人口の大幅な増加に\n総 括    つながっていることを確認した。また、現地視察を通じて、ロイズタウン駅とロイズ\n      工場、道の駅とうべつが一体となった地域づくりの実態を把握することができた。本\n      視察で得た官民連携や公共交通、地域ブランド戦略などの知見を、大崎市における地\n      域活性化や観光振興、持続可能なまちづくりに生かしていきたい。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"6cf14613d6dc1d36","year":2026,"faction":"公明党","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/koumei_20260722_24.pdf","page":11,"text":"会派視察報告書\n視察の様子\nJ 日北海道\nROYCE' TOWN STATION\nロイスタウン駅\n\n[PDFテキスト]\n会派視察報告書\n\n\n  視 察 の 様 子","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":1,"text":"会派視察報告書\n\n\n会 派 名   大地\n\n視 察 日   令和８年８月４日（火）\n\n視 察 者   伊勢健一 後藤錦信 髙橋雅博 川合明弘\n\n視 察 先    富山県黒部市 YKK AP株式会社黒部製造所／YKK AP技術館\n\n視察項目   企業とまちづくりの関わりについて\n       大崎市と黒部市は、YKK株式会社の仲立ちにより姉妹都市の提携を結んでい\n         る。YKK AP株式会社は、黒部市に製造・研究開発の拠点を置く企業であり、\n       工場の整備にとどまらず、周辺地域との共生を意識した街づくりを実践してい\n選定理由\n       る。同社の視察を通し、地方創生、モノづくり産業の振興、環境施策の観点等\n       について学び、大崎市の市政運営に役立てるため、会派会議において協議のう\n       え視察先として選定した。\n           YKK AP株式会社 生産本部 黒部総務部長 藤崎 猛 氏\n説 明 者\n           YKK AP技術館 YKK AP先人ホール館長 畑谷 弘之 氏\n           YKK AP株式会社は、黒部市に製造・研究開発の拠点を置く企業であり、工場\n       の整備にとどまらず、周辺地域との共生を意識した街づくりを実践している。\n       本視察では、①地域社会と共生する「まちづくり」と産業観光の推進、②防\n       災・環境対策とスマート化、③企業の人材育成と地元雇用の創出、の三点につ\n視察概要   いて説明を受けた。社員寮やパッシブタウンを地域住民に開放する街づくり、\n       創業時の工場を保存活用した技術館の一般公開、物流DXを核としたBCP体制の\n       構築、企業内大学の開校や定年の廃止による人材育成など、企業が地域の一員\n       として果たしている役割を具体的に確認することができた。あわせて、黒部市\n       が展開する雇用・定住施策についても調査を行った。\n\n       （１）地域社会と共生する「まちづくり」と産業観光の推進\n           YKK AP株式会社は、「他人の利益を図らずして自らの繁栄はない」というYKK\n       創業者・吉田忠雄の考え方である「善の巡環」を経営理念の基盤としており、\n               「Architectural Productsで社会を幸せにする会社。」をパーパスとして掲げて\n       いる。\n       本社では、理念浸透のため各拠点・部門で実践事例を共有する「語らい会」を\n        毎年実施しており、2024年度は国内の約2,000部門すべてで実施した。理解度\n 詳 細    を深めるeラーニングには社員約12,000名が参加し、取締役と社員の対話の場\n        「車座集会」を全国40拠点で47回開催し、約470名が参加している。\n       黒部事業所では、社員寮やパッシブタウン（自然エネルギー活用型エコタウ\n       ン）など、単なる社宅や社員用施設にとどまらず、地域住民に開かれた形で居\n       住・交流空間を提供している。敷地内の豊かな植栽やアーケードは通り抜けや\n       憩いの場として地域住民が利用可能であり、街全体に自然な賑わいを創出して\n       いる。社員と市民が日常的に交わることで、地域コミュニティとの一体感が醸\n       成されている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":2,"text":"会派視察報告書\n\n\n      地元木材や木質チップを活用したバイオマスボイラーや太陽光発電の導入によ\n      り、住宅・街区全体で自然エネルギーの活用・消費抑制を行うことで、地域に\n      持続可能なエネルギー供給のモデルを示し、地域の環境負荷低減に貢献してい\n      る。\n       産業観光施設としては、YKKセンターパーク（丸屋根展示館、ふるさとの森）\n         とYKK AP技術館の2施設を運営している。「ふるさとの森」では、黒部川扇状\n       地に原生していた樹木の種子から苗木を育て、20種2万本を植樹する緑豊かな\n       公園として整備し、市民や観光客に開放している。YKK AP技術館は、2020年\n       のパーパス策定を機に開設された施設であり、1959年にアメリカから輸入した\n      最新鋭のアルミ押出機を展示するなど、建材事業の創業時の工場を取り壊さず\n      展示館へリノベーションしたものである。これらの施設を通じ、企業活動が地\n      域の学びや交流の機会に直結している。\n       さらに2024年度は、ハーバード大学デザイン大学院（GSD）が黒部市で行った\n       実地授業を支援し、同社社員8名がアソシエイトメンバーとして参加し、GSD\n       の学生11名とともに黒部川扇状地の水資源とランドスケープについて学びを深\n      めている。\n\n      （２）防災・環境対策とスマート化\n       ＜大規模災害時の事業継続計画（BCP）について＞\n詳 細\n\n      本社は、製造・物流拠点の災害リスクに対して以下の施策を実施している。\n       2024年4月にCLO（最高ロジスティクス責任者）の役職を設けた。2024年9月に\n       はトラック予約受付システムを全国の製造・物流拠点30カ所に導入し、同年10\n       月に「荷待ち・荷役時間2時間以内」という目標をすべての拠点で100％達成し\n      ている。\n      物流DXの推進により、トラックの位置情報、交通・天候情報、製品・顧客情報\n      を一元的に管理し、遅延や寸断が予想される時点で事前に迂回経路を指示する\n      ことで、製品配送の確実性を向上させている。チャット機能やエリアごとの輸\n       送状況報告、SNS連携による気象・災害情報の集約を実現している。\n       スマートファクトリー化を推進し、2024年度を目途に黒部越湖製造所などの生\n       産拠点を無人化・自動化する。ロボットやAI、5G技術を活用し製造・点検工程\n      の異常検知を実現するほか、バーチャルファクトリーによる遠隔監視・模擬運\n      用も推進中である。\n       なお、国内外の全拠点でBCPの策定を完了している。2024年度は首都直下地震\n      や南海トラフ地震を想定した訓練を実施しており、黒部は首都圏被災時に現地\n      対策本部の代行拠点と位置づけられ、黒部と首都圏の連携訓練が行われてい\n      る。避難訓練の対象に、トラックのドライバーや食堂に勤務するスタッフな\n      ど、外部の協力会社まで含めた実効性のある訓練のあり方が進められている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":3,"text":"会派視察報告書\n\n\n      ＜環境負荷軽減への取り組みについて＞\n\n\n         YKK APは「Evolution 2030」及び中期環境事業計画に基づき、製品・ものづく\n      り・サプライチェーン全体で環境負荷軽減に取り組んでいる。\n      気候変動対策として、再生可能エネルギー導入を拡大している。黒部製造所に\n       は大規模蓄電池を導入し、国内外11拠点に合計16,200kWの太陽光発電を実現\n        している。2024年度の導入量は2021年度比で9倍であり、CO2排出量を12,000t\n       削減した。高断熱住宅窓の販売においても、例えばAPW 651トリプルガラス木\n       製窓により使用時CO2を削減でき、商品使用時のCO2削減貢献量は2024年度に\n        2020年度比175％を達成している（2028年度目標は220％）。\n      資源循環・リサイクルについては、アルミ再生材活用、樹脂リサイクル、廃棄\n       物ゼロエミッション等に取り組んでいる。社内リサイクル率はすでに100％を達\n       成し、四国製造所では2024年度末にリサイクルアルミ使用比率が80％に到達す\n      る予定である。富山大学を中心とした「富山資源循環社会モデルの創成」に幹\n       事企業として参画し、2024年4月からは東北大学とも共同研究講座を開講して\n      いる。\n      水保全と生物多様性保全については、水使用効率化、多段利用、排水管理強化\n       により地域コミュニティへの環境負荷を軽減している。2024年10月、内閣官房\n       水循環政策本部の「水循環ACTIVE企業」に認証された。各拠点で植樹や社会貢詳 細\n       献活動（2024年度217件）を展開し生物多様性保全に貢献している。\n\n      （３）企業の人材育成と地元雇用の創出\n\n\n       YKKグループでは、年齢や性別、学歴などにとらわれず、「自律と共生」の考\n      えをもとに、社員一人ひとりが十分に力を発揮できる制度や環境づくりを進め\n      ている。めざす姿は、一本一本の木が独立しながら森林を形成するように、一\n      人ひとりが「経営者」という意識を持ち、全員が手を携えて一緒に大きく育つ\n      「森林集団」である。\n      人材戦略については、①働きやすい職場環境の実現、②社員への投資、③成長\n      機会の提供、④雇用を生み出す経営、の4つの観点から施策を実行し、多様な人\n      材に選ばれる会社をめざしている。\n       具体的施策として、2021年度に定年を廃止した。意欲と能力のある社員が知見\n      や経験を活かし続けられるようにするとともに、ベテラン社員の技術・ノウハ\n      ウの次世代への継承を図っている。\n        2024年5月、企業内大学「YKK AP工科大学（APテック）」を開校した。生産\n       技術・生産管理・品質管理・ITの4つの専門コースを提供し、第1期生として37\n      名が受講している。また同月、ロボット活用人材の育成を目的としたロボット\n       スクールを開所し、2024年度は45名が受講している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":4,"text":"会派視察報告書\n\n\n       施工技術の人材育成については、2013年度から施工協力会と共同で「施工技能\n       修練伝承塾」を開講しており、2024年4月には第2拠点として埼玉工場に埼玉塾\n       を開講した。施工技術研修所「DO SPACE」を国内4拠点で運営しており、\n        2024年10月には三重工場内に「DO SPACE 三重」を新設した。\n       職場環境整備については、2024年度の環境設備投資は約16億円で、トイレ・休\n       憩室・食堂・更衣室等を改善した（2025年度は約19億8千万円を計画）。2024\n詳 細\n      年度からリフレッシュ休暇制度（特別有給5日間）を導入し、初年度は対象者の\n       約7割が利用した。\n       国内製造拠点では約400のサークルが小集団活動を実施し、毎年発表会を開催\n      している。\n        なお、2024年度のYKK APの人的資本は、国内従業員13,337名、海外従業員\n        4,915名（海外出向93名）である。\n\n      伊勢 健一\n      パッシブタウンや社員寮が地域住民に開かれ、植栽やアーケードが通り抜けや\n      憩いの場となっている点に感銘を受けた。企業の敷地を閉ざさず地域の生活空\n      間として共有することが、結果として街の賑わいと定住につながっている。大\n      崎市においても、企業立地を雇用の場としてのみ捉えるのではなく、まちの空\n      間をともにつくる主体として位置づける発想が必要である。\n\n      後藤 錦信\n       YKKセンターパークの「ふるさとの森」では、黒部川扇状地に原生していた樹\n       木の種子から苗木を育て、20種2万本を植樹していた。また技術館では創業時\n      の工場を取り壊さず展示館として再生していた。企業が自然と歴史を保存し市\n      民に開放する姿勢は、地域資源を次代へ引き継ぐ営みそのものであり、本市に\n      おいても学ぶべき点が多いと感じた。所 感\n\n      髙橋 雅博\n      黒部が首都圏被災時の現地対策本部の代行拠点と位置づけられ、実際に連携訓\n      練が行われていることを知り、地方拠点が担う国土強靭化上の役割を改めて認\n       識した。BCP体制の構築において、従業員だけでなく外部協力会社を含めた訓\n      練のあり方は、本市においても参考になる優れた事例である。\n\n      川合 明弘\n       2021年度の定年廃止や企業内大学「APテック」の開校など、人材を「確保す\n      る」から「育て、活かし続ける」へと軸足を移す姿勢は、人口減少下にある本\n      市にとっても重要な示唆である。企業内大学により、製造現場の技術と経営知\n      識を一貫して学ぶ環境が提供されることで、中核人材の育成と定着が実現して\n      いる。このモデルは地域産業の持続性を高める重要な視点である。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":5,"text":"会派視察報告書\n\n\n      （１）視察の成果\n          YKK AP株式会社は、黒部市において製造拠点としての機能を果たすにとどまら\n      ず、地域と共生する街づくりを実践していた。社員寮やパッシブタウンの地域\n      開放、創業時の工場を保存活用した技術館の無料公開、在来種による「ふるさ\n      との森」の整備と開放など、企業活動が地域の暮らしや学びに直接つながって\n      いる。\n       また、物流DXを核としたBCP体制の構築、環境目標の数値管理、定年の廃止や\n      企業内大学の開校といった人材戦略は、いずれも具体的な数値と実績を伴って\n       示された。YKKは黒部市の経済、まちづくり、環境施策に深く関わる存在であ\n      り、市の持続的発展や地域住民の生活に密接に関わっている。黒部市にとって\n       YKKは「なくてはならない存在」であることが確認された。\n\n\n      （２）今後の展望と政策提言\n       大崎市は面積797k㎡、人口約12万人を擁し、黒部市とは規模も産業構造も異な\n      る。しかしながら、人口減少と労働力不足、地域産業の維持という課題は共通\n      である。\n      企業の施設や活動が「企業のもの」に閉じず地域に開かれていることが、結果\n      として企業自身の人材確保や地域からの信頼につながっている点は、本市にお\n総 括      いても応用可能な視点である。\n\n\n      ① 地域の中核企業との連携によるまちづくりの推進\n      企業の施設・活動を地域に開かれたものとしていくための行政としての支援や\n      環境整備、及び産業観光資源としての活用について検討すべきである。あわせ\n      て、市内企業の歴史や技術を市民が学べる機会の創出を図るべきである。\n      ② 防災体制の強化\n      市内事業者との災害時の情報共有体制の構築を検討すべきである。また、防災\n      訓練の対象に、事業所の従業員のみならず、物流事業者や協力会社を含めた実\n      効性のある訓練のあり方を検討すべきである。\n      ③ 環境施策の数値管理と公共施設の断熱化\n      環境目標について、長期目標のみならず中間年度の数値指標を設定し、実績を\n      公表する仕組みを整えるべきである。また、公共施設等における断熱化・省エ\n      ネ化を計画的に推進すべきである。\n      ④ 人材確保・定着施策の充実\n      自治体・ハローワーク・事業者の三者連携による一体的な施策展開について検\n      討するとともに、本市における移住・定住支援策と雇用施策の連動を強化すべ\n      きである。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":6,"text":"会派視察報告書\n\n\n会 派 名   大地\n\n視 察 日   令和８年８月５日（水）\n\n視 察 者   伊勢健一 後藤錦信 川合明弘 高橋雅博\n\n視 察 先   富山県黒部市 黒部市民病院\n\n視察項目   黒部市民病院の現状と課題について\n       大崎市と黒部市は姉妹都市であり、両市の病院事業は地域医療の維持に不可欠\n選定理由   である。黒部市民病院の現状と課題、地域医療連携の取組を把握し、大崎市民\n       病院との連携強化に向けた示唆を得るため視察を選定した。\n       【黒部市民病院】病院長 辻宏和 氏、副院長（地域医療支援部主任部長・外科\n       部長・乳腺外科部長・がん診療センター所長・入退院支援室長） 寺田逸郎\n       氏、理事（耳鼻いんこう科部長・臨床研修センター所長） 丸山裕美子 氏、看\n       護部長 渡邊和美 氏、地域医療連携室看護師長 今井知明 氏、事務局長 中嶋説 明 者\n       ひとみ 氏、総務課長 牧野恵美 氏、医事課長 浜屋香苗 氏、情報管理課長 \n       武隈渉 氏、健康管理センター課長 島﨑三紀子 氏\n\n       【黒部議会事務局】局長 神保竜 氏、議事調査課 主任 前原健志郎 氏\n        黒部市民病院は、新川医療圏（人口約10.7万人）の基幹病院として、急性期医\n       療・救急医療・周産期医療・感染症医療など幅広い機能を担っている。今回の\n       視察では、病院の歴史、病床機能、経営状況、地域医療連携室の役割、扇状地\n       ネットによる情報共有の仕組みなどについて説明を受けた。特に、人口減少と\n視察概要\n       医療需要の変化、診療報酬制度による収益構造の制約、医療機器更新に伴う財\n       政負担など、自治体病院が抱える課題が具体的に示された。また、大崎市民病\n       院との連携の可能性についても意見交換を行い、地域医療の持続に向けた課題\n       と方向性を確認した。\n       黒部市民病院は1948年に「下新川厚生病院」として開院し、地域の医療需要に\n       応じて病床数・診療科・建物整備を進め、現在は一般363床、結核5床、感染症\n       4床の計372床を有する地域中核病院である。新川医療圏では、がん・脳卒中・\n       心筋梗塞・糖尿病・精神疾患の5疾病、救急・災害・へき地・周産期・小児医療\n        の6事業の多くを担い、特に救急医療（2.5次救急）、地域周産期母子医療セン\n       ター、第二種感染症指定医療機関など、圏域内で唯一の機能も多い。\n 詳 細\n        経営面では、令和7年度の医業収益は110.8億円、修正医業収支比率は90.2％と\n       県内自治体病院の中でトップの収益力であるにもかかわらず黒字化することが\n       できなかったということで、診療報酬は公定価格であり、物価高や人件費上昇\n        に対して価格転嫁ができない構造的課題がある。職員給与費は約61.5億円、材\n        料費は約30.3億円で、医療DXや効率化を進めても急性期医療の特性上、人材確\n       保と医療材料費の増加は避けられないとの説明があった。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":7,"text":"会派視察報告書\n\n\n       また、CT・MRI・リニアック・手術支援ロボットなど高度医療機器の更新費用\n       は減価償却費として年間約9.7億円を占め、更新を先送りすると医療安全や災害\n      対応力の低下につながるとされた。\n      地域医療連携室「フレンディー」は、紹介・逆紹介、退院調整、在宅支援、ク\n       リニカルパス運用などを担い、令和7年度の紹介患者数は6,513人、逆紹介は\n       7,598人で逆紹介率は83.6％と高い。医療機器共同利用は年間994件で、地域の\n      診療所・病院との連携が進んでいる。大腿骨頚部骨折・脳卒中・糖尿病などの\n詳 細    地域連携クリニカルパスは、急性期から回復期、在宅まで一貫した医療提供を\n      可能にしている。\n      さらに、扇状地ネットは黒部市民病院の電子カルテ情報を地域医療機関が閲覧\n      できる仕組みで、紹介状だけでは伝わらない検査結果や画像情報を共有でき\n       る。2025年にはあさひ総合病院・富山労災病院とも接続し、医療圏一体のネッ\n      トワークとして機能拡大が進んでいる。\n      質疑では、大崎市民病院との連携、地域医療連携の拡充などについて意見交換\n      を行い、自治体病院が抱える共通課題を確認した。\n\n      伊勢健一\n      黒部市民病院が地域医療の中心として多岐にわたる機能を担っていることを実\n      感した。特に扇状地ネットによる情報共有は、医療の質向上に大きく寄与して\n      いると感じた。大崎市民病院でも参考となる取組が多く、今後の連携強化に向\n      けて学びの多い視察であった。\n\n      後藤錦信\n      人口減少と医療需要の変化の中で、自治体病院が抱える課題は大崎市と共通し\n      ている。黒部市民病院の地域連携やクリニカルパスの運用は、地域包括ケアの\n      実践として非常に有効であり、当市でも導入可能な点が多いと感じた。\n所 感\n      川合明弘\n      紹介・逆紹介の高い実績や在宅支援の体制など、地域医療連携室の役割が非常\n      に大きいことを理解した。医療機器共同利用や情報共有の仕組みは、地域医療\n      の効率化に寄与しており、大崎市でも検討すべき取組であると感じた。\n\n      高橋雅博\n      高度急性期医療を維持するための設備投資や人材確保の重要性を改めて認識し\n      た。黒部市民病院の経営努力と地域連携の仕組みは大崎市民病院にとっても参\n      考となる。姉妹都市として、医療分野での協力関係をさらに深める必要性を感\n      じた。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":8,"text":"会派視察報告書\n\n\n      今回の視察を通じ、黒部市民病院が新川医療圏の基幹病院として急性期医療・\n      救急医療・周産期医療・感染症医療など多様な機能を担い、地域医療を支える\n      重要な役割を果たしていることを確認した。人口減少、診療報酬制度、医療機\n      器更新、人材確保など自治体病院が直面する課題は大崎市民病院とも共通して\n      おり、地域医療の持続には行政と病院が一体となった取り組みが不可欠であ\n      る。\n      特に、扇状地ネットによる情報共有、地域連携クリニカルパスの運用、紹介・\n総 括\n      逆紹介の仕組み、在宅支援体制などは、地域包括ケアの実践として高く評価で\n      きる。これらの取組は大崎市民病院においても参考となり、地域医療連携の強\n      化に向けた具体的な施策として検討すべきである。\n      姉妹都市として、両市の病院事業が連携し、医療機器共同利用や研修交流など\n      を進めることで、地域医療の質向上と持続可能性の確保につながると考える。\n      今回の視察成果を踏まえ、議会としても地域医療の課題解決に向けた政策提言\n      を進めていく。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":9,"text":"会派視察報告書\n\n\n会 派 名   大地\n\n視 察 日   令和８年８月５日（水）\n\n視 察 者   伊勢健一 後藤錦信 髙橋雅博 川合明弘\n\n視 察 先   石川県羽咋市 合同会社のとしし団\n\n視察項目   羽咋市 獣肉処理施設 のとしし団の概要について\n\n       大崎市においても「ジビエの郷おおさき」でジビエ事業を展開しているが、羽\n選定理由   咋市の先進的な取り組みと課題解決の状況を学び、今後の販路拡大戦略や事業\n       展開の参考にするため。\n\n       合同会社のとしし団 代表 加藤普司氏\n説 明 者\n       合同会社のとしし団 事務 髙田守彦氏\n\n        羽咋市では、イノシシによる農地被害の急増（平成24年から5年間で年間300頭\n       超の捕獲実績）に対応するため、平成27年に「のとしし大作戦」と銘打ったジ\n       ビエ事業を開始した。合同会社のとしし団は、市と出資者による合同会社形態\n       で運営されており、捕獲されたイノシシを食肉処理し、安全で安心な食肉とし\n視察概要\n       て販売するとともに、皮などの副産物を活用した特産化を目指している。特\n       に、飲食店からのニーズに応えた販売戦略や、これまで産業廃棄物とされてき\n       たイノシシを貴重な資源として余すところなく活用する考え方は、本市のジビ\n       エ事業の展開においても参考になる取り組みである。\n\n       （１）羽咋市とイノシシ問題の歴史的背景\n       羽咋市では、古くからイノシシと鹿の被害が課題となっている。安政の書上と\n       いう古文書の中で、これらの動物が畑を荒らす被害が訴えられており、明和9年\n       （1772年）には加賀藩より「悪事に使用しないこと」「又貸ししないこと」を\n       条件に、口郡（羽咋郡市・鹿島郡）に４挺の鉄砲が貸し出され、イノシシ退治\n       に取り組んでいた。その６年後にはイノシシと鹿の皮が300枚売りに出された\n 詳 細\n       との記録もあることから、当時は相当数のイノシシやシカが生息していたこと\n       が伺える。\n       明治から大正にかけて一度絶滅したとされるイノシシは、平成になり再び猛威\n       を振るうようになった。羽咋市で増加したのはつい最近のことで、市内では平\n        成24年にしばらくぶりにイノシシ1頭が捕獲されてから、わずか5年で年間300\n       頭を超えるイノシシが捕獲されるまでに至っている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":10,"text":"会派視察報告書\n\n\n      （２）のとしし大作戦の開始と事業概要\n      これまで、羽咋市では農家がイノシシを捕獲した場合、捕獲奨励金を支払うこ\n      とでご苦労に報いてきた。しかし、捕獲したイノシシをゴミとして扱うこと\n      は、捕獲した方の大きなストレスになることから、捕獲したイノシシを廃棄す\n      るのではなく、貴重な資源として活用することで、人間とイノシシが共存でき\n       ないかという思いから、平成27年に「のとしし大作戦」として事業を開始し\n      た。\n       この事業は、平成27年10月14日に食肉処理業の許可を得てスタートした。市に\n      も出資してもらい、合同会社の形態をとっており、安全で安心な食肉を生産\n      し、野生の味を楽しんでもらうことはもちろんのこと、これまで産業廃棄物と\n      して処分されることの多い皮についても特産化の試みを始めている。いのちの\n      営みに感謝をしつつ、貴重な資源として余すところなく活用していくことが、\n      のとしし大作戦が目指すところである。\n\n      （３）質疑応答\n      ◆運営形態について\n      問：運営形態は、指定管理のような形か？\n      答：羽咋市にも出資してもらい、合同会社の形態をとっている。\n      ◆販売先と売上について\n      問：主な販売先は？年間の売り上げは？\n詳 細\n      答：主な販売先はジビエ料理を専門とする飲食店である。地元というよりは、\n      関東圏などイノシシがいない地域がほとんどである。また、京都の丹波篠山な\n      どのジビエよりも価格的に購入しやすく取引先に卸している。売り上げは、豚\n       コレラの影響や新型コロナウイルスの影響で上下する部分があるが、年間1000\n      万円ほどである。\n      ◆主な販売先との関係性について\n      問：主な販売先との関係性は？\n      答：この事業は全国的にも早い段階でジビエ事業をスタートしており、新たな\n      顧客からのニーズもあるが、古くからの顧客への対応を大事にしながら、ビジ\n      ネスを展開している。\n      ◆捕獲後の連携体制について\n      問：イノシシを捕獲後の狩猟をする方との連携体制は？\n      答：職員が現場に出向き、ジビエに利用できるかどうかを確認した上で、施設\n      まで搬入する体制をとっている。\n\n      ◆骨の炭化処理について\n      問：イノシシの骨などを炭化処理して肥料にする仕組みがパンフレットにある\n      が、現状は？\n      答：生肉になる部分などを除くと、炭化処理する量が少なく、コスト面を考慮\n      して、現在は稼働していない。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":11,"text":"会派視察報告書\n\n\n      伊勢健一\n      本市においても、ジビエの郷おおさきにおいてジビエ事業を展開しているが、\n      合同会社のとしし団での取り組みは参考になる部分が多くある。おおさきジビ\n       エにおいても、2026年1月からホームページにおいて業務用ジビエのご案内\n      ページを開設しているが、飲食店や旅館などへの販路開拓が重要であると感じ\n      た。特に飲食店からの具体的なニーズ（脂の多い部位が欲しいなど）に応えた\n      販売戦略は学ぶべき点が多い。\n\n      後藤錦信\n      のとしし大作戦は、農家のストレス軽減と地域資源の活用という課題解決型の\n      アプローチが印象的である。捕獲したイノシシを「廃棄物」から「貴重な資\n      源」へと転換させる発想は、他の地域資源の活用においても応用できると思わ\n      れる。今後、本市におけるジビエ事業の展開においても、単なる利益追求では\n      なく、地域課題の解決と住民満足度の向上を同時に目指す視点が重要であると\n      感じた。\n所 感\n\n      髙橋雅博\n       ジビエ事業が全国で広がりを見せている中で、のとしし団の年間売上100万円\n      という現状は、事業としての採算性という課題を明らかにしている。豚熱やコ\n      ロナウイルスなどの外部要因の影響を受けやすい事業体質と、仕入れである捕\n      獲イノシシ確保の難しさは、今後の本市事業においても対応が必要と考える。\n      同時に、関東圏など消費地での販路開拓という経営戦略は参考になる。\n\n      川合明弘\n      本市のジビエの郷おおさきと異なり、のとしし団は販売先をほぼ市外の飲食店\n      に限定し、関東圏や関西圏などの消費地への販路開拓に注力している点が特徴\n      的である。市内飲食店での販売も大切だが、より大きな市場への展開が事業の\n      成長には不可欠であることを学んだ。また、顧客ニーズに迅速に応じた製品化\n      （部位の選別）は、ジビエ事業における競争力確保の重要なポイントと考え\n      る。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":12,"text":"会派視察報告書\n\n\n\n      羽咋市の「のとしし大作戦」は、農業被害という地域課題をジビエ産業化に\n      よって解決し、同時に農家の負担軽減と地域活性化を実現する先進的な取り組\n      みである。特に、合同会社形態による官民連携、飲食店からの具体的ニーズへ\n      の対応、そして捕獲から処理・販売まで一貫した体制構築は、本市のジビエ事\n      業にとって十分な参考価値がある。\n      今後の本市の課題としては、第一にジビエの郷おおさきの販路拡大であり、地\n      元市内での消費促進に加えて、関東圏など消費地での営業活動の強化が必要で\n総 括    ある。第二に、捕獲イノシシの安定確保であり、市内の狩猟関係者との連携体\n      制の整備と、捕獲者への支援策の充実が重要である。第三に、事業の採算性の\n      確保であり、のとしし団の現状からも、ジビエ事業は外部要因の影響を受けや\n      すいため、複数年度での経営見通しと、複数の収入源の確保（副産物の活用な\n      ど）が求められる。\n      本視察で得た知見を踏まえ、ジビエの郷おおさきの経営改善と事業拡大に向け\n      た施策を検討し、本市の地域課題解決と地域活性化に貢献するジビエ産業の構\n      築を進めていくことを期待する。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":13,"text":"会派視察報告書\n\n\n会 派 名   大地\n\n視 察 日   令和８年８月６日（木）\n\n視 察 者   伊勢健一 後藤錦信 髙橋雅博 川合明弘\n\n視 察 先   石川県羽咋市 羽咋市役所\n\n視察項目   世界農業遺産「能登の里山里海」の取り組みについて\n       同じ認定地域である羽咋市を視察し、認定後の取り組み状況と地域住民の関わ\n選定理由\n       りを学び、本市の取り組みに活かすため。\n       羽咋市議会議長 酒井一人氏\n       産業建設部農林水産課課長補佐 金森 章氏\n説 明 者\n       トキ共生室主任 井戸孝洋氏\n       議会事務局議事調査係係長 澤田朋子氏\n\n        羽咋市は石川県能登半島の基部西側に位置し、人口19,187人（令和8年8月1\n        日）、面積81.84㎢の市である。2011年6月、新潟県佐渡市とともに日本で初め\n        て世界農業遺産「能登の里山里海」に認定された。棚田178ha、ため池による\n視察概要\n       伝統的水管理システム、トキの本州初放鳥地、令和7年7月1日にオーガニックビ\n       レッジ宣言を行うなど、世界農業遺産の価値を継承・発展させている。また、\n       「はくい式自然栽培」に取り組み、令和7年度は36人の農家が参加している。\n\n       １．世界農業遺産「能登の里山里海」\n        平成22年11月30日、能登地域の4市5町が推進協議会を設立し、同年12月17日\n       に石川県、国際連合大学、金沢大学の推薦を受けて、農林水産省の協力の下、\n        「能登の里山里海」の世界農業遺産認定をFAOに申請した。平成23年6月11\n       日、新潟県佐渡市の「トキと共生する佐渡里山」とともに日本で初めて世界農\n       業遺産として認定された。\n       評価された点は、\n 詳 細    ①生物多様性が守られた伝統的な農林漁法と土地利用\n       ②里山里海に育まれた多様な生物資源\n       ③優れた里山景観\n       ④伝えていくべき伝統的な技術、\n       ⑤長い歴史の中で育まれた農耕にまつわる文化祭礼\n       ⑥里山里海の利用保全活動の6点である。能登地域全体の農林水産業とそれに関\n       連した人々の営みすべてが評価対象であり、地域住民の意識変化が地域活性化\n       につながっている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":14,"text":"会派視察報告書\n\n\n\n      ２．羽咋市の特徴と取り組み\n       （１）石川県最大の棚田面積：令和4年2月14日「つなぐ棚田遺産～ふるさとの\n       誇りを未来へ～」に選定された178haの棚田。2005年、ローマ教皇に献上した\n      ことで「神子原米」がブランド化に成功し、「神子原くわい」などの関連商品\n      を展開している。中山間地域等直接支払制度の活用や鳥獣被害対策に取り組ん\n      でおり、今後の担い手確保が課題である。\n      （２）ため池を利用した農業：能登半島は平地が少なく河川が短いため、ため\n      池を活用した稲作が営まれてきた。ため池の持つ生物多様性と共同管理による\n      コミュニティ構築のため、環境保全型農業に取り組み、羽咋市みどりの食料シ\n詳 細\n      ステム戦略推進協議会の活動を通じて事業推進を行っている。\n      （３）トキ生息環境整備：令和4年度からトキの餌場環境を整備する取り組みを\n      開始。モデル地区を設置し、環境に配慮した持続可能な農業の推進に努めてい\n      る。\n      （４）自然栽培の取り組み：「健康」「安心安全」をキーワードに、農薬・肥\n       料を使用しない自然栽培に取り組んでいる。JAと協働し「のと里山農業塾」を\n       開講し、自然栽培部会を設立。令和7年度実績は、水稲17.6ha、野菜3.5ha、穀\n       類4.7haで36人の農家が参加。営農支援、居住支援、普及支援の3つの支援策を\n      実施し、学校給食への提供やイベント開催で支援している。\n\n      ３．質疑応答\n       Q 自然栽培における市とJAの関わり、農家の収入確保と栽培面積拡大、オー\n      ナー制度の現状と観光への効果について\n       A 市が中心となっており、JAでは経営の視点もあるため課題が残っている。\n      収入面でやっていけないという農家の声もあり、自然栽培だけではハードルが\n      高く、有機農業としての取り組みも必要と考えている。オーナー制度は羽咋市\n詳 細    では実施していないが、これらの取り組みは少なからず観光面への効果となっ\n      ている。\n      Q 大崎市の「鳴子のプロジェクト」のような消費者との直接取引の例がある\n      か\n       A 自然栽培はJAが買い取っており、消費者に直接販売している例は「神子原\n      米」が直売所等で販売している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"f6ba57ae872dfde8","year":2026,"faction":"大地","kind":"activity","title":"報告書(PDFファイル:1.2MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/daichi_20260804_06.pdf","page":15,"text":"会派視察報告書\n\n\n      【伊勢健一】\n       本市も2017年12月に「大崎耕土」として世界農業遺産に認定されている。羽咋\n      市の先進事例から、地域住民の一体感形成とブランド化の重要性を学んだ。申\n      請・認定時に発揮した熱量を再現し、市民全体で世界農業遺産の価値を共有す\n      ることが今後の課題である。\n      【髙橋雅博】\n      羽咋市では棚田やため池が治水としての防災機能に役立っていることが印象的\n      だった。本市の水管理システムも、森林・河川・水田のそれぞれの機能に着目\n      し、流域治水の取り組みと世界農業遺産の価値を統合させることで、市民の理\n      解と参加を促すことができると感じた。\n所 感\n      【川合明弘】\n      羽咋市がトキの放鳥に取り組み、市民の意識が変化し地域活性化につながって\n      いる点に感銘を受けた。伝統文化を大切にしながら新しい時代への適応を進め\n      ることで地域の持続可能性が生まれる。本市も世界農業遺産「大崎耕土」を地\n      域活性化のツールとして活用することが重要である。\n      【後藤錦信】\n      羽咋市の事例から、世界農業遺産認定地として同じ課題に対応する先進事例を\n      学ぶことができた。伝統的な農業システムの継承と現代的課題への対応を両立\n      させるには、市民全体の意識醸成が不可欠である。本市も申請・認定時の熱量\n      を再現し、地域一体となって価値を次世代に継承する必要がある。\n\n\n      本視察を通じ、世界農業遺産認定地として羽咋市の先進的な取り組みから多く\n      の学びを得た。特に、棚田やため池という伝統的農業インフラと地域コミュニ\n      ティの連携、「はくい式自然栽培」による高付加価値農産物の創出、トキの生\n      息環境整備を通じた生物多様性の保全と地域活性化など、地域資源を活かした\n      持続可能な農業振興の具体的事例を確認できた。\n      本市の「大崎耕土」として認定された伝統的水管理システムは、単なる農業遺\n      産としての価値にとどまらず、現代の防災・減災、流域治水という観点からも\n      改めて位置付け直すべき価値がある。また、羽咋市では棚田やため池が治水と\n総 括    しての防災機能に役立っており、本市も森林・河川・水田のそれぞれの機能に\n      着目し、流域治水の取り組みにも世界農業遺産の認定を位置付けることが重要\n      である。\n      さらに、農業の担い手確保が全国的な課題となる中、移住・定住の支援と組み\n      合わせた営農環境の整備、農産物のブランド化と販売ルートの確保、学校給食\n      への地域農産物の活用など、総合的なアプローチが不可欠である。羽咋市の事\n      例を参考としながら、本市においても地域住民の一体感を醸成し、世界農業遺\n      産「大崎耕土」の価値を次世代に継承していくことが今後の重要な課題であ\n      る。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":1,"text":"会派視察報告書\n\n\n会 派 名   志創会\n\n視 察 日   令和８年７月２３日（木）\n\n視 察 者   早坂憂、荒井純、五島啓太\n\n視 察 先   鹿児島県大崎町\n\n視察項目   行政と特産品組合による販路拡大と地域活性化の取組について\n       行政と民間が各地域でのイベント出展で連携をしてシティプロモーションを\n選定理由   行っているだけではなく、ふるさと納税の返礼品開発を幅広く行い、相当な寄\n       付額となっているため、その仕組みと取組を学ぶべく選定した。\n\n       大崎町役場商工観光課長　上野明仁氏、大崎町役場商工観光課商工振興係長　\n       嶽野清人氏、大崎町ふるさと特産品振興事業協同組合理事長　山野勝広氏、大\n説 明 者\n       崎町ふるさと特産品振興事業協同組合役員　坂元健太郎氏、株式会社JTBふる\n       さと納税開発事業部大崎サテライトオフィス　脇田健哉氏\n\n                 1. 組合設立の背景と目的\n       優れた農産品はあるが、ブランド化や価値創出に至っていなかった。また、行\n       政主導の施策では予算手続きなどの制限により、迅速な意思決定や展開に時間\n       がかかるという課題があった。\n        2015年にふるさと納税額で全国町村部1位を獲得したことを機に、「チーム大\n        崎」として事業者が連携。この機動的な組織を恒久化するため、2019年6月に\n       組合を設立。\n\n                 2. 運営体制と役割分担\n         ◾ 行政の役割\n視察概要\n       ・仕組み作り、ノウハウの提供、予算確保。\n       ・シティプロモーションとしての出店料補助などの支援。\n         ◾ 組合の役割\n       ・特産品の販売・PR、商品開発。\n       ・事業者同士の連携による自由な発想での新商品創出。\n       ・機動的なイベント出店および販売活動。\n         ◾ 資金源\n        ・設立当初2年間は運営補助金（年200万円）があったが、3年目以降は売上手\n       数料や組合員の出資金による自己資金で運営している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":2,"text":"会派視察報告書\n\n\n\n                 3. 具体的な取り組みと成果\n       ・県内外のイベントに積極的に出店し、物販のみならずシティプロモーション\n       を通じて関係人口を創出。\n       ・事務局による一括配送・梱包体制の構築により、個別の送料コストを大幅に\n       削減。\n       ・ふるさと納税型のクラウドファンディングを活用。寄付金を集め、その一部\n       を開発費として補助する仕組みで、毎年新しい商品を開発している。\n       ・和牛マンゴーカレー、マンゴーアイス、焼酎と地元の飴を掛け合わせた商品視察概要\n       など、事業者間のコラボレーション商品を展開。\n       ・利益を「リサイクル未来奨学金」などに充て、次世代の人材育成や環境保全\n       に還元する循環型地域社会を目指している。\n\n                 4. 定量的な成果と評価\n        ・関東圏での認知度調査において、過去最高となる20.9%を記録。\n       ・特産品購入者が農業体験に訪れ、そこから地元小学校での職業授業へ繋がる\n       などの波及効果が見られる。\n\n             Q1. 組織として組合を設立した根本的な理由は？\n       きっかけは平成13年のリサイクル政策。行政職員が各集落を回り分別を説明し\n       たことで、行政と住民の距離が縮まった経験がベースにある。また同一事業者\n       への助成金が1～2回までという制約もあり、組織化でカバーしようとした。品\n       川・夢さん橋の先行事例からも学び、「街全体の商品を売る」という発想から\n       「チーム大崎」が生まれた。\n\n             Q2. 出店（県内5回・県外8回）の費用はすべて組合負担か？\n       一部組合負担だが、県外出店は当初2カ年シティプロモーション助成金があっ\n       た。県内は自己収益＋各種助成（1/2補助等）を組み合わせて運営。\n\n 詳 細       Q3. 商工会との役割分担は？\n       組合員は商工会にも所属。組合は町外へのPR部隊、商工会は地域内の商工振興\n       が主担当。\n\n             Q4. 行政職員は組合員として加入しているか？\n       加入していない。行政と組合は別組織としてタッグを組み、事務局のみ行政が\n       担当。当初は地域おこし協力隊活用も検討したが実現しなかった。\n\n             Q5. 町内での組合活動の認知度は？\n       正式な調査は未実施。ふるさと納税1位獲得後のテレビ報道やコラボ商品の受賞\n       歴（地銀アワード等）、新聞掲載などから、一定の認知度はあると推測してい\n       る。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":3,"text":"会派視察報告書\n\n            Q6. 中間事業者（JTB）の役割は？\n      ①受発注管理・発送　②寄付者情報管理　③返礼品開発　④マーケティング施\n       策、の4本柱。\n\n            Q7. JTBとして組合の存在をどう感じるか？\n      外部から地域に入る中間事業者にとって、組合という窓口があることで地元事\n      業者と接点が持ちやすく、非常に助かっている。\n\n            Q8. JTBの全国的な取り組み実績は？\n       中間事業者事業を始めて約13年、現在大阪本部200人体制。全国約120自治体を\n       担当し、大崎町とは11年の付き合い。全国10拠点にサテライトあり。\n\n            Q9. 旅行クーポンのような対応も可能か？\n      可能。大崎町ではあまり活用されていないが、宮城県で言うと仙台支店等を通\n      じて観光施策のソリューション提供も行っている。\n\n            Q10. 現在の売れ筋商品ベスト3～5は？\n       1位うなぎ、2位黒毛和牛、3位肉まん（神楽坂の老舗中華店）。うなぎが牽引\n      役となり、他商品への波及効果を生んでいる。\n\n詳 細    Q11.「チーム大崎」結成当初は何社から始まったか？\n       最初は3～4社程度、組合設立時に23事業者、現在は30事業者。\n\n            Q12. 商品開発で事業者間トラブルは起きなかったか？\n      設立当初はふるさと納税ルールが緩やかで、事業者間の自由な連携から新商品\n      （梅酒、北上市との共同焼酎など）が生まれた。総務省基準が厳格化した現在\n      はより制約がある。\n\n            Q13. JTBは各事業者との個別面談を行っているか？\n      本来は行いたいが時間的制約があり、上位事業者・サテライト拠点中心の対応\n      になっている点は反省点である。\n\n            Q14. 組合の資金運用（供託金）はどうなっているか？\n      全事業者を組合員化する案は負担が大きいため見送り、任意加入制でスター\n      ト。集めた資金は供託金として積み立て、活動費には使わず退会時に返還する\n      仕組み。\n\n            Q15. うなぎを安定供給できる背景は？\n      町内に「大崎町うなぎ加工組合」という誘致企業があり、生産体制が確立。昭\n       和40年代のデンプン工場跡地（池）を活用してうなぎ養殖が始まった歴史的経\n      緯がある。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":4,"text":"会派視察報告書\n\n\n\n      早坂　憂\n      我が大崎市では民間と行政との連携に課題があると感じていたため、今回の視\n      察に至ったが、大崎町と特産品組合との連携はまさに理想の取り組みであり、\n      非常に羨ましく感じたのが正直なところだった。その基盤となったのがリサイ\n      クル事業であり、地域住民との繰り返しの対話を通じて信頼関係を築き、特産\n      品組合の設立に繋がった話は非常に興味深かった。視察調査の最中も、終始行\n      政職員と特産品組合の方々とのやりとりもあり、その雰囲気の良さから、普段\n      から信頼関係が厚い事も伝わってきた。事業の内容や仕組みが重要なのではな\n      い。いかに関わる人間が熱意を持って取り組むか、これが大切なのだと改めて\n      認識した。返礼品の開発についても、多くの方々が関わり、コンスタントに新\n      商品を開発する事で信頼関係が強固になると共に、「うなぎともう一品」が選\n      ばれて寄付額の増加につながっている事も頷けた。\n\n所 感\n      五島　啓太\n      ふるさと納税を単なる寄附集めにとどめず、地域の稼ぐ力、官民の信頼関係、\n      そして次世代育成へとつなげる先進的な循環モデルを深く学ぶことができまし\n      た。大崎市においては、自主財源の確保や地域経済の活性化に向けて、ふるさ\n      と納税事業をこれまで以上に強力かつ着実に推進していく必要性を痛感してお\n      ります。その中で特に印象的だったのは、行政と事業者の明確な役割分担と、\n      自走する「特産品振興協同組合」の存在です。行政が制度設計や基盤整備に徹\n      し、民間が主体となって機動的に異業種マッチングや新商品開発、外に向けた\n      PR・販売を行う仕組みは、大崎市が直面する「民間連携の不足」を打破するた\n      めの大きな鍵となります。また、事業者の枠を超えて地域全体で商品を売り込\n       む姿勢や、中間事業者（JTB等）との的確なマーケティング連携、さらには得\n      られた成果を食育や未来奨学金など次世代への投資へと還元する「循環型地域\n      経営」の思想には強く共感いたしました。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":5,"text":"会派視察報告書\n\n\n      荒井　純\n      今回の視察を通じて最も重要な学びとなったのは、リサイクル事業や地域振興\n      策の成果そのものではなく、その基盤にある行政と住民との継続的な対話と信\n      頼関係である。大崎町のリサイクル事業は、行政が一方的に導入し、住民に協\n      力を求める手法によって実現したものではない。行政職員が各集落へ繰り返し\n      出向き、住民と直接向き合いながら、分別の必要性や具体的手法を丁寧に説明\n      し、疑問や不安に一つひとつ応えてきた。こうした地道な取組を積み重ねるこ\n      とで、住民の理解と主体的な参画が促され、地域全体でリサイクルに取り組む\n      基盤が形成されている。特に評価すべき点は、行政と住民との対話が、単なる\n      事業への協力関係にとどまらず、地域課題を共に考え、解決する協働の関係へ\n      発展している事である。その信頼関係が、住民主体の組織づくりや特産品の振\n      興など、環境分野を超えた地域活性化にも繋がっている。施策の成否は、制度\n      の内容だけではなく、その必要性を住民と共有し、共に取り組む過程によって\n所 感    大きく左右されることを改めて認識した。\n\n      また、地域資源を活用して得られた財源を、食育や奨学金など、子どもたちの\n      成長と将来を支える施策へ還元している点も注目すべきである。環境政策によ\n      る成果を地域経済の活性化に繋げ、更に次世代育成や住民生活の向上へ循環さ\n      せる仕組みは、持続可能な自治体経営の実践例として大変参考になる。大崎市\n      においても、新たな制度や施設の整備を先行させるのではなく、行政が地域に\n      出向き、住民が抱える課題や将来への不安を直接把握する姿勢を、施策形成の\n      出発点とする必要がある。特に、福祉、子育て、防災、地域コミュニティなど\n      の分野では、行政だけで課題を解決することには限界がある。住民、地域団\n      体、事業者、関係機関がそれぞれの役割を担い、継続的に連携できる仕組みづ\n      くりが不可欠である。今回の視察で得た知見を踏まえ、行政と住民との対話を\n      施策形成に反映させる仕組みや、地域資源から生み出された成果を次世代育成\n      と住民福祉へ還元する仕組みについて、民生常任委員会でも検討を深め、具体\n      的な政策提言へ繋げていきたい。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":6,"text":"会派視察報告書\n大崎市でも古川商工会議所青年部から政策提言があり、民間と行政が連携した\nふるさと納税の返礼品開発が提案されている。ふるさと納税は恒久的な財源と\nして当てにすることは出来ないが、シテイプロモーションや関係人口増加にも\n繋がるだけでなく、今回学んだように、地域活性化にも寄与する施策である。\n連携した取り組みの中で新たな化学反応が生まれ、予期しなかった成果が生ま\nれる可能性すらある。大崎町とは同じ 「 大崎 」 の名を持つ縁もあることから、\n今後の自治体間の交流にも期待したいところであり、物産交流や人的交流にも\n繋げたいと感じた視察だった。視察調査後に中野伸ー大崎町長と懇談する機会\nにも恵まれ、友好都市としての可能性について言及があった\nロ川大崎で開催\n0ロロ\nされる 「 品川夢さん橋 」 での大崎交流を更に昇華させ、 『 大崎 』 の繋がりによ\nる様 々 な交流事業に発展させたい。\n総括\n視察の様子\n\n[PDFテキスト]\n会派視察報告書\n\n\n      大崎市でも古川商工会議所青年部から政策提言があり、民間と行政が連携した\n      ふるさと納税の返礼品開発が提案されている。ふるさと納税は恒久的な財源と\n      して当てにすることは出来ないが、シティプロモーションや関係人口増加にも\n      繋がるだけでなく、今回学んだように、地域活性化にも寄与する施策である。\n      連携した取り組みの中で新たな化学反応が生まれ、予期しなかった成果が生ま\n      れる可能性すらある。大崎町とは同じ「大崎」の名を持つ縁もあることから、\n総 括\n      今後の自治体間の交流にも期待したいところであり、物産交流や人的交流にも\n      繋げたいと感じた視察だった。視察調査後に中野伸一大崎町長と懇談する機会\n      にも恵まれ、友好都市としての可能性について言及があった。品川大崎で開催\n      される「品川夢さん橋」での大崎交流を更に昇華させ、『大崎』の繋がりによ\n      る様々な交流事業に発展させたい。\n\n\n                 視 察 の 様 子","method":"windows-ocr-ja","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":7,"text":"会派視察報告書\n\n\n会 派 名   志創会\n\n視 察 日   令和８年７月２４日（金）\n\n視 察 者   早坂 憂 五島啓太 荒井 純\n\n視 察 先   愛媛県宇和島市\n\n視察項目   「高齢者見守り・オンライン診察事業」(愛媛県宇和島市)\n       本市においても喫緊の課題となっている地域医療の充実に向け、先進的な取り組み\n選定理由   を行っている愛媛県宇和島市を視察対象とした。特に遠隔診療の導入や医師確保に\n       注目し、今後の施策立案の参考とするため選定した。\n       宇和島市 保健福祉部 高齢者福祉課 課長 小櫻博規様\n説 明 者   宇和島市 保健福祉部 高齢者福祉課 地域包括支援センター \n       所長補佐 大江仁志様\n       今回の視察では、高齢者が住み慣れた地域で安心して暮らし続けられるよう、地域\n       全体で支える見守り体制について学んだ。郵便局、行政、地域包括支援センター、\n       民生委員、自治会、事業者などが連携し、高齢者の異変を早期に発見・対応する仕\n       組みや、ICTを活用した見守りの取組、関係機関による情報共有の方法について説\n視察概要\n       明を受けた。\n       また、孤立防止や介護予防、認知症高齢者への支援など、日常生活に寄り添った実\n       践事例も紹介され、多様な主体が役割を分担しながら地域で支え合う体制づくりの\n       重要性について理解を深めた。\n\n       愛媛県宇和島市。人口６４８０１人 高齢化率４１．７％ 前年比－１４３３人 \n       ２００５年１市３町合併 都市部、中山間地域、島しょ部が混在。全国平均を超す\n       高齢化。(株)日本郵便からの働きかけによる、包括連携協定。\n       郵便局ネットワークを活用。高齢者の見守り体制として、市内各所に拠点(郵便局)\n       を持つ、日本郵便と連携事業で新たな社会資源を生み出している。自治体が連携し\n       スマートスピーカーを活用した「高齢者見守りネットワーク事業」プラス、タブ\n       レット端末と組み合わせによるサービスを行う。\n       ①独居高齢者、高齢者世帯等にスマートスピーカーを設置。操作は、郵便局社員が\n       見守り訪問サービス時に実施。\n 詳 細\n       ②スマスピアプリで体調確認や服薬確認を実施。結果は、レポートで家族にメール\n       自動配信。\n       ③日本郵便社員が定期的に戸別訪問。家族にメールでお知らせ(みまもり訪問サー\n         ビス)\n       ④家族や行政、居宅介護支援事業所が必要に応じてオンライン通話。健康状態を確\n       認。\n       ⑤タブレットを利用してオンライン診療および服薬指導を実施。\n       ⑥薬局からの配送依頼を受け、レターパック等にて処方薬剤を郵便局員が配達す\n       る。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":8,"text":"会派視察報告書\n\n\n      導入時の課題と解決にむけて\n      ①医療費、薬代の支払い、配達員の現金の取り扱いがNG→口座引き落としの手続\n      きをとる。\n      ②オンライン医療における郵便社員の立ち合いはゆるされるのか？→法的に「医療\n      従事者等」にあたり問題ない。\n      ③オンライン診療を行う医師に必要な条件→厚生労働省の研修を受講した。\n\n\n      導入状況\n      令和８年７月１日現在\n       １２世帯(うちオンライン診療２世帯)\n\n\n      現在から未来\n      人口減少が進む中自宅で自分らしく生きたい市民をどのように支援するか？限界を\n      感じる地方自治体と新たなサービスの創出を図りたい日本郵便、デジタル田園都市\n      国家構想の実現を目指す事業である。\n      「住み慣れたまちで、自分らしく生きる」家族が持つ様々な困りごとに応じて官、\n      民、地域住民がケースに応じて支援、役割を変え、安心した暮らしにつながる。\n      市内３０の郵便局と協同し、ネットワークを活用した民間企業とのハブの役割を期\n      待する。今後も拡大を目指す。\n詳 細\n      質疑応答\n      【早坂】\n      ① デジタルスピーカーの導入について。\n      質問\n      見守りサービスに活用することで、ケアマネジャーさんの声、連携・共有につい\n      て。実際にどのような支援につながっているか。\n      回答\n      ケアマネジャー連絡会を年２回で行う。意見を聞く。\n      ケアマネジャーから対象者の紹介がある。\n      緊急連絡先としてケアマネジャーを登録しているケースもあり、見守り体制の強化\n      につながっている。\n      ② 郵便局員の役割について\n      質問\n      タブレットの操作説明まで郵便局員が行うとのことだが、その役割は協定締結時か\n      ら想定されていたものか。\n      回答\n      当初はスマートスピーカーだけを想定。\n      オンライン診療導入に伴い、タブレットを追加し、郵便局員が配達・設定・操作支\n      援まで担う体制へ変更した。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":9,"text":"会派視察報告書\n\n\n      ③ デジタル田園都市国家構想交付金について\n      質問\n      交付金は具体的にどの部分へ活用されたのか。\n      回答\n      タブレット購入\n      スマートスピーカー購入\n      システム構築\n      実証事業費用\n      などに活用した。\n      ④ 対象者数について\n      質問\n       現在12世帯とのことですが、本来対象となる高齢者はどのくらいいるのか。\n      回答\n        独居高齢者は約5,000人。\n      通院困難者や高齢者世帯も含めると対象はさらに多い。\n\n      ⑤ 利用拡大について\n      質問\n      利用が伸びない理由は何か。また、今後どのように増やしていく考えか。\n詳 細      家族への直接的なアプローチが重要ではないか。\n      利用者の体験談や実例を発信することが利用促進につながるのではないか。\n      地域住民のネットワークを活用して対象者につなげる仕組みも有効ではないか。\n      回答\n      高齢者本人の心理的抵抗感が大きい。家族が市外に居住が多い。\n      行政だけでは家族へ十分アプローチできないことが課題である。\n      ⑥ タブレットの拡張性について\n      質問\n      タブレットは今後、様々なアプリを追加できる仕様なのか。\n      回答\n      技術的には可能だが、郵便局との運用ルールや協議が必要である。\n\n\n      【五島】\n      ⑦ 導入コストについて\n      質問\n       1人当たりの導入費用はどの程度か。\n      回答\n       事業費は約200万円。\n      利用者が増えるほど１人当たりコストは低減する。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":10,"text":"会派視察報告書\n\n\n      ⑧ 郵便局との連携について\n      質問\n      郵便局にとっても新たな事業となり、お互いメリットがあるという理解でよいか。\n      回答\n      その通りです。\n      郵便局も地域での新たな役割・事業を模索しており、双方にメリットがある。\n\n\n      【荒井】\n      ⑨ オンライン診療の位置付けについて\n      質問\n      訪問診療との関係はどのように考えるか。\n      回答\n      オンオライン診療は主に再診・定期受診が対象で初診や急変時は対面診療が基本で\n      ある。\n      ⑩ 医師確保について\n      質問\n詳 細    協力医師の確保はどのように行ったのか。\n      回答\n      日頃から地域包括支援センターと連携していた医師へ協力を依頼。\n      地域医療への理解と熱意のある医師が協力してくれたことが大きかった。\n      ⑪ 大崎市の事例を紹介しながらの意見交換を行う。\n      荒井から\n      オンライン診療\n      訪問看護\n      公民館を活用した診療\n      子育て世代へのオンライン診療\n      などの事例を紹介し、\n      「やってみることで新たなニーズが見えてくる」\n      との考えを伝え、宇和島市と課題や今後の可能性について活発な意見交換を行っ\n      た。\n      これらの質疑は、単なる制度確認にとどまらず、大崎市での導入・応用を見据えた\n      実践的な視点からの質問・提案が中心となっていた。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":11,"text":"会派視察報告書\n\n\n      荒井 純\n      今回の視察を通じて、高齢者の見守りは行政だけで完結するものではなく、地域住\n      民、民生委員、地域包括支援センター、協力事業者など、多様な主体が連携するこ\n      とによって初めて効果的に機能する仕組みであることを改めて認識した。\n      また、見守りを「特別な活動」ではなく、新聞配達や宅配、金融機関、商店などの\n      日常業務の中で異変に気付く体制として構築している点は、持続可能性の高い取り\n       組みであると感じた。さらに、ICTや緊急通報システムを活用しながらも、人と人\n      とのつながりを大切にしている姿勢は、高齢化が進む自治体において重要な視点で\n      ある。\n      一方で、高齢者のみならず、認知症の方や高齢者世帯の増加、支援者不足など、今\n      後の課題も共有された。こうした課題に対応するためには、地域全体で「見守る意\n      識」を醸成するとともに、行政が関係機関との情報共有や連携体制をさらに強化し\n      ていくことが必要である。\n      大崎市においても、地域の実情に応じた見守りネットワークの充実を図り、既存の\n      地域資源や民間事業者との連携をさらに推進することで、高齢者が住み慣れた地域\n所 感    で安心して暮らし続けられる地域共生社会の実現につながるものと考える。\n\n\n\n\n      早坂憂\n       離島という特殊事情を、ICTの活用によって課題解決に繋げる取り組みに、いかに\n      住民と福祉の距離を近づけ、利便性を高めると共に安全・安心に対する熱意を感じ\n       た。Digi田甲子園の交付金をどの様な事業で活用出来るかが発想の入口だったが、\n      見事に住民福祉の向上に繋げていた。もちろん課題はあったが、その解決の糸口を\n       見つける過程で郵便局との連携に結びつき、お互いの組織のWinWinへと進化さ\n      せ、島と行政を近づけた功績は大きいと感じた。大崎市でも各分院でオンライン診\n      療・訪問看護の取組が進められているが、機器の設置と操作方法の説明、そして配\n      薬に課題があるという。まさに参考になる取り組みだった。早速担当課や市民病院\n      本院・各分院と情報共有、意見交換をしてみたい。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":12,"text":"会派視察報告書\n\n\n      五島啓太\n      愛媛県宇和島市への視察研修を通じて、急速に進む高齢化と中山間地域・過疎地が\n      抱える医療・見守りの課題に対し、デジタル技術と地域資源を融合させた先駆的な\n      取り組みを深く学ぶことができた。\n      特に印象的だったのは、単にオンライン診療システムを導入するだけでなく、日本\n      郵便の地域ネットワークを活用した「人に優しいデジタル化」の実行である。高齢\n      者にとってハードルとなりがちなタブレット端末の操作や服薬指導、薬の配送を郵\n      便局員が対面でサポートし、日常の見守り（スマートスピーカー等）と組み合わせ\n所 感    ることで、デジタルデバイドを解消しながら安心を届ける仕組みは非常に実践的\n      だった。また、医師・薬剤師・郵便局・行政が一体となり、医療過疎地における通\n      院負担や移動困難の解消に向けて粘り強く合意形成を図ってきた姿勢にも強く感銘\n      を受けた。\n      大崎市においても、広大な市域と中山間地域を抱え、高齢化や公共交通・医療アク\n      セスの確保は喫緊の課題である。デジタルを活用して手続きや移動の負担を減らす\n      一方で、本当にサポートが必要な高齢者には手厚い対面支援を組み合わせるという\n      「人に優しいデジタル活用」の思想は、まさに大崎市の市政推進においても不可欠\n      な視点である。\n\n\n\n      今回の行政視察では、各自治体における先進的な取組について、事業の背景や運営\n      体制、財源、人材確保の手法、成果と課題まで幅広く調査を行った。いずれの事例\n      も、人口減少や少子高齢化、担い手不足といった共通課題に対し、地域の実情に応\n      じた工夫と継続的な改善を重ねながら成果を上げていることを確認した。\n      会派としては、視察で得られた知見を単なる事例紹介にとどめることなく、大崎市\n      の地域特性や財政状況、既存施策との整合性を踏まえた上で、その有効性を十分に\n      検証し、導入可能な施策について積極的に政策提言を行う必要があるとの認識を共\n総 括    有した。\n      また、現地で確認した取組と比較した結果、大崎市において制度の充実や関係機関\n      との連携強化、情報発信、利用促進など改善の余地が認められる分野については、\n      現状把握を進めるとともに、必要に応じて担当部局への調査や一般質問、委員会活\n      動等を通じて課題解決を促していくことが重要である。\n      今後は、今回の視察成果を市政運営へ反映させるため、執行部との建設的な議論を\n      重ねるとともに、実効性のある政策提言と継続的な検証を行い、市民福祉の向上と\n      持続可能な地域づくりに資する議会活動を推進していく。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":13,"text":"会派視察報告書\n\n\n会 派 名   志創会\n\n視 察 日   令和８年７月２５日（土）\n\n視 察 者   早坂憂、荒井純、五島啓太\n\n視 察 先   愛媛県宇和島市\n       パフィオ宇和島（宇和島市学習交流センター）\n       ・複合施設を活用した地域コミュニティの形成\n視察項目   ・多世代交流および市民活動推進の取組について\n       ・中心市街地の賑わい創出と図書館・子育て支援・生涯学習拠点の複合的連携事業に\n       ついて\n       パフィオ宇和島（宇和島市学習交流センター）\n       中心市街地の賑わい創出と多世代交流・生涯学習の推進を図るため、図書館・子育て\n       支援・多目的ホール等を一体化した先進的な複合施設であるパフィオ宇和島を視察対\n選定理由\n       象とした。市民協働による施設運営や多世代が日常的に集うコミュニティ形成の取組\n       を現地調査し、本市の公共施設マネジメントおよびまちづくり施策の参考とするため\n       選定した。\n       宇和島市生涯学習センター 指定管理者 株式会社上田 センター長 吉光 久 氏\n説 明 者   宇和島市教育委員会 生涯学習課 宇和島市立図書館 館長　村上 愛子 氏\n       宇和島市議会事務局 主査 中川 武史 氏\n       【パフィオ宇和島】\n       図書館・子育て支援・生涯学習拠点を一体化した中心市街地の複合施設を視察。多世\n視察概要\n       代が集う交流拠点づくりや市民協働による施設運営、中心部の賑わい創出に向けた空\n       間活用の取組を現地調査した。\n\n       【パフィオ宇和島（宇和島市学習交流センター）：複合拠点による多世代交流と賑わ\n       い創出】\n\n                 1. 施設概要・説明事例\n       ・中央図書館、子育て世代活動支援センター、生涯学習センター、多目的ホール等を\n       一体化した中心市街地の複合施設。\n       ・乳幼児から高齢者、中高生などの若者世代までが同一空間に集い、自然な多世代交\n       流が生まれる動線・空間設計を採用。\n 詳 細\n       ・天候に左右されずに遊べる屋内子育て支援スペースや、自習・読書・市民活動がで\n       きるオープンスペースを配置し、中心市街地の回遊性向上と平日・休日を問わない賑\n       わいを創出している。\n\n                 2. 運営および市民協働の取組\n       ・市民ボランティアや市民活動団体と連携したイベント・講座の定期開催。\n       ・単なる公共施設の複合化にとどまらず、世代を超えたコミュニティ形成と中心市街\n       地の活性化を両立させる拠点運営モデルとして機能している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":14,"text":"会派視察報告書\n\n\n\n\n      五島　啓太\n      中央図書館、子育て支援、生涯学習拠点が一体となった「パフィオ宇和島」を視察\n      し、若者から子育て世代、高齢者までが日常的に集い、自然に世代間交流が生まれる\n      空間設計と運営ノウハウを学んだ。天候に左右されずに子どもたちが遊べる場や市民\n      活動の拠点を中心市街地に設けることは、街の明かりを灯し、賑わいコミュニティを\n      再構築するために不可欠である。本市における公共施設の利活用や、世代を超えて\n      人々が語り合える拠点づくりに向けた具体的な政策提言につなげていきたい。\n\n\n\n      早坂　憂\n      まずはその立地条件の良さに驚いた。駅の近くである事、街を一望できる場所である\n      事、城を眺められるテラスがある事、そして3つの施設が集まった複合施設である事\n      から、利用率が高いことも頷けた。\n所 感    一階の貸し館施設は指定管理制度で運営され、広いホールと可動式の客席、分割でき\n      る多目的室、自由工房、音楽練習室、スタジオなどに別れており、バリアフリーの取\n      り組みも進められていた。\n      二階の図書館も同様で、読書バリアフリーサービスも行われていた。吹き抜けの空間\n      や眺望を意識したレイアウト、特集コーナーの配置など、職員や司書の方々のやる気\n      を感じる施設だった。\n      三階の子育て世代活動支援センターは奥まで目が届きやすいレイアウトで、受付の職\n      員や保護者が子どもを見守りやすいと感じた。玩具や本の貸出も行われ、スライム作\n      りなどの企画も多く、視察させて頂いた日も実際に複数の親子が企画を楽しんでい\n      た。テラスも開放的で手洗い場も設置されていたが、当日は猛暑ということもあり、\n      子ども達に解放はされていなかった。\n      大崎市では用地取得の課題もあるが、公共施設の在り方検討の中で集約化も進めてい\n      かなければならない。新しい箱を作るだけではなく、既存の施設をどう活用して集\n      約・複合化が出来るかという視点も必要と感じた。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":15,"text":"会派視察報告書\n\n\n      荒井　純\n      愛媛県宇和島市の複合施設「パフィオ宇和島」は、図書館、生涯学習、子育て支援な\n      どの機能を一体的に配置し、子どもから高齢者まで、幅広い世代が日常的に利用でき\n      る地域の交流拠点として整備されていた。単に複数の公共施設を集約するのではな\n      く、異なる機能を相互に結び付け、新たな交流と支え合いを生み出している点に大き\n      な特徴がある。\n      特に注目したのは、障がいの有無や年齢にかかわらず、誰もが必要な情報にアクセス\n      し、安全に施設を利用できる環境づくりである。視覚障がい者などの移動や情報取得\n       を支援する「NaviLens」の導入、大活字本をはじめとした利用者の特性に応じた資料\n      の充実など、情報から誰一人取り残さないための具体的な配慮がなされていた。理念\n      としてユニバーサルデザインを掲げるだけではなく、設備、蔵書、案内、サービスの\n      各面において実践している点は高く評価できる。\n      子育て世代活動支援センターには、一時預かり、授乳室、親子で過ごせるスペースな\n      どが設けられ、子育て家庭が安心して利用できる環境が整備されている。子育て中の\n      保護者が悩みや負担を抱え込まず、必要に応じて相談や支援につながることのできる\n      場は、家庭の孤立を防止するうえでも重要である。\n      さらに、子育て支援機能と図書館、学習・交流スペースを同一施設内に配置し、それ\n      ぞれを利用しやすい動線で結ぶことで、異なる世代や目的を持つ人々が自然に行き交\n所 感      う環境が形成されていた。このような空間構成は、意図的に交流を求めなくても、同\n      じ場所に居合わせることで緩やかなつながりや見守りが生まれる「共生型の地域拠\n      点」として、有効であると感じた。\n      また、同施設が自動解錠システムを備えた津波避難ビルとしての機能を有している点\n      も重要である。平常時には学習、子育て、交流の拠点として活用し、災害時には住民\n      の命を守る避難拠点として機能する。特に、高齢者、障がいのある方、乳幼児を連れ\n      た家庭など、避難時に配慮を必要とする人々を想定した施設整備は、福祉と防災を一\n      体的に考えるうえで参考となる。\n      大崎市においても、公共施設を個別の行政目的だけで捉えるのではなく、子育て、福\n      祉、生涯学習、防災、地域交流などの機能を横断的に結び付ける視点が必要である。\n      新たな施設整備に限らず、既存施設の機能や配置を見直し、世代や分野を超えて利用\n      できる地域拠点へ再構築することも検討すべきである。\n      あわせて、施設のバリアフリー化にとどまらず、情報の受け取りやすさ、移動のしや\n      すさ、利用手続の分かりやすさなども含めた、総合的なユニバーサルデザインを推進\n      する必要がある。すべての市民が孤立することなく、必要な支援や人とのつながりを\n      得られる地域社会の実現に向け、今回の視察で得た知見を、大崎市の公共施設の在り\n      方と福祉施策に関する具体的な政策提言へつなげていきたい。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"20de876df7db3f1e","year":2026,"faction":"志創会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/shisokai20260723_25.pdf","page":16,"text":"会派視察報告書\n\n\n\n               1. 視察の成果と共通の認識\n      各視察先において一貫していたのは、「行政の枠組みや前例にとらわれず、現場の課\n      題解決に向けて民間活力や既存の地域資源を最大限に巻き込む姿勢」である。\n      ・大崎町では、行政と事業者が対等なパートナーシップを築き、自立した協同組合に\n      よる機動的な商品開発と大都市圏での共同PRを推進することで、地域経済の循環と自\n      主財源の確保を実現している。\n      ・宇和島市役所では、超高齢化と医療格差という深刻な課題に対し、郵便局ネット\n       ワークやICTを活用した「デジタルと対面のハイブリッド支援」によって、高齢者一\n      人ひとりに寄り添う持続可能な地域包括ケアモデルを提示している。\n      ・パフィオ宇和島では、機能集約にとどまらず、多世代が日常的に交差し賑わいを生\n      み出す空間設計と市民協働の拠点運営を実践している。\n\n               2. 本市が直面する課題と改善点\n      本市の現状と照らし合わせた際、以下の課題が浮き彫りとなった。\n      ・ふるさと納税において、民間事業者との連携体制や自立的な返礼品開発のスピード\n      感が不足しており、単一品目に依存しない稼げる地域産業の育成が急務である点。\n      ・行政手続きや医療等のデジタル化を進める一方で、取り残されがちな高齢者や中山\n      間地域住民に対する「現場に即した手厚い対面サポート体制」の構築が遅れている\n総 括      点。\n      ・中心市街地や公共施設の利活用において、多世代が自然に集い交流できるコミュニ\n      ティ拠点の創出が十分に図られていない点。\n\n               3. 今後の政策提言および議会活動の方向性\n      本視察の成果を単なる調査にとどめず、本市の課題解決とアップデートに向け、以下\n      の柱を軸に具体的な政策提言および議会からの働きかけを積極的に行っていく。\n      ①【官民共創による稼げる地域産業の構築】\n      行政依存から脱却し、市内事業者が主体となって魅力的な返礼品や特産品を機動的に\n      生み出せる協働プラットフォームの整備を提言する。また、「大崎」の地名縁などを\n      活用した都市間連携・異業種連携による新たなブランド価値創出を後押しする。\n      ②【人に優しいデジタル化と地域インフラの再構築】\n      高齢者や子育て世代の利便性を高めるデジタル化（オンライン診療・行政手続きのス\n      マホ完結等）を推進するとともに、郵便局など地域に根ざした既存インフラと連携\n      し、取り残される市民を出さない手厚い対面支援体制（ラストワンマイルの確保）の\n      構築を提言する。\n      ③【世代を超えて集える賑わい拠点の形成】\n      公共施設の更新や中心市街地活性化にあたっては、子育て支援・生涯学習・市民活動\n      が一体となり、若者から高齢者までが日常的に集い語り合える多世代交流拠点の整備\n      と柔軟な市民協働運営を求めていく。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":1,"text":"会派視察報告書\n\n\n会 派 名   創清会\n\n視 察 日    令和8年8月4日\n\n視 察 者   佐藤仁一郎 石田政博 富田堅治\n\n視 察 先    YKKAP株式会社 黒部製造所、YKKAP技術館\n\n視察項目   企業とまちづくりの関わりについて\n       大崎市と黒部市は、YKK株式会社の仲立ちにより姉妹都市の提携を結んでい\n         る。YKK AP株式会社は、黒部市の工場などを製造・研究開発の拠点として整\n       備するだけでなく、周辺地域との共生を意識した街づくりをも実践している。\n選定理由\n       本調査において、地域社会と共生する企業の姿勢や、モノづくり産業の振興、\n       環境施策の観点等について学び、大崎市の施策に役立てるため、会派会議にお\n       いて協議のうえ視察先として選定した。\n           YKK AP株式会社 生産本部 黒部総務部長 藤崎 猛氏\n説 明 者\n           YKK AP技術館 YKK AP先人ホール 館長 畑谷 弘之氏\n           YKK AP株式会社は、黒部市に製造・研究開発の拠点を置く企業であり、工場\n       の整備にとどまらず、周辺地域との共生を意識した街づくりを実践している。\n       本視察では、\n       【説明依頼項目】視察概要\n       ①地域社会と共生する「まちづくり」と産業観光の推進\n       ②防災・環境対策とスマート化\n       ③企業の人材育成と地元雇用の創出、の三点について説明を受けた。\n\n        質問事項に対し、別紙資料「YKK AP統合報告書2025」及びYKK AP技術館の展\n       示資料により応答・説明をいただいた。\n\n\n       【調査事項１】地域社会と共生する「まちづくり」と産業観光の推進について\n\n       （質問）黒部市で展開する「パッシブタウン（自然エネルギー活用型エコタウ\n       ン）」やYKKセンターパークのような観光産業・緑化施設の運営手法について\n       伺う。\n 詳 細       （応答・説明）\n        ア）社員居住と地域開放の連携\n       社員寮やパッシブタウンなど、単なる社宅や社員用施設に留まらず、地域住民\n       にも開かれた形で居住・交流空間を提供している。敷地内の豊かな植栽やアー\n       ケードは、通り抜けや憩いの場として地域住民が利用可能で、街全体に自然な\n       賑わいを創出している。こうした設計により、社員と市民が日常的に交わるこ\n       とで、 地域コミュニティとの一体感を醸成している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":2,"text":"会派視察報告書\n\n\n      イ）環境・エネルギー面での地域貢献\n      地元木材や木質チップを活用したバイオマスボイラーや太陽光発電の導入によ\n      り、住宅・街区全体で自然エネルギーの活用・消費抑制を行うことで、地域に\n      持続可能なエネルギー供給のモデルを示し、地域の環境負荷低減に貢献してい\n      る。\n\n      ウ）地域資源と文化の活用\n      地域の豊かな地下水や自然環境を尊重した製造活動や街づくりに活かす循環型\n      の取り組みを行っている。また、「魚の駅 生地」など地元の特色ある施設への\n      木材供給やデザイン協力により、地域文化や景観保全とリンクした開発を進め\n      ている。\n\n      エ）住民開放型施設での教育・交流・観光\n        YKKセンターパークやYKK AP技術館など産業観光施設の設置により、技術や\n      企業理念を地域住民や訪問者に公開するとともに、環境共生・木造建築などの\n      見学体験を通じて、地域住民への教育・啓蒙も兼ねており、企業活動が地域の\n      学びや交流の機会にもなっている。\n\n\n      【調査事項２】防災・環境対策とスマート化について\n\n詳 細\n      （質問）自動化・省エネ化が進む製造拠点における大規模災害時の事業継続計\n       画（BCP）及び環境負荷低減の取り組みについて伺う。\n\n      （応答・説明）\n       ア）大規模災害時の事業継続計画（BCP）について\n      本社の製造・物流拠点の災害リスクに対して以下の施策を実施している。\n        ①物流DXの推進と「安心・安全ポータル」の構築\n          • トラックの位置情報、交通・天候情報、製品・顧客情報を一元的に管理\n          • 遅延や寸断が予想される時、事前に迂回経路を指示し、製品配送を確実化\n                     • ポータルにより関係者間の情報伝達が迅速化し、災害対応力を向上\n          • チャット機能やエリアごとの輸送状況報告、SNS連携による気象・災害情\n        報集約を実現\n       ②スマートファクトリー化\n                       • 今年度を目途に黒部越湖製造所などの生産拠点を無人化・自動化\n                       • ロボットやAI、5G技術を活用し製造・点検工程の異常検知を実現\n                       • バーチャルファクトリーによる遠隔監視・模擬運用も推進中\n        ③サプライチェーン全体のBCP意識向上\n                      • 従業員・物流業者との協力体制により、自然災害発生時も継続的な輸送と\n        安全確保を実現","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":3,"text":"会派視察報告書\n\n\n      イ）環境負荷軽減への取り組み\n          YKK APは「Evolution 2030」及び中期環境事業計画に基づき、製品・ものづく\n      り・サプライチェーン全体で環境負荷軽減に取り組んでいる。主要施策は以下\n      のとおりである。\n       ①気候変動対策\n                    • CO2排出削減\n                    • 再生可能エネルギー導入拡大（黒部製造所には大規模蓄電池を導入）。\n        国内外11拠点に合計16,200kWの太陽光発電を実現し、2024年度の導入量は\n         2021年度比で9倍、CO2排出量を12,000t削減した。\n                   • 高断熱住宅窓の販売。例：APW 651トリプルガラス木製窓により使用時CO2\n       を削減。商品使用時のCO2削減貢献量は2024年度に2020年度比175％を達成し\n        た（2028年度目標は220％）\n       ② 資源循環・リサイクル\n      ・アルミ再生材活用・樹脂リサイクル・廃棄物ゼロエミッション等\n\n      ウ）化学物質・水保全・生物多様性詳 細\n                   • 水使用効率化、多段利用、排水管理強化により地域コミュニティへの環境負\n      荷を軽減。\n                  • 各拠点で植樹や社会貢献活動（2024年度217件）を展開し生物多様性保全に貢\n      献。\n\n      【調査事項３】企業の人材育成と地元雇用の創出について\n\n      （質問）多様な人材の確保策及び、技術継承や人材育成について伺う。\n\n      （応答・説明） YKKグループでは、年齢や性別、学歴などにとらわれず、「自\n      律と共生」の考えをもとに社員一人ひとりが十分に力を発揮できる制度や環境\n      づくりを進めている。めざす姿は、一本一本の木が独立しながら森林を形成す\n      るように、一人ひとりが「経営者」という意識を持ち、全員が手を携えて一緒\n      に大きく育つ「森林集団」である。そのような組織として価値を創造すべく、\n      真に公正な人事制度の実現と人材育成に取り組んでいる。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":4,"text":"会派視察報告書\n\n\n      人材戦略\n      以下の4つの観点から各施策を実行し、多様な人材に選ばれる会社をめざしてい\n      る。\n       ①働きやすい職場環境の実現 働き方改革委員会や職場改善委員会の取り組み\n      を強化し、多様な働き方やダイバーシティ＆インクルージョンを推進してい\n      る。\n      ②社員への投資 既存の研修に加え、創造性や構想力向上の育成とグローバル\n詳 細    人材育成を目的に、教育体制の再構築を図っている。\n      ③成長機会の提供 個人のキャリア形成・開発支援を強化している。\n      ④雇用を生み出す経営 人事制度・運用を改善し、年次有給休暇取得率の向上\n      や採用強化施策などを展開している。\n      具体的な施策\n                   • 2021年度に定年を廃止した。意欲と能力のある社員が知見や経験を活かし続\n      けられるようにし、ベテラン社員の技術・ノウハウの次世代への継承を図って\n      いる\n      佐藤 仁一郎\n       黒部市は、面積約426k㎡、人口約37,000人の市である。その中にあるYKK黒部\n       事業所には約6,000人が勤務しYKKのファスナー事業や建材事業の開発・生産や\n      技術開発の中核でもあり、国内外に向けた技術発信と製造の重要拠点と位置づ\n      けられていた。パッシブタウンや社員寮が地域住民に開かれ、植栽やアーケー\n      ドが通り抜けや憩いの場となっている点に感銘を受けた。企業の敷地を閉ざさ\n      ず地域の生活空間として共有することが、結果として街の賑わいと定住につな\n      がっている。大崎市においても、企業立地を雇用の場としてのみ捉えるのでは\n      なく、まちの空間をともにつくる主体として位置づける発想が必要である。\n\n      石田 政博\n所 感    YKKセンターパークの「ふるさとの森」では、黒部川扇状地に原生していた樹\n       木の種子から苗木を育て、20種2万本を植樹していた。また技術館では創業時\n      の工場を取り壊さず展示館として再生していた。企業が自然と歴史を保存し市\n      民に開放する姿勢は、地域資源を次代へ引き継ぐ営みそのものであり、本市に\n      おいても学ぶべき点が多いと感じた。\n\n      富田 堅治\n      黒部が首都圏被災時の現地対策本部の代行拠点と位置づけられ、実際に連携訓\n      練が行われていることを知り、地方拠点が担う国土強靭化上の役割を改めて認\n       識した。また、2021年度の定年廃止や企業内大学「APテック」の開校など、人\n      材を「確保する」から「育て、活かし続ける」へと軸足を移す姿勢は、人口減\n      少下にある本市にとっても重要な示唆である。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":5,"text":"会派視察報告書\n\n\n      本視察を通じ、会派「創清会」としての総意を以下のとおり取りまとめる。\n\n      １．視察の成果\n          YKK AP株式会社は、黒部市において製造拠点としての機能を果たすにとどま\n      らず、地域と共生する街づくりを実践していた。社員寮やパッシブタウンの地\n      域開放、創業時の工場を保存活用した技術館の無料公開、在来種による「ふる\n      さとの森」の整備と開放など、企業活動が地域の暮らしや学びに直接つながっ\n       ている。また、物流DXを核としたBCP体制の構築、環境目標の数値管理、定年\n      の廃止や企業内大学の開校といった人材戦略は、いずれも具体的な数値と実績\n      を伴って示された。 YKKは黒部市の経済、まちづくり、環境施策に深く関わる\n      存在であり、市の持続的発展や地域住民の生活に密接に関わっている。黒部市\n       にとってYKKは「なくてはならない存在」であることが確認された。\n\n      ２．今後の展望\n       大崎市は面積797k㎡、人口約12万人を擁し、黒部市とは規模も産業構造も異な\n      る。しかしながら、人口減少と労働力不足、地域産業の維持という課題は共通\n      である。企業の施設や活動が「企業のもの」に閉じず地域に開かれていること\n      が、結果として企業自身の人材確保や地域からの信頼につながっている点は、\n      本市においても応用可能な視点である。\n\n総 括    ３．政策提言の方向性\n       （1）地域の中核企業との連携によるまちづくりの推進\n      企業の施設・活動を地域に開かれたものとしていくための行政としての支援や\n      環境整備、及び産業観光資源としての活用について検討すべきである。あわせ\n      て、市内企業の歴史や技術を市民が学べる機会の創出を図るべきである。\n       （2）防災体制の強化\n      市内事業者との災害時の情報共有体制の構築を検討すべきである。また、防災\n      訓練の対象に、事業所の従業員のみならず、物流事業者や協力会社を含めた実\n      効性のある訓練のあり方を検討すべきである。\n       （3）人材確保・定着施策の充実\n      自治体・ハローワーク・事業者の三者連携による一体的な施策展開について検\n      討するとともに、本市における移住・定住支援策と雇用施策の連動を強化すべ\n      きである。\n       （4）姉妹都市交流の実質化\n       大崎市と黒部市は、YKK株式会社の仲立ちにより姉妹都市の提携を結んでい\n      る。この縁を儀礼的な関係にとどめず、政策情報の相互交換や職員・議員の交\n      流を継続し、両市の課題解決に活かしていくことを提案する。\n\n       添付資料 有（別紙 「YKK AP統合報告書2025」抜粋、YKK AP技術館パンフ\n      レット）","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":6,"text":"会派行政視察報告書\n\n\n                                 大崎市議会調査活動概要報告書\n                                  報告者石田政博\n1. 視察概要\n 会派名  創清会\n   氏 名   佐藤仁一郎、石田政博、富田堅治\n   日 時   令和 ８年８月５日AM１０：００〜令和８年８月５日1１：３０\n         大崎市民病院との連携協定締結後の、取組について確認することと、黒部市民病院が\n  選定理由  抱える課題等や経営状況改善の取組について調査するため。\n  視察先   富山県黒部市（黒部市民病院）\n  出席者   辻宏和院長、寺田逸郎副院長、丸山裕美子理事、渡邊和美看護部長、今井知明看護肢\n  （説明者）  長他７名（添付名簿の通り）\n\n\n2. 視察内容\n  視察項目  黒部市民病院の現状と課題について\n   概要    人口は本市の1/3、面積では約1/２であるが、本市と同じように周辺地域の中核病院\n         としての立場にあり、担っている医療・機能も類似に有している。視察をしてみると、大崎\n         市民病院が抱える課題も類似しており医業収益は増加しているものの、医業費用の職員\n         給与費と材料費が増加し収支が悪化している。また、先進医療インフラへの投資と設備\n         投資・更新の必要性も同じである。看護師・専門医師の不足の課題も重なっていた。\n                 2020 年10 月の「災害時等における相互応援に関する協定」から丸5 年が経過したが、\n         現在、研修医の交換交流も行われている。\n\n\n\n\n\n          【現状と課題】\n   詳細    ・新川医療圏の基幹病院として、主に高度急性期医療・急性期医療を担っている。さらに\n         自治体病院として、救急医療、高度医療、小児・周産期医療、へき地医療などの不採算\n         医療を担い、がん診療連携拠点病院よして専門的ながん医療や健康センターを中心に\n         病気の早期発見と予防に取り組んでいる。\n         ・同医療圏では、医師・看護師・薬剤師等の医療従事者の不足により医療機能の維持が\n         困難になることが想定され、黒部市民病院では初期臨床研修医や新専門医制度による\n         専攻医、病院実習等の受け入れなどを通じマンパワー確保に努めている\n             。\n         ・（経費削減）・院外処方箋の発行率向上による材料費抑制と在庫抑制\n               ・適正な人員配置による人件費削減\n               ・業務改善による時間外勤務の抑制\n          ・（人員確保・離職防止）\n               ・医師・看護師・薬剤師の確保のため大学等との連携、人脈を通じた情報収\n         集、採用情報などを積極的に発信するほか、勤務環境の改善が必要。\n\n\n  質疑応答  事前質問への回答（別紙資料参照）\n\n\n         １．黒部市民病院の現状と課題について\n          答）現状\n            ①一般３６３床、結核５床、感染4 床計３７２床\n            ②３３診療科、２．２次救急を担う、HDU１３床、他は大崎市民病院同等\n            ③「良質な医療を保つ」、「信頼を培う」、「安心の医療を届ける」を基本としている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":7,"text":"課題\n  ①収益と支出のギャップ\n   医業収益は増加しているが医業費用（職員給与・材料費）が増加し、収支が悪化\n    している。\n   高度医療を守るにはインフラ投資に、１０年単位の更新計画と投資判断が必要。\n  ②人口減少（患者減少・働き手減少）\n   生産人年齢口減、高齢者増で医療需要増、人材確保困難、健康寿命の延伸。\n  ③看護師不足・専門医不足\n   採用不足を補う「辞めない・支える・育てる」体制が必要\n                                 （辻院長）〈資料１〉\n\n\n２，地域医療連携室の取り組みについて\n 答）愛称：「フレンディー」\n   主な業務：前方支援（紹介受付・診察/検査の予約\n       ：後方支援（退院・店員調整、逆紹介等\n   スタッフ：病棟選任 看護師３名/社会福祉士７名\n       事務  １．５名\n   扇状地ネット登録医療機関：３２機関\n   医療機器共同利用延べ９９４件/年間\n 課題\n   ①「PFM 体制構築」による入院前から退院後までのシームレスな医療提供\n   ②切れ目のない入退院支援（扇状地ネット・Net４U の活用）\n   ③対面交流・連携会議の継続・あいさつ訪問）\n   ④ICT と対面の両輪で多職種連携を推進し、地域包括ケアを強化\n                              （今井看護師長）〈資料２〉\n\n\n３，地域医療連携の拡充について\n 答）扇状地ネットは、現状、あさひ総合病院・富山労災病院とカルテ閲覧やオンライン予\n  約を行っている。\n  加えて今年度から地域内診療所との病診連携を予定している。\n  診療所に加え、薬局・介護施設・医師会・薬剤師会・新川康生センター等の他機関と\n  の連携へ進める。（患者の同意が必要）\n  目指す姿は、患者さんがどの施設にいても経過・検査・薬剤情報を確認できること。\n  目的は、人口減少時代の「医療資源の共有」\n   患者の負担軽減/重複検査の抑制/紹介・逆紹介の円滑化/退院後支援の連続性\n                            （武隈情報管理課長）〈資料３〉\n\n\n４，大崎市民病院との連携について\n  岩出山分院・鹿島台分院に研修医を派遣\n\n\n                                （辻院長）〈資料１〉\n追加質問\n 問）扇状地ネットによる情報共有時の個人情報管理の課題はないか。\n 答）現在までの３病院では無かったが、指摘の通り利用範囲を拡げた場合の検討を\n  している。\n 問）地域連携医療において、運用の費用負担に課題は無いか。黒部市民病院の負\n  担が大きいのではないか。\n 答）指摘の通り持ち出しの状態である。しかし地域の中核として進めている。\n\n\n「その後、ヘリポートを案内して頂き視察」","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":8,"text":"（佐藤仁一郎）\n          今回の視察を通じて、黒部市民病院が新川医療圏の中核病院として、救急・急性期医\n   所感   療から地域医療、在宅・福祉との連携まで幅広い役割を担っている事を実感した。特に\n          地域医療連携室を中心とした医療機関・福祉関係機関との連携や、地域包括医療・ケ\n         アに取り組む姿勢は、大変参考になった。\n\n\n          （富田堅治）\n          救急医療や災害医療、高度医療にも対応しながら、地域住民に身近な医療を提供して\n         いる点から「地域の中核病院」としての責任と役割の大きさを感じた。今回の視察で得た\n         知見を、今後の地域医療の充実や医療・介護・福祉の連携強化、住民が安心して暮らせ\n          る地域づくりに生かしていきたい。\n\n\n          （石田政博）\n          高度な急性期医療を担いながら、地域に根差した医療・介護・福祉の連携を進めてい\n         る点が非常に印象的であり、大崎地域の医療体制を考える上で有意義な視察となった。\n   総括   大崎も現在、市民病院敷地内に連携拠点施設(夜間救急センター併設)開設を予定して\n         いるので、今回の視察課題を関連部署に報告しながら、団体や担当課、民生常任委員\n         会相互に意見交換の必要を感じた。\n         救急医療体制整備と併せて、昨日の就活支援、おひとり様支援を含め委員会として視察\n         結果を踏まえ、医療と扶助の連携について具体的に提案していく必要性を痛感した。\n          今後の地域医療連携施設の運営にも、黒部市の医療連携室や扇状地ネット等の先進\n         事例は参考になると思われるので、更なる交流・意見交換が両病院間で行われる事が\n          望まれる。\n\n\n\n\n\n以上","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":9,"text":"会派視察報告書\n\n\n会 派 名   創清会\n\n視 察 日     令和8年8月5日 15:00-16:00\n\n視 察 者   佐藤仁一郎、石田政博、富田堅治\n\n視 察 先   羽咋市 合同会社のとしし団\n\n視察項目   羽咋市 獣肉処理施設 のとしし団の概要について\n       大崎市においても、ジビエの郷おおさきを中心にジビエ事業に取り組んでいる\n       が、同じくジビエ事業に先進的に取り組む石川県羽咋市の「のとしし団」を視\n選定理由\n       察することで、イノシシ対策と地域産業の振興を一体的に捉えた事業展開につ\n       いて学ぶため。\n       合同会社のとしし団 代表 加藤普司 様\n説 明 者\n       合同会社のとしし団 事務 髙田守彦 様\n\n       羽咋市ではイノシシによる農業被害が深刻化しており、平成24年の1頭から5年\n        で年間300頭を超えるまでに増加している。のとしし団は平成27年に「のとし\n       し大作戦」として設立され、羽咋市と合同会社の形態で運営されている。捕獲\n       したイノシシを前処理室での殺菌処理から始まり、一次処理室での内臓摘出・\n視察概要   殺菌浄、1～3℃での熟成冷蔵保存、二次処理室での部位分けまで、段階的な処\n       理を実施している。施設には高圧洗浄機、金属検出器など最新の処理設備を備\n       え、-40℃での急速冷凍でドリップの流出を最小化している。年間売上は約\n       1000万円で、主に関東圏などの飲食店に卸売りしている。廃棄物は炭化装置で\n       肥料化を試みるなど、貴重な資源として余すところなく活用している。\n\n\n\n       【羽咋市の歴史的背景】\n       羽咋市では、安政の書上という古文書の中で畑を荒らす動物としてイノシシと\n        鹿の被害が訴えられており、明和9年（1772年）加賀藩より「悪事に使用しな\n       いこと」、「又貸ししないこと」を条件に口郡（羽咋郡市・鹿島郡）に４挺の\n 詳 細\n       鉄砲が貸し出され、イノシシ退治に取り組んでいた。その６年後にはイノシシ\n       と鹿の皮が300枚売りに出されたとの記録もあることから、当時はかなり多く\n       のイノシシやシカが生息していたことが伺える。明治から大正にかけ一度絶滅\n       したとされるイノシシは、平成になり再び生息するようになった。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":10,"text":"会派視察報告書\n\n\n      【のとしし大作戦の開始経緯】\n       羽咋市で増えたのはつい最近のことで、平成24年にしばらくぶりにイノシシ1\n       頭が捕獲されてから、たったの5年で年間300頭を超えるイノシシが捕獲される\n      までになった。農家の皆さんが農地や農作物を守るためにやむをえず捕獲して\n      いるのが現状である。\n       これまでは、イノシシを捕まえた方に対して、捕獲奨励金を支払うことでご\n      苦労に報いてきたが、捕獲したイノシシをゴミとして扱うことは、捕獲した方\n      の大きなストレスになってしまう。捕獲したイノシシを廃棄するのではなく、\n      貴重な資源として活用を図ることで人間とイノシシが共存できないかという思\n       いから、平成27年に「のとしし大作戦」事業を開始した。平成27年10月14日に\n      食肉処理業の許可を得て、事業がスタートした。\n       安全で安心な食肉を生産し、野生の味を楽しんでもらうことはもちろんのこ\n      と、このプロジェクトでは、これまで産業廃棄物として処分されることの多い\n      皮についても、特産化の試みを始めている。いのちの営みに感謝をしつつ、貴\n      重な資源として余すところなく活用していくことが、のとしし大作戦の目指す\n      ところである。\n\n\n\n      【質疑応答】\n詳 細        問：運営形態は、指定管理のような形か？\n        答：羽咋市にも出資してもらい、合同会社の形態をとっている。\n        問：主な販売先は？年間の売り上げは？\n        答：主に、ジビエ料理を専門とする飲食店である。地元というよりは、関東\n      圏などその地域にイノシシがいない地域がほとんどである。また、京都の篠山\n      などのジビエよりも価格的に購入しやすくして、取引先に卸している。売上\n      は、豚コレラの影響や新型コロナウイルスの影響で上下する部分はあるが、年\n       間1000万円ほどである。\n        問：主な販売先との関係性は？\n        答：この事業は、全国的にも早い段階でジビエ事業をスタートしており、新\n      たな顧客からのニーズもあるが、古くからの顧客への対応を大事にしながら、\n      ビジネスを展開している。\n        問：イノシシ捕獲後の狩猟者との連携体制は。\n        答：職員が現場に出向き、ジビエに利用できるか確認を行い、施設まで搬入\n      する体制をとっている。\n        問：イノシシの骨などを炭化処理して肥料にする仕組みについて\n        答：生肉になる部分などを除くと、量的に炭化処理する部分が少なく、コス\n      ト面を考慮して、現在は稼働していない。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":11,"text":"会派視察報告書\n\n\n      【佐藤仁一郎議員】\n       のとしし団の視察を通じて、捕獲から処理、販売に至るまでの一連のプロセ\n      スに高度な技術が導入されていることに強い印象を受けた。特に、前処理室で\n       の殺菌処理、金属検出器による異物検査、-40℃での急速冷凍など、食品として\n      の安全性を確保する仕組みが徹底されている点は、本市のジビエ産業において\n      大きな参考となる。高圧洗浄機や電動ホイストなど最新の処理設備の導入によ\n      り、作業効率と製品品質が両立しており、ビジネスとしての競争力が生まれて\n      いることを確認できた。本市においても、このような技術的な基盤整備が急務\n      であると痛感した。\n\n      【石田政博議員】\n       地域産業振興の観点から、のとしし団の循環型ビジネスモデルに注目した。\n      有害鳥獣対策の奨励金という消費的支出から、捕獲動物を資源として活かす産\n      業創出へのシフトは、地域経済に大きな波及効果をもたらしている。年間売上\n       100万円規模であるが、飲食店からの具体的なニーズに応じた部位ごとの販売\n      を行うことで、顧客の信頼を獲得している。本市のジビエの郷おおさきにおい\n所 感\n      ても、単なる有害鳥獣対策に留まらず、地域産業として経営を自立させるため\n      の商品差別化と販売戦略が不可欠であると認識した。今後の成長に向けて、加\n      工・販売体制の強化と広域販路の開拓が重要であると考える。\n\n      【富田堅治議員】\n       有害獣対策と環境面からの評価を述べたい。能登地域でのイノシシ被害は平\n       成24年の1頭から5年で年間300頭を超えるまでに急増しており、深刻な農業被\n      害が生じている状況は、本市の状況とも共通している。のとしし団は、このよ\n      うな被害対策から産業創出へとシフトさせ、同時に持続可能な取り組みを実現\n      している。廃棄物を炭化装置で肥料化することで、土壌改良にも貢献してい\n      る。単なる対症療法的な有害獣対策ではなく、イノシシという資源を余すとこ\n      ろなく活用する姿勢は、地域の自然環境と経済の両立を実現させるものであ\n      り、本市においても参考にすべき取り組みである。捕獲から販売、廃棄物処理\n      までの一連のプロセスで資源を無駄にしない経営感覚は、持続可能な開発目標\n       （SDGs）の理念とも一致している。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":12,"text":"会派視察報告書\n\n\n       本視察を通じて、大崎市が進めるジビエ産業が、今後さらに発展するために\n      は、以下の点が重要であることを確認した。\n\n       第一に、衛生管理と品質管理を兼備した処理・加工施設の整備である。最新\n      の処理設備の導入により、食品としての安全性と高い品質を確保することで、\n      ビジネスとしての競争力を生むことができる。\n\n       第二に、イノシシ肉の特性や栄養価に基づいた商品企画と販売戦略である。\n      高い栄養価を強みとして、飲食店からの具体的なニーズに応じた部位ごとの販\n      売を行うことで、顧客の信頼を獲得できる。\n総 括\n       第三に、地域資源の循環活用である。捕獲から販売、廃棄物処理までの一連\n       のプロセスで資源を無駄にしない姿勢は、持続可能な開発目標（SDGs）の理\n      念とも一致し、地域の自然環境と経済の両立を実現できる。\n\n       能登の事例に学び、本市においても有害鳥獣対策と地域産業の振興、そして\n       SDGsの達成を一体的に捉える必要がある。加工・販売体制の強化、広域販路\n      の開拓、処理施設の整備、そして地域資源の循環活用への継続的な投資と支援\n      が急務である。会派一同、この視察での学びを今後の政策立案に生かしていく\n      所存である。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":13,"text":"会派視察報告書\n\n\n会 派 名   創清会\n\n視 察 日   令和８年８月６日（木）\n\n視 察 者   佐藤仁一郎、石田政博、富田堅治\n\n視 察 先   石川県羽咋市\n\n視察項目   世界農業遺産の認定と羽咋市の取り組みについて\n\n       世界農業遺産とジビエ推進の羽咋市は世界農業遺産「能登の里山里海」認定と\n       連動した自然栽培の推進で成果を上げており、また、トキ放鳥に関連した里山\n選定理由\n       環境整備を進めている。大崎市においても、農業の持続性確保と地域活性化に\n       向けた実践的知見を得ることを目的として本会派視察を実施した。\n\n       羽咋市議会 議長 酒井一人様\n       羽咋市産業建設部農林水産課 課長補佐 金森章様\n説 明 者\n       羽咋市産業建設部トキ共生室 主任 井戸孝洋様\n       羽咋市議会事務局議事調査課 係長 澤田智子様\n\n        羽咋市は、石川県・能登半島の基部西側に位置し、人口19,187人（2026年8月1\n        日現在）、面積81.84平方キロメートルの小規模自治体である。同市は2011年6\n       月11日、新潟県佐渡市と同時に、日本で初めて世界農業遺産「能登の里山里\n       海」に認定された。\n       同市の最大の特徴は、世界農業遺産認定と連動した「はくい式自然栽培」の推\n       進である。農薬・肥料を一切使用しない自然栽培を地域全体で推進し、その認\n        証制度（HSS、HSS+0）を構築している。令和7年度の取組農家は36戸・\n視察概要    25.8haであり、農業塾の受講生は累計658名に達している。\n       羽咋市とJAはくいは、「総論賛成、各論反対」の初期段階を経て、現在では密\n       接な連携体制を構築しており、全量買取、流通体制の整備、認証制度の運用な\n       どを推進している。同時に、トキの放鳥（令和7年5月31日）に伴う里山環境整\n       備も進めており、化学肥料・化学合成農薬の低減、冬季湛水などの取り組みが\n       展開されている。\n       一方で、労働力不足による面積停滞、収量の不安定性、国庫補助の5年期限とい\n       う課題が残されており、これらの課題解決が今後の推進の鍵となっている。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":14,"text":"会派視察報告書\n\n\n      問：「環境保全型農業」として、具体的にどのような技術的取り組みが行われ\n      ていますか？\n      答： マイクロプラスチック問題の原因となりうる被覆肥料（コーティングされ\n      た肥料）を避けるため、ペースト状肥料の導入や、そこに農薬を混ぜて散布回\n      数を減らす「深層施肥」などの技術を導入しています。また、トキの餌場環境\n      を確保するため、田んぼに水をため続ける「冬季湛水」や、生き物が逃げ込め\n      る「ビオトープ（絵）」の設置を進めています。\n       問：自然栽培の導入にあたり、JAとの関係や農家の反発はありませんでした\n      か？\n      答： 当初、農家やJA内には「資材（肥料や農薬）を販売して利益を出すのが農\n      協の役割なのに、なぜそれを使わない自然栽培を推進するのか」といった戸惑\n      いや反対の声が根強くありました。しかし、農業を持続させるためには今のま\n       まではいけないという危機感から、JAも協力体制を取り、専用の畑を整備する\n      などして連携を深めてきました。\n      問：新規就農者や既存農家への支援策はどのようなものがありますか？\n      答： 国の経営開始資金に加え、市独自でその2割を上乗せして2年間助成する制\n       度や、自然栽培部会への10アールあたり2万円の独自助成などがあります。た\n詳 細      だし、これらは「いつまでも支援に頼るのではなく、5年を目処に自立を促す」\n      という方針へシフトしており、継続して受給していた既存農家への支援は制限\n      を設ける方向で整理されています。\n\n      問：自然栽培の「収量減」という課題に対し、どのように経営を成立させてい\n      ますか？\n      答： 通常の米（約7俵/10アール）に対し、自然栽培米は4俵程度と収量は大き\n       く落ち込みます。そのため、JAによる自然栽培米としての高い価格（30キロあ\n      たり3万円超など）での全量買い取りを保証することで収益を担保しています。\n      また、自然栽培のみでは厳しい層のために、観光農園と組み合わせたり、加工\n      品開発への補助制度を活用したりして収入源を多角化する支援を行っていま\n      す。\n      問：今後の自然栽培の計画や目標はどのようになっていますか？\n      答： 現在の自然栽培面積は約17.6ヘクタールですが、これを令和11年度までに\n       23.9ヘクタールまで拡大する計画です。かつては面積の拡大が最優先でした\n      が、現在は「トキ認証米」への需要が高まっていることを受け、単に自然栽培\n      の面積を増やすことだけでなく、環境と調和した農業全体をブランド化する方\n      向へ軸足を移しています","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":15,"text":"会派視察報告書\n\n\n      富田堅治\n      羽咋市の取組は、単なる農業技術の転換にとどまらず、地域の歴史・文化・生\n      物多様性を「地域資源」として総合的に再定義し、観光や教育（食育）と融合\n      させた点に強みがある。大崎市においても、世界農業遺産地域としての強みを\n       活かし、JA連携の強化や、消費者との直接的な結びつきを意識したブランド化\n      戦略をさらに深化させる必要がある。\n       羽咋市の自然栽培推進が成功した最大の要因は、行政とJAの信頼関係に基づく\n      長期的な連携である。初期段階で丁寧な議論を重ね、時間をかけてお互いの理\n      解し合える土壌を醸成したことが、現在の密接な連携体制につながっている。\n      また、新規農業者への段階的で手厚い支援制度、複数の販売チャネル構築、世\n      界農業遺産認定による地域住民の意識変化も、重要な成功要因であることが確\n      認できた。\n      質疑応答から見えた課題と論点\n       経営の自立化: 自然栽培は高い付加価値を持つ一方、収量低下や労働負担増と\n      いった課題がある。市は助成制度を段階的に自立を促す設計に見直しており、\n      政策的な支援の「出口戦略」が重要となっている。\n       住民・消費者との連携: 自然栽培農業塾などを通じた地域外からの交流人口創出\n所 感      や、学校給食・販路開拓を通じた認知拡大が図られている。一方で、大規模生\n      産への転換と環境保全のバランスには依然として試行錯誤が見られる。\n\n\n      佐藤仁一郎\n       「能登の里山里海」として2011年6月に日本初の世界農業遺産に認定されて、\n      自然と共生しながら農林水産業を続けて来て居る事や震度6弱の被災から復旧だ\n      けでなく「復興」を目指して、神子原米や有機米トキ米等のブランド米の高付\n      加価値化によって農家の収入向上や農業人材の呼び戻しに繋げている点は感心\n      し、参考にしたい。\n\n\n      石田政博\n       「トキが舞うはくい」の取り組みが始まり、今回の視察に先立ち、本年5月と6\n       月に計18羽のトキを放鳥し、トキ共生室を中心に住民参加による環境づくり、\n      観察マナーの普及が進み、農業のみならず観光や市内業者の商品開発に活性化\n      がみられるところは注目でき、参考になる物を大崎市でも検討したい。「トキ\n      ツーリズム」の支援や地域おこし協力隊の募集も併せて参考になった。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"7dc36f400ea25044","year":2026,"faction":"創清会","kind":"activity","title":"報告書(PDFファイル:1.1MB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/soseikai_20260804_06.pdf","page":16,"text":"会派視察報告書\n\n\n      本視察を通じて、世界農業遺産「能登の里山里海」に認定された羽咋市の先進\n      的な取り組みから、多くの学びを得ることができた。\n      羽咋市では、農薬・肥料を使わない自然栽培を独自の認証制度とともに地域全\n       体で推進しており、その成功の背景には行政とJAの強い信頼関係がある。当初\n       は農家やJA内にも戸惑いや反発があったというが、丁寧な対話を重ね、全量買\n      取や流通体制の整備を通じて協力体制を築いてきた点は、大崎市が施策を進め\n      る上でも大いに参考になると感じた。また、新規就農者への段階的な支援策\n総 括    や、直売・観光農園・加工品開発など複数の販売チャネルを組み合わせること\n      で、収量減という課題を抱えながらも自然栽培のみで経営を成り立たせている\n      点も印象的だった。\n      一方で、労働力不足や国庫補助の期限といった課題も明らかになり、支援策に\n      は「出口戦略」を見据えた設計が必要であることも実感した。\n       大崎市においても、JA大崎との連携強化、段階的な支援制度の構築、複数販路\n      の確保、そして労働力確保策の検討を進め、地域資源を活かした農業振興につ\n      なげていきたいと考える。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":1,"text":"会派研修報告書\n\n\n会 派 名   希望の会\n\n研 修 名   令和８年度 第２回市町村等・議会議員特別セミナー\n\n研修日時   令和８年７月２７日（月）～７月２８日（火）\n\n会  場   全国市町村国際文化研修所\n\n参 加 者   平野 洋子\n       1、食と農で紡ぐ「持続可能なまちづくり」\n       大阪府泉大津市長 南出 賢一氏\n       2、生成AIは議会をどう変えるか？ ～住民参加と政策力強化の観点から～\n       早稲田大学デモクラシー創造研究所 招聘研究員 山内 健輔氏\n研修内容   3、公民連携で地域を再生する\n       ～オガールが実践してきた協働のデザイン～\n       株式会社オガール 代表取締役 岡崎 正信氏\n       4、政策議会の質問力\n       法政大学法学部 教授 土山 希美枝氏\n\n       1、食と農で紡ぐ「持続可能なまちづくり」\n       食と農で紡ぐ持続可能なまちづくりは、本市においても重要なテーマであると考え\n       ています。人口約7万人の大阪府泉大津市は、毛布をはじめとする繊維産業や商工\n       業が発展してきた都市であり、農業を主要産業とする自治体ではありません。その\n       ような泉大津市が、学校給食への取組やオーガニック農業の推進など、食と農をど\n       のようにまちづくりに取り入れ、地域の持続可能性につなげているのかを学び、本\n       市における今後の取組の参考とするため選定しました。\n       2、生成AIは議会をどう変えるか？ ～住民参加と政策力強化の観点から～\n       生成AIの急速な普及により、行政や議会においてもその活用が求められる時代と\n       なっています。議会活動における生成AIの可能性や課題、住民参加の促進や政策立\n受講目的\n       案への活用について理解を深め、今後の議会活動に生かすことを目的としました。\n       3、公民連携で地域を再生する ～オガールが実践してしてきた協働のデザイン～\n       岩手県紫波町で実践されている公民連携による地域再生は、全国から注目を集めて\n       います。人口減少や地域課題に向き合いながら、行政と民間が協働で、地域の価値\n       を高めてきた取組が、どのような考え方や手法によって実現されているのかを学\n       び、本市における地域活性化や公民連携の推進に生かしたいと考えました。\n       4、政策議会の質問力\n       議会における一般質問は、行政への質問にとどまらず、政策形成や課題解決につな\n       げる重要な役割を担っています。質問の組み立て方や政策議会に求められる視点を\n       学び、今後の一般質問や議会活動の充実につなげることを目的としました。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":2,"text":"会派研修報告書\n\n\n       １．泉大津市の南出賢一市長による「食と農で紡ぐ『持続可能なまちづくり』」と\n       題した講義では、官民連携・市民共創によるまちづくりについて学びました。自治\n       体が生産者と直接つながるダイレクトサプライチェーンを構築し、生産物の出口を\n       確保することで、農家が安心して生産に取り組める仕組みを作り、学校給食や妊産\n       婦への金芽米の提供、オーガニック給食、食育などを通じて、「食べること」と\n       「農業を守ること」を結びつける取組が紹介されました。また、古米を備蓄倉庫で\n       熟成させ「熟成米」として活用する地域資源を活かした取組についても説明があり\n       ました。さらに、官民連携による図書館「シープラ」の活用や、海の水質改善の実\n       証実験、環境保全の取組、「シーパスパーク」や「GARB GREEN WALK」などを\n       活用した食育や交流の場づくり、食を通じた根本的な健康づくりと医食同源の実践\n研修概要   についても学びました。\n       ２．生成AIの講義では、会議録作成や住民の声の分析・可視化、資料分析など、住\n       民参加と政策形成への活用について学びました。一方、価値判断や最終的な意思決\n       定は議員自身が担うことの重要性も示されました。\n       ３．オガールの岡崎正信氏の講義では、公民連携による地域再生について学びまし\n       た。公共施設の整備を目的とせず、暮らしの質や事業性、地域への波及効果を考\n       え、行政・民間・金融機関が役割を担い、地域内で資金が循環する仕組みの重要性\n       が示されました。\n       ４．土山希美枝氏の講義では、政策議会における一般質問の役割と質問力について\n       学びました。地域にとって必要不可欠な課題を明確にし、事実と分析、主張を整理\n       した上で、政策実現につながる質問を組み立てることの重要性を学びました。\n\n\n       １，食と農で紡ぐ「持続可能なまちづくり」\n       （１）泉大津市概要\n        泉大津市は人口72,921人、面積14.33平方キロメートルの関西のへそに位置し、近\n        畿圏2府4県に40分で行けます。日本一の毛布の街として知られ、毛布の90%以上が\n       泉大津市で生産されています。又、中古車輸出は全国3位。若者に選ばれる自治体\n 詳 細\n        ランキングでは、815市の中で29位にランクインしていて、25歳から39歳の若者の\n       人口も増加しています。泉大津は、かつて、ちぬの海と須恵器の生産拠点として栄\n       え、その地に鎮座する泉穴師神社では、2000年前から稲作が行われ、日本の礎を\n       作りました。現在、泉大津市は1、市民の安全・安心な暮らしを守り2、幸福度向上\n       を目指し 3、広く社会に未来の指針となることを目指しています。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":3,"text":"会派研修報告書\n\n\n      （２）官民連携と市民共創による地域資源を活かしたまちづくり\n      官民連携、市民共創による様々な実例があげられていたので以下に例を挙げます。\n      ①  図書館シープラ \n      市立図書館シープラには、バイオフリックデザイン（みどり、音、香り）を取り入\n      れた癒しの空間がつくられていて、自然がないとギスギスする環境を改善。年間\n       400本のワークショップを開催。3年目には100万人の来場者を記録。本をただ借り\n      に来るというだけでなく、図書館をまちの人が集まる場所にしています。\n      ②  ウォーターフロント \n      無限の可能性を秘めたウォーターフロントには、グランピング、バーベキュー施設\n       Nグリルがあります。3月から12月で2万～2万1千人の来場者を記録していて、地元\n      で働く場所を提供できる上に、お客様も増えています。\n      ③  泉大津フェニックス\n      泉大津フェニックスでは、野外ロックフェスや海釣りイベントを開催。又、水質改\n      善事業を漁業組合と協力して行っていたところ、なぶら発生や、イルカの親子、ウ\n      ニがホースについているなどの自然現象も観察されています。\n      ④  ６００年の御神木の保存 \n       泉大津市では、樹齢600年の御神木を残すことを選択したことを、単なる樹木保存\n      ではなく、地域の自然環境を守り育てる象徴的な取組として捉えています。その結\n詳 細      果として、御神木から「ひこばえ」が生える フクロウ、コウノトリ、タンチョウ\n      が舞い降りる など、生き物が戻ってくる環境が生まれています。\n      ⑤  シーパスパーク \n       シーパスパークは甲子園の500倍の広さ。こちらの公園では、未来の森を、市民と\n       一緒に育てる取り組みを行っています。令和6年7月21日、シーパスパーク内に、\n       緑の中で食や交流を楽しめる民間レストラン「GARB GREEN WALK」がオープ\n      ン。こちらは、公園の中にレストランを置いたのではなく、「レストランも含めて\n       公園を使いこなす」という発想で、GARB GREEN WALKを単なる飲食店としてで\n      はなく、市のイベントや食育、農業、地域産品の紹介などの場としても活用してい\n      ます。こちらでは、結婚式をすると、見知らぬ人が駆けつけるなど、街全体でお祝\n      いする風習が生まれています。\n      ⑥  未病予防への取り組み \n       泉大津ヘルスベースにナノミストサウナを設置し、令和8年8月6日には新潟の会社\n      コロナと提携。全国初となる官民連携で、デトックス効果のあるサウナを拠点とし\n       て提供。10分で滝汗をかき、心臓がバクバクしない疲れないサウナが特徴。予約が\n       殺到しています。2階のカフェでは、無添加化調味料を使用した料理を提供してお\n      り、市民がプロデュースをしています。+ではなく、引き算が大事だということで\n       した。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":4,"text":"会派研修報告書\n\n\n      （３）米を守り、農を守り、命を守るまちづくり\n      米騒動から考える日本の米と農業の課題\n      2年前、なぜ米騒動が起こったのか？ 目先のことに注視するのではなく、日本人\n      の米消費量の減少に着目する必要があります。減反政策と複雑な流通構造により、\n       農家所得は低迷し、農業従事者の平均年齢は70歳に達しています。お米を作ってい\n       ても赤字が60年続いています。お米の消費量は年間120キロから60キロに減少し、\n       収量と作付面積も減少しています。大手商社や中間流通業者による買占め、2024\n      年は過去最大の米輸出を記録しました。これは道徳なき経済と言えるでしょう。\n       「米騒動は約60年かけて起こした人災です。」\n\n\n      食料安全保障と持続可能な農業を支える「出口づくり」\n       東京の食料自給率は0.5％、神奈川県は2％、大阪府は1％と、都市部の食料自給率\n       は低く、これら3地域で日本の人口の約25％を占めています。都市は農山村地帯な\n      しでは生きていけず、安全・安心な食料の安定的供給が不可欠です。泉大津市で\n       は、令和5年3月に「安全・安心な食糧の安定的確保に関する構想」を策定し、「①\n      市民の食（命）を守る 何があっても米は食べていける街」と「②食べることで健\n      康になる医食同源」を掲げました。全国各地を調査し、人吉市、東近江市、日高川\n詳 細    町、野洲市、旭川市、南箕輪村、五戸町、小松市、日野町、吉備、丹波市などの特\n      別栽培米を導入しています。また、毎月、妊婦に出産まで月1回お米を配る取り組\n       みを行い、155トンの米を生産者から直接買う「ダイレクトサプライチェーン」を\n      構築しました。生産者と消費地を直接つなぐことで、農家に安定した「出口」をつ\n      くり、農家所得の向上にもつなげています。「良い時も悪い時も、顔のある連携で\n      支え合っていく」ことの重要性が示されました。さらに、オーガニックビレッジの\n      取り組みでは、生産者が２から１2軒に増加、作付面積を拡大した事例が紹介さ\n      れ、「農家さんは出口があるから頑張れる。出口をつくることが重要」との考えが\n      示されました。\n\n\n      米を通じた市民のつながりと地域の支え合い\n      市民同士がつながると、強い市民同士の交流が生まれます。泉大津市市民限定で、\n       非常事態下における金芽米の特別販売を行いました。5キロ4000円、10キロ8000円\n       で販売し、自治会による共同購入は5キロ3750円でした。お米は重いので直接来れ\n      ない高齢者のところには、若い人が届けました。又、対面販売をすることで、市民\n      同士のつながりを深めています。いざという時に、仕組みを作れば生かすことがで\n      きます。困った時はお互い様。「米万博」では、全国から農産物を購入し、物価高\n      騰対策を行いました。適正な価格で常にお米を買える環境があるのが大切です。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":5,"text":"会派研修報告書\n\n\n      「医食同源」を目指した健康づくりと食育\n        国民医療費は、2017年には43兆710億円、339,900人に達しました。健康づくり推\n      進条例は、１，健康に関する学びの強化、２，健康状態の見える化 ３，食育の推\n      進 ４，健康や医療に関する多様な選択肢作りの4つの柱で構成されています。\n      「医者に委ねるのではなく、学んで選択する力を身につけてください。」\n      人間は自然の一部。子供にとっての一食は、大人にとっての一食とは違います。子\n       供の食事の3分の1は給食でできている。給食は大事。オーガニック給食では、金芽\n      米、自然塩、きび砂糖を使用しています。牛乳を減らし、お茶を飲んでいます。発\n      酵食品、旬の食材、地域食材を取り入れ、トランス脂肪酸を減らしています。給食\n       での、パンは月に1回、金芽米60%、特別栽培米40%を使用しています。ときめき\n      給食も実施しています。おやつは米粉入り。お米をたくさん食べる子供が多いで\n       す。20年前から有機農業をしているという、生産者の方々は、食べている人の顔が\n      見えて嬉しい、感謝していますとの声を頂いています。有機農業を選ぶ理由は、土\n      の微生物が多く、酵素の量が多いからです。生きた、エネルギーの高い食材を届け\n      られます。\n\n      金芽米は、とぎ汁が出ず、白米よりも甘みが強く、栄養価がアップしています。1\n       日1食、金芽米に増やすと、公的医療費が約60%に低減します。令和5年度からス\n      タートした金芽米ですが、妊婦さんが、妊娠中、金芽米を食べて生まれた金芽米ベ\n詳 細\n       イビーは、1300名に達成しました。普段食べる米を少し変えるだけで、妊娠中の体\n       調不良が軽減し、出産した赤ちゃんの体重が増加。1ヵ月検診時の体重増加率が\n       アップし、低出生体重時の割合が7%から3%に激減しました。妊婦さんの体調も良\n       くなっています。ぬかを1枚残すだけで、ビタミンB1が増え、腸を整えます。作る\n      力を生きる力にするために、子供たちの五感を作る力を育む取り組みもしていま\n      す。就学児童から大人まで、だしをとって味噌汁を作る、米を炊く取り組みをして\n      います。\n\n      米の今後の見通しをどう考えるか。未来へのみちしるべ。\n       令和8年5月、コメサミットを設立しました。\n           1 ）官民連携による生産地との 安定生産、安定確保。1,741自治体が米給食を月1\n       回増やした場合、年間6,800トン、約1,400ヘクタール、約40億円の増加になりま\n      す。\n        2） 医食同源の推進。健康な体を作れば、医療費は下がります。\n        3） 古米の概念をなくす。熟成保管技術の普及、熟成米保管を国民運動、国民ビ\n       ジョンに。4年経過してもおいしい熟睡保管庫。（和歌山の東洋精米機製作所。）\n      古い米の方がおいしいです。現在、国家は備蓄が半月ほどしかありません。お米を\n      熟成米にしましょう。農村が維持できながら元気な泉大津、日本を作ります。\n      米は気の源、日本民族の源です。工夫すれば健康になり、環境も良くなります。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":6,"text":"会派研修報告書\n\n\n       ２，生成AIは議会をどう変えるか？ ～住民参加と政策力強化の観点から～\n       （1）生成AIによる議会業務の効率化\n       生成AIは、地方議会の事務負担を軽減するだけでなく、効率化によって生み出され\n      た時間を、議会本来の機能である政策形成や住民との対話に振り向けるための手段\n      として活用できます。\n      議会事務局の業務の中でも負担が大きいものとして会議録作成が挙げられ、浜田市\n       議会では生成AIを活用することで、従来2日程度を要していた会議録作成を半日程\n       度まで短縮し、作業時間を約75％削減した事例が紹介されました。\n      また、墨田区議会では、各会派から提出された意見をもとに、論点整理、意見の集\n       約、提言案の素案作成などに生成AIを活用している。生成AIの活用は単なる時間短\n      縮だけでなく、多数の意見を一定の基準で整理することで、意見集約の客観性を高\n       める可能性もあります。重要なのは、AIによって業務を効率化すること自体を目的\n       とするのではなく、そこで生まれた時間とAIの分析能力を、議会機能の強化にどう\n      活用するかという視点です。\n\n       （2）生成AI時代における「議会と住民との関係」\n       生成AIの普及によって、人々の情報収集の方法そのものが変化しています。従来は\n      検索エンジンで自ら検索語を考え、検索結果から必要な情報を探すことが一般的で\n       したが、現在は、まず生成AIに質問し、AIとの対話を通じて必要な情報を得る行動詳 細\n      が広がっています。この変化は、議会にとって大きなチャンスであると説明されま\n       した。\n       議会が発信する情報が、AIから参照されやすい形で公開されていれば、住民がAIに\n      地域の課題や政策について質問した際に、議会で行われた議論が回答に反映される\n      可能性があります。\n       そのためには、単に議会情報をPDF等で公開するだけではなく、議会で「何が議論\n      されたのか」が検索・参照されやすいテキストデータとして蓄積されていることが\n      重要となります。\n      具体的には、\n      ・議会ウェブサイトの情報を充実させる\n      ・会議録をテキストデータとして公開する\n      ・議会だよりのテキスト化を進める\n      ・議案ごとの情報を整理した「議案カルテ」等を作成する\n      ・速報版の議事情報を迅速に公開する\n      といった取り組みが考えられます。\n      これからの議会情報発信では、「住民が議会のホームページを訪れること」だけを\n       目標とするのではなく、「住民がAIに質問した際に、議会での議論がAIの回答に反\n      映される状態」をつくることが重要になります。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":7,"text":"会派研修報告書\n\n\n       （3）住民参加の課題とオンライン活用\n      議会活動は、「住民の声を聞く→議論する→決める→再び住民の声を聞く」という\n      循環によって成りたちますが、従来の住民参加には、参加できる人が限られる、発\n      言に慣れた人の意見が目立つ、時間的な制約から十分に意見を述べられない、集\n      まった意見を整理することが難しい、集めた意見が議会の議論にどうつながったの\n      か分かりにくい、といった課題がありました。又、住民の意見が集まらないのは、\n      必ずしも、住民に意見がないからではなく、聞き方に問題がある場合もあります。\n      例えば、資料を示したうえで「ご意見をお寄せください」とだけ求めても、住民か\n      らすれば「どこを読めばよいのか」「何について意見を言えばよいのか」が分から\n      ず、前提知識がなければ意見を表明すること自体が難しいのです。その為、住民が\n      自身の経験や問題意識を言葉にしやすいよう、情報の提示方法や問いの立て方を工\n      夫する必要があります。\n\n       （4）生成AIを活用した「ブロードリスニング」こうした課題への対応として紹介\n      されたのが「ブロードリスニング」という考え方でした。ブロードリスニングと\n       は、AI技術を用いて大量の意見を収集・分析・可視化し、政策形成に活用する手法\n       です。2024年東京都知事選挙において安野貴博氏が活用した手法としても紹介さ\n       れ、AIによって多数の意見を整理し、意見の傾向や論点を可視化することができま\n       す。例えば、集められた意見をAIによって類似する内容ごとに「クラスター」とし\n詳 細    て分類し、全体像を把握したうえで、個々のクラスターの具体的な意見を確認する\n      ことができます。これにより、\n      「大量の意見を集める」\n      ↓\n       「AIで整理・分類する」\n      ↓\n      「全体像を把握する」\n      ↓\n      「重要な論点を確認する」\n      ↓\n      「政策議論につなげる」という流れをつくることができます。\n\n       また、AIを使って資料の背景情報を整理したり、論点や住民に聞くべきポイントを\n       抽出したり、誹謗中傷等を事前にチェックしたりすることも可能です。ただし、AI\n      による整理結果をそのまま政策判断に用いるのではなく、最終的には人間が内容を\n      確認し、必要に応じて修正することが重要です。さらに、既に投稿された意見と類\n       似する意見をAIが検出し、新たに意見を投稿する際に、既存の意見へのコメントや\n      内容のブラッシュアップを促す仕組みも考えられます。これにより、単に「意見を\n      集める」だけでなく、住民同士の意見の共有や議論を促し、政策形成につなげるこ\n      とができます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":8,"text":"会派研修報告書\n\n\n       （5）「聞きっぱなし」にしない仕組み\n      住民参加においては、意見を集めるだけでは不十分。「このような意見がありまし\n      た」という共有や感想で終わるのではなく、集めた意見を整理・分析し、議会での\n      政策議論にどのようにつなげたのかを住民に返していくことが重要。住民からすれ\n      ば、自分の意見がどのように扱われたのかが分からなければ、「意見を言っても意\n      味がない」という感覚につながり、次の意見表明への意欲を失う可能性がありま\n       す。そこで、生成AIを活用することで、大量の意見を短時間で整理・分析し、「住\n      民の声→論点→議会での議論→政策判断」という循環をつくりやすくなります。\n\n\n       （6）生成AIを活用した政策力の強化\n       政策検討において生成AIは、\n      ・事実や関連情報を集める\n      ・複数の資料を横断して情報を整理する\n      ・現状や原因を整理する\n      ・異なる立場から検討する\n      ・論点や政策選択肢を示すといった作業に活用できます。\n          特に、ChatGPT等の生成AIには、RAG（Retrieval-Augmented Generation：検索\n      拡張生成）と呼ばれる仕組みがあり、指定した複数の資料の中から必要な情報を検\n      索し、回答を生成することができます。例えば、自治体の各種計画、総合計画、人\n詳 細\n      口ビジョン、地域福祉計画、公共施設等総合管理計画などを対象として、複数の行\n      政文書を横断的に分析することで、従来は人が一つ一つ確認していた情報を効率的\n      に整理することができます。ただし、「○○について教えてください」と質問する\n       だけでは、生成AIの能力を十分に活用しているとはいえなくて、SWOT分析などの\n      分析手法と組み合わせることで、より政策検討に適した使い方が可能になります。\n       一方、行政文書をもとにSWOT分析を行った場合、その結果は、既存の行政認識や\n       前提に基づく「仮説」であることにも注意が必要で。AIの分析結果を事実そのもの\n      と捉えるのではなく、政策検討のための仮説として扱い、必要な検証を行うことが\n      重要です。\n\n       （7）ペルソナを活用した多様な立場からの政策検討\n      政策を検討する際には、特定の立場だけで考えるのではなく、利害や価値観の異な\n       る複数の立場から検討する必要があります。その手法として、AIと「ペルソナ」を\n      組み合わせる方法が紹介されました。手順としては、まずデータセットを確認し、\n      テーマに関係する属性を抽出する。そのうえで、意見や利害関係の異なるおおむね\n       10程度のグループに分類し、それぞれを代表するペルソナを設定します。その後、\n      複数のペルソナによる政策対話を行い、異なる立場から意見を出し合うことで、政\n      策の論点を可視化します。この方法により、議員自身の視点だけでは見落としやす\n      い課題や、政策によって影響を受ける人の立場を仮想的に検討することができま\n      す。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":9,"text":"会派研修報告書\n\n\n       （8）論点の構造化・可視化\n       生成AIを使って政策課題を整理する際には、単なるアイデア出しにとどめず、「論\n      点を構造化する」ことが重要だということで、講義では、マーメイド記法を用い\n      て、課題の構造を図式化する方法が紹介されました。\n      例えば、\n      「結果として何が起きているのか」\n      ↓\n      「その原因は何か」\n      ↓\n      「原因に対してどのような打ち手があるのか」\n      という形で整理することで、問題と原因、政策手段を分けて考えることができま\n       す。生成AIを活用することで、思いつきによるアイデア出しから、仮説の整理・検\n       証へと政策検討の質を高めることができます。又、AIを使って抜け漏れを確認しな\n      がら、論点を整理することで、議論の前提条件をそろえ、「何について議論してい\n      るのか」を明確にすることにもつながります。\n\n詳 細\n       （9）AI時代における議員の役割\n       講義の最後に、生成AIにはできないことについて説明がありました。ブロードリス\n      ニングによって大量の住民の声を集めることができても、そのすべてを政策として\n       採用することはできません。RAGによって大量の情報を整理することができても、\n       「どの情報を重視するのか」をAIが決めることはできません。ペルソナによって多\n      様な立場から検討できても、「誰の不利益をどこまで許容するのか」という価値判\n       断をAIに委ねることはできません。つまり、AIによって情報や選択肢が増えれば増\n       えるほど、最終的には人間による価値選択と価値判断が重要になる。AI時代の議会\n      には、これまでリアルな場だけでは聞くことができなかった住民の声を集め、自分\n      一人の頭だけでは思いつかなかった政策案を検討し、多くの判断材料を得ることが\n      可能になる一方、それらを全て採用することはできないという難しさも生じます。\n       従って、重要なのは「AIに使われる」のではなく、「AIを使いこなす」ことです。\n       生成AIの具体的な操作方法を覚えるだけではなく、「何のためにAIを使うのか」と\n      いう目的を明確にし、住民参加の拡充や政策形成能力の向上という議会本来の目的\n      に沿って、戦略的に活用することが求められます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":10,"text":"会派研修報告書\n\n\n      ３，公民連携で地域を再生する～オガールが実践してきた協働のデザイン～\n       （1）人間を主体としたまちづくり\n      岡崎氏は、まちづくりを考える際には、行政や施設を起点とするのではなく、「人\n      間を主体に考える」ことが重要であると説明しました。暑ければ人は外に出てこな\n      いことから、緑や日陰など、人が気持ちよく過ごせる環境をつくることが必要。\n      「どうしたら人が来てくれるのか」ではなく、「人にとって気持ちの良い、居心地\n      の良い空間とは何か」という視点の重要性を示されました。具体例として、オガー\n       ル祭りの開催時期を8月から7月初旬に前倒ししたところ、全体の売上が1.85倍に\n      なった事例を紹介し、気候や空間など、人間の行動特性を踏まえてまちをデザイン\n      することの重要性を説明されました。\n\n       （2）公共施設を不動産価値の視点から考える\n      事業を成立させる要素として、「不動産の価値」「金利」「建設コスト」の三つが\n      あげられました。公共施設や公共空間の整備、リノベーションを考える際にも、単\n      に施設の整備費や機能だけを見るのではなく、その施設を整備することで、土地や\n      周辺地域の不動産価値が高まるのかという視点が必要。優れた公共施設の周辺では\n      不動産価値が高まり、逆に公共施設を適切に育てることなく乱立させるだけでは、\n      周辺エリアの不動産としての魅力は高まらないとの考えを示されました。\n\n       （3）紫波町の課題とオガールプロジェクト\n詳 細\n       紫波町は人口約3万3,000人の町で、盛岡市と花巻市の間に位置するベッドタウンと\n       しての性格を持ち、昼夜間人口比率は県内で最も低い状況。町では1998年にJR紫\n        波中央駅前の10.7haの土地を28億5,000万円で取得したが、その後、税収減等によ\n       り再開発が進まず、約10年間活用されない状態が続きました。\n       その後、2007年に公民連携に向けた取組が進められ、2009年には「紫波町公民連\n      携基本計画」が策定され、オガールプロジェクトが本格的に始動しました。岡崎氏\n      は、この土地を活用し、民間主導の公民連携によって地域の価値を高める取組を進\n       めました。\n\n       （4）金融機関との対話と事業性\n      岡崎氏は、「人に信用させたかったら、そいつを儲けさせよ」という考え方を示\n      し、公民連携を進める上では、金融機関が納得する、市場対話が重要であると説明\n      されました。行政だけで事業を判断するのではなく、政府系金融機関や市中金融機\n      関とも協議し、事業として成立するかどうかを厳しく検証することによって、地域\n      内で資金が循環する仕組みをつくっていくことが重要だということを示しました。\n       又、岡崎氏自身も事業者として最高33億円の借入を経験し、そのうち26億円はノン\n      リコースローンによるプロジェクトファイナンスであったそうです。民間事業者自\n      身がリスクを負いながら事業を成立させることの重要性についても述べられまし\n      た。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":11,"text":"会派研修報告書\n\n\n       （5）図書館を核とした官民複合施設\n      オガールプラザは、図書館・地域交流センター・子育て応援センターなどの公共施\n      設と、産直市場、カフェ、飲食店、学習塾、クリニック等の民間テナントを組み合\n       わせた官民複合施設です。この施設は、特定目的会社（SPC）であるオガールプラ\n      ザ株式会社が整備・管理・運営を担い、民間資金や金融機関からの融資等を活用し\n      て事業を成立させました。公共施設を単独で整備するのではなく、集客力のある図\n      書館と民間の収益施設を組み合わせることで、施設全体として事業性を持たせる仕\n      組みについて説明がありました。図書館は「人が来れば来るほど行政側にはコスト\n      がかかる施設」である一方、民間施設にとっては人が来ることが、事業機会につな\n      がるという関係性を活用し、公共施設を地域の集客装置として位置づけている点が\n      特徴です。\n       （6）オガールアリーナ、住宅、保育園\n      オガールアリーナについては、日本初のバレーボール専用アリーナとして整備し、\n      小さな市場であっても競合の少ない分野に特化することで、施設の稼働率を高める\n      考え方が紹介されました。バレーボールを核として国内外から選手や関係者を呼び\n      込み、併設する宿泊施設などへの利用にもつなげる事業モデルについて説明があり\n      ました。住宅については、単に住宅そのものを販売するのではなく、「あたたかい\n      か、涼しいか」といった住宅性能や「良い暮らし」を価値として提供することが重\n       要であるとし、オガールタウンでは57区画の住宅地を整備し、紫波型エコハウスの\n詳 細\n      考え方を取り入れています。また、保育園についても、単なる子育て支援施設では\n      なく、働く世代の就労を支える機能として捉え、地域の暮らしを支える施設として\n      整備していることが紹介されました。\n       （7）「経営者を先に決める」という事業構築\n      施設整備について岡崎氏は、建物を設計・建設してから「誰が運営するのか」を考\n      えるのではなく、「まず経営者を決めること」が重要であると指摘しました。「誰\n      が経営するのか」を明確にした上で、建設、設計、運営、継続可能性を検討し、\n      「誰と一緒に事業を進めるのか」を決定する。このように、施設を建設することを\n      目的とせず、将来にわたって事業として継続できる仕組みを先に考えることが重要\n       であると説明しました。\n       （8）公民連携の考え方\n      公民連携については、インフラの老朽化や限られた財源など、行政だけでは対応が\n      難しい課題に対して、行政と民間それぞれの強みを組み合わせることが重要です。\n      行政には、公権力や予算執行、制度を運用する権限がある一方、民間には事業を成\n      立させ、継続させる力がある。双方がそれぞれの役割と責任を担い、適切に組み合\n      わせることによって、持続可能な地域づくりにつなげることができるとしました。\n      また、「公権力を上手に使いこなす官と民が存在する地域には可能性が宿る」と\n      し、公民連携には行政側の覚悟、実行力、継続的な関わりが必要であると述べられ\n       ました。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":12,"text":"会派研修報告書\n\n\n       （9）公民連携を成功させる10の原則\n       公民連携を成功させるための10の原則として、①入念に準備する、②共有ビジョン\n      を描く、③相手と関係者を理解する、④リスクとリワードを明確にする、⑤明確な\n      意思決定プロセスをつくる、⑥全員が宿題をやり切る、⑦一貫したリーダーシッ\n      プ、⑧早く頻繁に伝える、⑨公正なディール構造、⑩信頼を中核価値として導く、\n       という考え方が示されました。さらに、「覚悟なきPPPは、始めてはいけない」\n       「PPPは事業プロダクトではなく、プロセスである」と述べ、公民連携を単なる事\n      業手法として導入するのではなく、関係者が責任と覚悟を持って継続的に協働する\n      ことの重要性を強調されました。講義の最後には、「その土地の価値をどう高める\n      のか」という問いが示され、地域づくりを考える上で、施設の整備だけではなく、\n      不動産価値、事業性、暮らしやすさ、地域経済の循環を総合的に捉えることの重要\n      性が示されました。\n      ４，法政大学法学部 教授 土山 希美枝氏 政策議会の質問力\n      （１）一般質問とは何か\n      講義では、地方議会における一般質問について、「たかが一般質問、されど一般質\n      問」という視点から、その意義について説明がありました。\n      一般質問は、地方自治法に直接定められた必須の仕組みではなく、議員個人のパ\n詳 細\n      フォーマンスの場として捉えるのではなく、議会改革や政策議論につなげていくこ\n      とが重要である。一方で、一般質問は、政治家であり、同時に議会の一員でもある\n      議員の知見や活動を集約し、地域の政策課題を議会の場で提起する機会でもある。\n      議会活動の中でも市民から見えやすく、議員にとっても重要な場であることから、\n      「議員必携」の実質的な意味はどこにあるのかを考える必要があるとの問題提起が\n       ありました。\n\n      （２）自治体は何のためにあるのか\n      一般質問のあり方を考える前提として、「自治体は何のためにあるのか」という問\n      いが示されました。自治体は、市民が必要不可欠とする政策・制度を整備するため\n      の機構であり、自治体の仕事は、さまざまな事業や制度として具体化されている。\n      良い自治体とは、単に多くの事業を実施する自治体ではなく、市民にとって必要不\n      可欠な政策・制度を適切に整備し、その政策・制度の効果を高めている自治体であ\n      るとの考え方が示されました。その際、「何が必要不可欠なのか」「どの政策の効\n      果が高いのか」を考えることが重要となります。しかし、地域課題は無限に存在す\n      る一方、財源や人員などの行政資源には限りがあります。そのため、すべての課題\n      に対応することはできず、何を優先するのかという政策判断が必要になります。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":13,"text":"会派研修報告書\n\n\n      （３）政策には唯一の正解がない\n      政策は、現在の状況から出発し、描いた未来に到達するための手段である。しか\n      し、政策には数学の問題のような唯一の正解があるわけではない。\n      そのため、自治体には、さまざまな選択肢の中から何を選ぶのかという「決断」が\n      必要になる。もし政策に唯一の正解が存在するのであれば、議論に多くの時間を費\n      やす必要はない。しかし、正解がないからこそ、議論を通じて選択肢を比較し、自\n      治体として決断することが重要となります。そして、その自治体としての政策決定\n      において、最終的に重要な役割を担うのが議会です。市民から信託・負託を受けた\n      議会が、その責任にどう応えていくのかが問われています。\n\n      （４）一般質問で何を問うのか\n      一般質問では、質問したいことを多く盛り込めばよいわけではない。論点を詰め込\n      みすぎることで、かえって質問の焦点がぼやけ、行政側からも噛み合わない答弁が\n      返ってくることがあります。そこで、「わが街にとって、これは必要不可欠な政策\n      課題である」と自ら定義し、その課題について何を確認し、何を引き出したいのか\n      を明確にすることが重要です。特に、質問を組み立てる際には、最終的に「これだ\n      けは引き出したい」というポイントを明確にし、そのための質問の順序や戦略を考\n      えておく必要があります。\n詳 細\n      （５）「事実」と「意見」を整理する\n      質問を論理的に組み立てるためには、事実と意見を区別することが重要です。基本\n      的な整理として、\n      事実＝現在の状況、問題となっている状況\n      分析＝その事実から何が言えるのか\n      主張＝その分析を踏まえて何を実現したいのか\n      という構造で整理します。また、過去の議会答弁なども重要な「事実」として確認\n      し、これまで行政がどのような認識を示してきたのかを踏まえた上で質問すること\n      が求められます。\n\n      （６）結論を意識した質問の組み立て\n      質問では、最終的に何を確認したいのかを明確にし、その結論に向けて質問を組み\n      立てる「結論サンドイッチ」の考え方が紹介されました。\n      単に「どう考えていますか」と尋ねるのではなく、現状や事実を確認し、そこから\n      導かれる問題意識を共有した上で、自分の主張につなげていく\n      事実 → 分析 → 主張 → 問いという流れを意識し、行政側と問題意識を共有しなが\n      ら、最後に必要な答弁を引き出していくことが重要です。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":14,"text":"会派研修報告書\n\n\n      （７）「噛み合う答弁」を得るための準備\n      質問と答弁が噛み合わない原因の一つは、質問する側と答弁する側で問題意識や論\n      点の認識が共有されていないことにあります。そのため、質問前の準備として「論\n      点メモ」を作成し、自分が何を問題として捉え、どのような事実を確認し、最終的\n      に何を引き出したいのかを整理しておくことが重要です。特に、「これだけは引き\n      出したい」という一点を明確にしておくことで、質問の途中で論点が拡散すること\n      を防ぐことができます。さらに、質問内容については、議員や行政職員だけが理解\n      できればよいのではなく、一般の市民が聞いても「確かにそうだ」と理解できるこ\n       とが重要です。その目安として、「15歳の人が聞いても分かるように」という視点\n      が示されました。詳 細\n\n      （８）監査・検証の重要性\n      政策を議論するためには、現在行われている事業や制度が実際にどのような状況に\n      あるのかを把握する必要があります。そのため、行政の事業や制度を検証する視\n      点、いわば「監査」の視点を持つことも重要です。既存の事業について、目的に対\n      してどのような効果が出ているのか、必要性や有効性があるのかを確認すること\n      で、新たな政策課題を発見したり、政策の改善につなげたりすることができます。\n      一般質問は「行政に質問して答弁をもらう場」ではなく、地域にとって必要な政策\n      課題を明確にし、事実に基づいて議論し、議会としての政策判断につなげるための\n      重要な活動です。\n\n      １．食と農で紡ぐ「持続可能なまちづくり」\n      （１）泉大津市での取り組みは、食と農だけでなく、健康、子育て、食育、防災、\n      環境保全、地域づくり、図書館等、さまざまな視点から大崎市でも参考にできるも\n      のが多い講義でした。大崎市とは異なり、泉大津市は米の消費地であり、生産地で\n      はなく、農業を主要産業とする自治体でもありません。そのような泉大津市が、食\n所 感    と農を市民の健康や命を守るための重要な政策として位置付け、積極的に取り組ん\n      でいることに特に感銘を受けました。中でも印象に残ったのが、「医食同源」とい\n      う考え方です。食を単なる生活や産業の一部として捉えるのではなく、食を通じて\n      市民の健康を守り、ひいては「命」を守るという視点で、食育、子育て、高齢者支\n      援、農業振興などをつなげている点に大きな学びがありました。泉大津市の取り組\n      みを参考に、本市で取り入れる場合の可能性について、以下に7点、考察します。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":15,"text":"会派研修報告書\n\n\n      ① 生産者と消費者をつなぐ「ダイレクトサプライチェーン」\n      泉大津市では、全国の農家から米を直接購入し、市民に届ける「ダイレクトサプラ\n      イチェーン」の仕組みを構築しています。講義の中で示された、「出口があるから\n      農家さんは頑張れる。」という言葉が特に印象に残りました。大崎市では、オーガ\n      ニックビレッジ宣言を行い、有機農業を推進していますが、有機農業に取り組む生\n      産者を増やしていくことは課題となっています。有機農業を推進するためには、生\n      産者への支援だけでなく、「作ったものを誰が買うのか」という出口まで考えるこ\n      とが重要です。\n      例えば、学校給食や公共施設での利用、市内の小売店・飲食店との連携など、行政\n      が一定の需要を増やすことで、生産者が安心して有機農業に取り組める環境を整え\n      ることができます。これは農業振興だけでなく、子どもたちの食育や健康、地域内\n      での経済循環にもつながる可能性があると考えます。\n      ② 米を「備蓄」から「食料安全保障」と「農業振興」へ\n      泉大津市では、現在「古米」とされる米を一定期間保管し、「熟成米」として活用\n      する官民連携の取り組みが行われています。大崎市は米の生産地ですが、昨今の米\n      不足や、災害、天候不順などへの備え、市民が安定して食料を確保できる仕組みを\n      持つことは重要です。市が一定量の米を確保することは、単なる災害備蓄にとどま\n      らず、\n      ・市民の食料安全保障\n所 感    ・生産者の安定した販売先の確保\n      ・米の消費拡大\n      ・災害時の食料確保\n      など、複数の政策効果を生み出す可能性があります。「備蓄」と「農業振興」を\n      別々に考えるのではなく、地域で生産された米を地域で支える仕組みとして検討す\n      ることは、本市にとっても意義があると考えます。\n      ③ 米を炊く、みそ汁を作るという「生涯を通じた食の力」\n      こどもから大人まで、誰もが米を炊き、みそ汁を作ることができるようにする泉大\n      津市の食育の考え方も印象的でした。\n      これは単なる料理技術の習得ではなく、\n      ・健康づくり\n      ・食文化の継承\n      ・自立した生活\n      ・災害時に自分で食事を準備する力にもつながります。\n      また、これは子どもだけの問題ではありません。高齢世帯が増える中、高齢者が自\n      分で食事を整える力を維持することは、健康維持や自立した生活を続けることにも\n      つながります。そのため、食育を子どもだけの施策として捉えるのではなく、子ど\n      もから高齢者まで、生涯を通じて食を自分で整える力を育てる取り組みとして考え\n      ることが重要です。公民館や地域活動などと組み合わせれば、高齢者の食生活支援\n      や世代間交流の場として展開することもできると考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":16,"text":"会派研修報告書\n\n\n      ④ 「医食同源」を大崎市の農業と健康づくりにつなげる\n      泉大津市の「医食同源」という考え方は、本市においてこそ活かせる可能性があり\n      ます。大崎市には、大崎耕土をはじめ、豊かな農産物や有機農業に取り組む生産者\n      がいます。又、地域内には温泉という地域資源があります。こうした農業や地域資\n      源を、農業振興だけの視点で捉えるのではなく、市民の健康を守るための資源とし\n      て捉え直すことが重要です。例えば、\n      ・妊産婦への食を通じた支援\n      ・子どもへの食育\n      ・学校給食における地元農産物のさらなる活用\n      ・高齢者の低栄養予防 ・温泉を養生施設としてとらえ、そこに、食をとりいれ\n      る。など、「食」と「健康」を結び付けることが考えられます。\n      又、泉大津市では、妊婦に対して定期的に金芽米を届ける取り組みを行っていま\n      す。妊娠期の栄養状態は母体と胎児の健康に関わる重要な時期であり、行政が\n      「食」を通じて具体的に支援する仕組みは、本市においても参考になります。ま\n      た、泉大津市だけではなく、お隣の加美町でも官民連携による金芽米の学校給食へ\n      の導入が始まっています。大崎市でも、金芽米の導入なども含め、妊産婦や子ど\n      も、高齢者などへの食を通じた健康支援について検討する価値があると考えます。\n      重要なのは、「農業を守るために市民に食べてもらう」のではなく、「地域資源や\n      食を通じて市民の健康を守ることが、結果として地域の農業を守る」という循環を\n所 感      つくることだと考えます。\n\n      ⑤ 「制度や商品を届ける」だけでなく、「人を介して届ける」\n      泉大津市では、米を直接市民に届ける取り組みを通じて、単に商品を届けるだけで\n      なく、人と人とのつながりを生み出しています。この考え方は、大崎市の行政サー\n      ビスや地域の取り組みにも応用できるのではないかと考えます。例えば、みやポの\n      ような電子クーポンを配布する場合、スマートフォンの操作や電子決済に不慣れな\n      高齢者が取り残される可能性があります。そこで、電子クーポンを配布するだけで\n      はなく、地域の人を「デジタルサポーター」として配置し、使い方を教えたり、実\n      際の利用を支援したり、困りごとを聞いて必要な支援につないだりする仕組みが考\n      えられます。同様に、米についても、若い世代が地域の高齢者世帯に米を届ける仕\n      組みをつくれば、米の消費拡大だけでなく、高齢者の買い物支援や見守り、世代間\n      交流にもつながります。また、大崎市でも、すでに各地域でマルシェやお祭り、市\n      が、開催され、農産物や加工品などを、生産者や地域の事業者から直接購入し、\n      「顔の見える人から買う」ことを楽しむ市民の姿があります。こうした場は、単な\n      る販売の場ではなく、生産者と消費者が顔を合わせ、会話を交わし、地域の情報や\n      思いを共有する場にもなっています。既存の取り組みをさらに活かし、それらの場\n      を地域の交流拠点として位置付けることで、買い物やイベントをきっかけにした見\n      守りや世代間交流、地域の情報交換、新たな活動のきっかけづくりにも発展させる\n      ことができるのではないかと考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":17,"text":"会派研修報告書\n\n\n      これらは一見異なる取り組みに見えますが、共通しているのは、「制度や商品だけ\n      を届けるのではなく、人を介して届ける」という考え方です。行政サービスのデジ\n      タル化が進む中だからこそ、単に人の手を減らすのではなく、デジタルを活用しな\n      がら、地域の中に「つなぐ人」を増やしていくことが重要です。そして、米を届け\n      ること、デジタルの使い方を教えること、マルシェや市で買い物をすることなど、\n      日常の小さな接点を通じて人と人がつながることで、見守り、交流、地域経済、地\n      域の支え合いへとつながる可能性があると考えます。\n\n      ⑥ 施設や地域資源を「人が集まり、交流や活動が生まれる場所」へ\n      泉大津市のシーパスパークや泉大津フェニックス、そして図書館「シープラ」の取\n      り組みから学んだのは、施設や場所を単に「利用するための場所」として捉えるの\n      ではなく、人が集まり、交流し、新しい活動が生まれる場所として活用するという\n       考え方です。泉大津市では、図書館で年間約400ものイベントが開催されており、\n      本を借りる・読むという本来の機能に加えて、さまざまな人が訪れ、交流する場と\n      しての機能を持たせています。大崎市でも、図書館の貸出冊数など、本来の図書館\n      機能については高い利用があります。今後は、図書館を「本を借りる場所」だけで\n所 感      なく、市民が集まり、学び、交流し、新しい活動を始める場所としてさらに活用で\n      きるのではないかと考えます。例えば、地域の生産者による食育イベント、子ども\n      向けのワークショップ、高齢者と若者の交流、地域活動の紹介、マルシェやキッチ\n      ンカーとの連携など、図書館を核としてさまざまな活動をつなぐことが考えられま\n      す。同じ考え方は、泉大津市のシーパスパークや泉大津フェニックスにも見られま\n      す。新しい施設をつくることそのものではなく、「ここで何かをしたい」「ここに\n      行ってみたい」と思える理由をつくることで、人が集まる場所にしていることが重\n      要だと感じました。\n\n      大崎市にも、江合川、潟沼、化女沼、蕪栗沼などの水辺、森や里山、田園、温泉地\n      など、多くの地域資源があります。また、すでにマルシェやキッチンカーなど、市\n      民や事業者が主体となった活動も行われています。こうした既存の場所と活動を組\n      み合わせ、水辺なら水辺、森なら森、図書館なら図書館、それぞれの特徴を活かし\n      て「人が集まる理由」をつくることが重要です。新しい施設を建設することだけが\n      地域づくりではなく、既にある場所に新しい使い方や活動を生み出すことによっ\n      て、地域の価値を高めることができると考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":18,"text":"会派研修報告書\n\n\n      ⑦ それぞれの地域が個性を活かし、「地域から地域へ」つなぐ\n      大崎市には、古川、岩出山、田尻、三本木、鹿島台、松山、鳴子（鬼首）、それぞ\n      れ異なる歴史、文化、自然、産業を持つ地域があります。\n      重要なのは、すべての地域に同じ施設や同じイベントをつくることではなく、それ\n      ぞれの地域が持つ個性や資源を活かし、「ここに行ってみたい」「ここで何かをし\n      てみたい」と思える場所や機会をつくることです。\n      例えば、\n      ・古川は、行政、商業、交通、文化などの機能が集まる大崎市の中心地域であり、\n      人を集め、情報を発信し、各地域をつなぐ「交流と発信の拠点」\n      ・岩出山は、歴史や文化、伊達家ゆかりの地域資源を活かしたまち\n      ・三本木は、ひまわりなどの自然や地域資源を活かしたまち\n      ・松山は、酒や歴史、文化、コスモスを活かした地域\n      ・鳴子は、温泉、こけし、自然などを活かした観光・交流\n      ・鬼首は、豊かな山や自然、アウトドアなどを活かした体験型の交流\n      ・田尻は、蕪栗沼や農業、歴史など、豊かな自然と食を活かした交流\n      ・鹿島台は、農産物や地域イベントなどを活かした地域内外との交流\n      など、それぞれに「人が集まる理由」となり得る資源があります。こうした地域の\n      特色を活かすためには、新しい施設を一からつくることだけではなく、すでにある\n      場所や自然、公共施設、地域の人、マルシェやキッチンカーなどの活動を組み合わ\n所 感    せることが重要です。\n\n      例えば、古川では図書館や駅、まちなかなど、人がすでに集まる場所を活かして各\n      地域の魅力を発信し、岩出山や松山、鳴子、田尻などの地域で開催されるイベント\n      やマルシェ、農産物、文化、観光などにつなげることが考えられます。「古川に来\n      た人が、次は岩出山へ行ってみる」「鳴子を訪れた人が、田尻の自然や農業にも触\n      れる」「松山の文化に触れた人が、三本木や鹿島台にも足を運ぶ」といった、人の\n      流れをつくることができれば、各地域がそれぞれに活性化するだけでなく、大崎市\n      全体の交流人口や地域内の経済循環を生み出すことにもつながります。\n      また、これは観光客だけの話ではありません。市民にとっても、自分が暮らしてい\n      る地域以外の大崎市を知り、訪れ、地域の人と交流する機会になります。大崎市に\n      は、すでに多くの「場所」「人」「資源」「活動」があります。それぞれを個別に\n      捉えるのではなく、古川を一つの拠点として各地域の魅力をつなぎ、さらに各地域\n      同士をつなぐことで、大崎市全体を一つの大きな交流の場として捉えることができ\n      るのではないかと考えます。 以上、7点を泉大津市の街づくりの中から、大崎市\n      での視点として、考察しましたが、今回の講義を通じて、泉大津市の取り組みをそ\n      のまま大崎市に取り入れるのではなく、「大崎市なら何ができるのか」という視点\n      で考えることができました。今回得た比較軸を今後の政策や議会活動に活かし、大\n      崎市にすでにある資源や人の力をつなぎながら、地域の新しい可能性を引き出して\n      いきたいと考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":19,"text":"会派研修報告書\n\n\n\n       ２．生成AIは議会をどう変えるか\n      （１）「業務効率化」から「議会機能の強化」へ\n       今回の講義で特に印象に残ったのは、生成AIを単なる業務効率化のための道具とし\n      て捉えるのではなく、「住民の声を政策につなぐこと」と「議会の政策形成力を高\n       めること」に活用するという視点です。浜田市議会では、生成AIの活用によって会\n      議録作成時間を大幅に短縮し、墨田区議会では各会派から提出された意見の集約や\n       提言案の作成に活用している事例が紹介されましたが、重要なのは、AIによって作\n      業時間を削減することそのものではなく、そこで生まれた時間を、住民との対話や\n      地域課題の調査、政策研究など、議会本来の機能を高めるために活用することで\n       す。大崎市議会においても、すでにICTを活用した議会運営が進められていること\n       から、生成AIの導入についても「業務を効率化する」だけでなく、効率化によって\n      生まれた時間を、政策形成や住民との対話にどう振り向けるかという視点が重要だ\n      と考えます。\n\n\n所 感       （２）「情報公開」から「AI時代の情報発信」へ\n      大崎市議会では、すでに議会だより、会議録、議会中継・録画配信、議会ホーム\n      ページなどを通じて、議会情報を市民に公開しています。従って、今回の講義から\n      学ぶべきことは、「情報を公開する仕組みを新たにつくる」ことではなく、現在公\n       開している情報を、生成AI時代に合わせてさらに活用しやすい情報へ進化させるこ\n      とだと考えます。これからは、住民が議会のホームページを直接訪れるだけでな\n       く、生成AIに「大崎市ではこの問題についてどのような議論がされたのか」と質問\n      し、その回答を通して議会情報に触れる機会も増えていくと考えられます。そのた\n      め、議会で何が議論され、どのような論点があり、どのような判断がされたのか\n       を、AIが参照しやすいテキストデータとして整理しておくことが重要です。例え\n      ば、議案ごとに「何が課題なのか」「議会でどのような質疑があったのか」「どの\n      ような意見が出されたのか」「最終的にどのような議決になったのか」を整理する\n      「議案カルテ」のような仕組みも考えられます。大崎市議会がこれまで積み重ねて\n      きた情報公開を、単なる「公開」から「住民が必要な情報にたどり着ける情報発\n       信」へ進化させることが、AI時代の議会には求められると考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":20,"text":"会派研修報告書\n\n\n      （３）「住民の声を聞く」から「声を政策につなぐ」へ\n      大崎市議会では、議会報告会や意見交換会など、市民の声を聞くための取り組みも\n      行っています。一方で、住民参加には、参加できる人が限られること、発言しやす\n      い人の声が中心になりやすいこと、集まった意見を整理・分析して政策議論につな\n      げることが難しいことなどの課題があります。講義で紹介された「ブロードリスニ\n       ング」は、オンライン等を活用して幅広い住民の意見を集め、生成AIによって類似\n      する意見を分類し、論点を整理・可視化する手法です。大崎市においても、従来の\n       対面型の意見交換会などを大切にしながら、オンラインによる意見募集とAIによる\n      分析を組み合わせることで、これまで参加しにくかった若い世代や子育て世代、仕\n      事などで時間の制約がある人などからも意見を集められる可能性があると感じまし\n      た。そして重要なのは、「意見を集めること」で終わらせないことです。「住民の\n       声を聞く→AI等で整理・分析する→議会で論点を議論する→政策につなげる→結果\n      を住民に返す」という循環をつくることが必要です。住民の声を単に「聞いた」で\n      終わらせるのではなく、議論や政策につなげ、さらにその結果を住民に返してい\n所 感    く。この循環をつくることは、「声を聴き、つなぎ、カタチにする」ということに\n      つながるのではないかと考えます。\n\n\n       （４）AIを活用して議員の政策形成力を高める\n       生成AIは、住民参加だけでなく、議員自身の政策調査・政策形成にも活用できま\n       す。講義では、複数の行政資料を横断した分析、SWOT分析、異なる立場を想定し\n      たペルソナによる検討、論点の構造化・可視化などの手法が紹介されました。大崎\n      市には、総合計画をはじめ、人口、福祉、農業、公共交通、子育て、公共施設な\n       ど、多くの計画や行政資料があります。これらを生成AIで横断的に分析すること\n      で、一つの政策課題を単一の分野だけで捉えるのではなく、複数の政策分野との関\n      係から考えることが可能になります。例えば、「高齢者の孤立」という課題一つを\n      とっても、福祉だけではなく、公共交通、地域コミュニティ、デジタル化、公共施\n       設、図書館など、さまざまな分野と関係しています。生成AIを活用して大量の情報\n      を整理し、課題の構造や政策の選択肢を可視化することは、議員の調査力・政策形\n      成力を高める有効な手段になると考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":21,"text":"会派研修報告書\n\n\n\n       （５）AIに判断を委ねるのではなく、「人」が使いこなす\n       一方で、AIは情報を整理・分析し、多様な選択肢を示すことはできても、「何を大\n      切にするのか」「誰を優先するのか」「誰の不利益をどこまで許容するのか」と\n       いった価値判断をすることはできません。情報や選択肢が増えるAI時代だからこ\n      そ、議員には、地域の将来像や政策の目的を明確にし、自ら考え、判断する力がこ\n      れまで以上に求められます。大崎市議会においても、すでにある議会だより、会議\n      録、議会中継、ホームページ、住民との意見交換などの仕組みを基盤として、そこ\n       に生成AIを組み合わせることで、情報公開、住民参加、政策形成をさらに一段高め\n       ていくことができるのではないかと考えます。そして最終的に目指すべきは、AIに\n       使われるのではなく、AIを使いこなすことです。AIによって情報を集め、整理し、\n      多様な意見や選択肢を得る一方で、地域に足を運び、人の声を直接聴き、人と人と\n       の対話を重ね、何を大切にするのかを自ら考え、判断することが重要です。AIにで\n       きることはAIに任せ、人にしかできない対話、共感、価値判断、責任を大切にしま\n       す。その上で、AIを人のため、地域のため、そしてより良い議会活動のために活用\n       していきたいと考えます。生成AIの導入そのものを目的とするのではなく、「声を\n       聴き、つなぎ、議論し、カタチにする」という議会本来の役割を、AIによってどこ\n所 感       まで強くできるか。そこに、AI時代の議会改革の可能性があると考えます。\n\n\n      ３，公民連携で地域を再生する\n      （１）「新しくつくる」から「今あるものの価値を高める」へ\n      岡崎氏の講義で特に印象に残ったのは、まちづくりを考える際に、単に公共施設を\n      整備するのではなく、「その土地の価値をどう高めるか」という視点を持つことで\n      す。紫波町のオガールでは、駅前の町有地を起点に、図書館、産直、飲食店、ホテ\n      ル、スポーツ施設、住宅などを組み合わせ、公民連携によってエリア全体の価値を\n      高めていました。この考え方を大崎市に置き換えると、必ずしもオガールと同じ施\n      設をつくる必要はなく。むしろ、大崎市には図書館、スポーツ施設、歴史・文化施\n      設、温泉、農業、自然など、すでに多くの資源があるので、これらを「単独の施\n      設・事業」として見るのではなく、周辺の土地や施設、民間事業者、人の流れと組\n      み合わせることで、新たな価値を生み出せないかという視点が重要だと感じまし\n      た。特に、現在十分に活用されていない土地や公共空間についても、「利用されて\n      いない＝価値がない」と考えるのではなく、「誰が、何のために使えば価値が生ま\n      れるのか」という発想で見直す必要があります。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":22,"text":"会派研修報告書\n\n\n      （２）大崎市の各地域を「ハブ」として捉える\n      今回の講義を大崎市に当てはめて考えると、各地域にはそれぞれ異なる「人を呼ぶ\n      力」や地域資源があることに気づきました。例えば、古川には多くの市民が利用す\n      る大崎市図書館があり、さらに吉野作造記念館という、大崎市ならではの歴史・文\n      化資源があります。図書館を「知・学び・交流」のハブ、吉野作造記念館を「歴\n      史・市民学習」のハブとして捉え、古川駅や商店街などとつなぐことで、施設の利\n      用者をまち全体へ回遊させる仕組みが考えられます。また、田尻では、すでにハン\n      ドボールやパークゴルフの「さくらカップ」に全国から人が集まっています。これ\n      は、新たなコンテンツを作らなくても、すでに人を呼ぶ力を持つスポーツイベント\n      を地域のハブとして活用できることを示しています。鹿島台には、野球場や体育施\n      設、交流施設に加え、仙台、松島、石巻方面などとつながる交通の利便性がある。\n      スポーツ・交流・農・食・交通を組み合わせることで、地域内外をつなぐ拠点とし\n      ての可能性がある。さらに、松山は、コスモス、酒、歴史、岩出山は伊達政宗や有\n      備館などの歴史・文化、鳴子は温泉・自然、鬼首は自然・温泉に加え、秋田・山形\n      との広域的なつながりという、それぞれ異なる強みを持っています。一つの地域に\n所 感\n      すべてを集めるのではなく、それぞれの地域が持つ強みをハブとして育て、それら\n      をつないでいく。これは、広域化した大崎市だからこそできるまちづくりではない\n      かと感じました。\n\n\n      （３）図書館を「本を借りる場所」から「まちのハブ」へ\n      特に大崎市図書館については、オガールの図書館を参考にできる部分が多いと感じ\n       ました。大崎市ではすでに「しあわせCafe」との連携が行われていますが、ここか\n      らさらに、民間テナント、マルシェ、子どもの学び、市民活動など、さまざまな人\n      や事業をつなげることができるのではないか？すでに人が集まっている図書館だか\n      らこそ、「図書館の利用者を増やす」だけではなく、「図書館に来た人をまちの中\n      へつなげる」という発想が重要だと考えます。さらに、古川駅と図書館の立地を生\n      かし、陸羽東線を利用して図書館や吉野作造記念館を訪れ、そこから商店街や地域\n      の飲食店などを回遊する仕組みも考えられます。図書館、文化施設、駅、商店街を\n      別々の施設として捉えるのではなく、一つの「まちの回遊」として考えることが、\n      オガールから学べる点だと感じました。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":23,"text":"会派研修報告書\n\n\n      （４）アリーナは「箱」をつくるのではなく、「事業」をつくる\n      大崎市でもアリーナ誘致・整備についての議論がありますが、岡崎氏の講義を聞\n      き、特に注意すべきなのは、アリーナを単なる大型公共施設、いわゆる「箱もの」\n      にしないことです。オガールアリーナについても、施設を建設することそのものが\n      目的ではなく、誰が運営するのか、どのような競技やイベントを行うのか、年間を\n      通してどのように稼働させるのか、周辺の飲食・宿泊・商業などにどのような経済\n      効果を生み出すのかという、事業としての継続可能性が重要になるということでし\n      た。したがって、大崎市でアリーナを検討する場合も、誰が経営・運営するのか、\n      どのようなコンテンツをつくるのか、年間を通じて人を呼べるのか、周辺地域にど\n      のような経済効果を生むのか、公共交通や宿泊、飲食などとどうつなげるのか、将\n      来の維持管理費をどうするのかまでを、建設前から考える必要があります。「ア\n      リーナを建てる」のではなく、「アリーナを核に何を生み出すのか」という視点が\n      必要だと感じました。\n\n       （５）「覚悟なきPPPは、始めてはいけない」\n       今回の講義で特に印象に残った言葉が、「覚悟なきPPPは、始めてはいけない」で\n      す。公民連携というと、民間の資金やノウハウを活用する手法という捉え方をしが\n      ちですが、岡崎氏の話からは、行政側にも明確なビジョンと責任、そして事業を実\n所 感       現する覚悟が必要であることを学びました。PPPは、行政が民間に任せることでは\n      ない。行政が「何を実現したいのか」というビジョンを持ち、その上で民間事業\n      者、金融機関、地域住民などと対話し、リスクとリターン、役割分担、意思決定、\n      運営主体を明確にしていく必要があります。特に公共施設は、一度つくれば終わり\n      ではなく、何十年にもわたって維持・運営していかなければならない。そのため、\n      「建設できるか」ではなく、「将来にわたって経営できるか」という視点を持つこ\n      とが重要だと感じました。\n\n      （６）議員の役割は「まちの価値を高める」こと\n      岡崎氏の「街の価値を上げるのは、議員の仕事」という言葉も強く印象に残りまし\n      た。公共施設の整備や予算を議論する際、これまでは「いくらかかるのか」「市の\n      負担はいくらなのか」という視点が中心になりがちだが、それだけではなく、その\n      投資によって何が生まれるのか。地域にどのような価値が残るのか。周辺の土地や\n       事業にどのような波及効果があるのか。10年後、20年後に大崎市にどのような資\n      産として残るのか。\n      という視点から議論することが、議員に求められているのではないかと感じまし\n      た。公共施設を「維持するもの」としてだけではなく、地域の価値を高めるための\n      資産として捉え直すことが必要だと思います。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":24,"text":"会派研修報告書\n\n\n      今回の講義を通して、まちづくりについての見方が大きく変わりました。大崎市に\n      は、すでに多くの資源があります。また、十分に活用されていない公共施設や土地\n      についても、単に「使われていない」「価値がない」と判断するのではなく、「何\n      とつなげれば価値が生まれるのか」「誰が使えば地域の価値が高まるのか」という\n      視点から見直すことができます。それぞれの地域にある「人が集まる場所」「人を\n      呼べるもの」「土地」「歴史」「文化」「自然」を見つけ、それぞれを地域のハブ\n      として育て、さらにそれらを交通や人の流れでつないでいく。そして、新しい公共\n      施設を整備する場合には、「何をつくるか」ではなく、「それによってどのような\n      価値を生み出し、誰が責任を持って運営し、将来にわたって地域に何を残すのか」\n      を考えることが重要です。今回の研修を通して得た、「ないものをつくる」のでは\n      なく、「あるものを見つけ、つなぎ、活かし、価値を高める」という視点を、今後\n      の大崎市の政策や公共施設のあり方を考える上で生かしていきたいです。\n\n\n      ４．政策議会の質問力\n所 感\n      今回の講義を通じて、一般質問に対する自分自身の捉え方を改めて深く見つめ直す\n      機会となりました。特に印象的で、今後必ず取り入れたいと思ったのが、「一般の\n       人が聞いても納得できる質問」「15歳の人にも分かる質問」という視点です。こ\n      れまで私は、議会で質問する際には、ある程度の専門用語や難しい言葉を使い、詳\n      しく説明した方がよいのではないかと考えていました。しかし、今回の講義を聞\n      き、重要なのは難しい言葉を使って説明することではなく、市民の皆様に「なぜこ\n      の課題を今議論する必要があるのか」を分かりやすく伝え、問題意識を共有するこ\n      となのだと気づきました。議会での議論は、議員と行政だけのものではなく、市民\n      のためのものです。だからこそ、市民の方が聞いて「確かにそうだ」と納得できる\n      質問をすることが、議会への理解や信頼にもつながるのだと思います。今後の一般\n      質問では、専門的な内容であっても、できるだけ分かりやすい言葉に置き換え、誰\n      が聞いても論点が理解できる質問を意識していきたいと考えます。また、一つひと\n      つの政策課題について、質問すること自体を目的にするのではなく、その前段階の\n      準備をより大切にしたいと思いました。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":25,"text":"会派研修報告書\n\n\n      具体的には、\n      「本当に大崎市にとって必要不可欠な課題なのか」\n      「現状はどうなっているのか」\n      「なぜ今、取り組む必要があるのか」\n      「今回の質問で何を引き出したいのか」\n      という点を、行政や関係機関、市民の皆様との事前のやり取りや、過去の一般質\n      問・答弁なども参考にしながら整理し、明確な論点を持って質問に臨みたいと思い\n所 感    ます。私は、議員活動において、「声を聴き、つなぎ、かたちにする」ということ\n      を大切にしたいと考えています。今回の講義を踏まえると、市民の声をそのまま行\n      政に伝えるだけではなく、その声を地域の政策課題として整理し、事実を確認し、\n      論点を明確にした上で、議会で議論し、最終的に政策や制度の改善につなげていく\n      ところまでが、議員の役割なのだと改めて感じました。今後は、一般質問を「質問\n      して答弁をもらう場」ではなく、市民の声を政策につなぎ、議会としてより良い決\n      断をしていくための場として捉え、一つひとつの質問をより丁寧に組み立てていき\n      たいと思います。\n\n      １． 講義の成果\n      今回の4つの講義を通して、最も大きな学びとなったのは、「つなぐ」という視点\n      を、これまで以上に具体的な議員活動として捉えることができたことです。\n      政策議会の質問力では、市民の声を聴き、それを分かりやすい政策課題として整理\n       し、議会で問い、政策につなげていくことの重要性を学びました。生成AIについて\n      は、情報や多様な住民意見を整理・分析し、議論や政策形成につなげる可能性を学\n      びました。公民連携では、行政だけで新しいものをつくるのではなく、すでに地域\n      にある人、場所、資源、活動を組み合わせ、その価値を高めていく視点を得まし\n      た。泉大津市の講義では、食、農業、健康、子育て、防災、環境などを個別の政策\n      として捉えるのではなく、それらをつなぐことで、市民の健康や命を守り、地域全\n総 括    体の持続可能性を高めるという考え方を学びました。\n       4つの講義はそれぞれ異なるテーマでしたが、共通していたのは、「個別に考える\n      のではなく、さまざまなものをつなぐことで新しい価値を生み出す」という考え方\n       でした。\n      今回の研修を通して、議員の役割についても改めて考える機会となりました。議員\n      は、単に行政に質問したり、予算をチェックしたりするだけではなく、市民の声、\n      人、情報、地域資源、行政、民間、そして地域と地域をつなぎ、それを政策として\n      形にしていく役割も担っているのではないかと感じました。\n      また、「新しいものをつくること」だけを考えるのではなく、「大崎市には何があ\n      るのか」「誰が活動しているのか」「すでにあるものを何と組み合わせれば、新し\n      い価値を生み出せるのか」という視点を持つことの重要性も学びました。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":26,"text":"会派研修報告書\n\n\n      ２．今後の展望\n      今後は、今回学んだ「つなぐ」という視点を、一般質問、委員会活動、市民との対\n      話、政策調査など、日々の議員活動に具体的に生かしていきたいと考えます。\n      特に、\n      「声を聴く → 情報を集める → つなぐ → 議論する → カタチにする → 結果を市民\n      に返す」\n      という政策サイクルを意識していきたいと思います。\n      市民の声を聴くだけで終わらせず、その声を事実やデータと照らし合わせ、必要な\n      情報を集め、関係する人や部署、地域、民間事業者などをつなぎ、議会で議論し、\n      政策につなげていく。そして、実施した政策がどのような成果を生んだのかを検証\n      し、その結果を市民に返していく。この循環を大切にしたいと考えます。\n       また、生成AIなどの新しい技術についても、導入すること自体を目的とするのでは\n       なく、情報収集や分析などAIにできることはAIに任せ、その分、人にしかできない\n      対話、共感、現場を見ること、価値判断、責任ある意思決定を大切にしていきま\n      す。\n\n      ３．政策提言の方向性総 括\n      今回の研修を踏まえ、今後の政策提言については、特に以下の方向性を検討してい\n      きたいと考えます。\n      ① 食・農・健康・防災をつなぐ政策\n      泉大津市の「医食同源」という考え方を参考に、農業振興、食育、健康づくり、子\n      育て、高齢者支援、防災を別々の政策として捉えるのではなく、「食を通じて市民\n      の健康と命を守る」という視点からつなげていくことを検討します。\n      大崎市は米をはじめとする豊かな農業資源を有する生産地であるため、食と農を健\n      康や防災と結び付ける可能性は大きいと考えます。\n\n      ② 「食の備蓄」を農業振興・食料安全保障につなげる\n      現在の災害備蓄を単なる非常時の食料確保として捉えるだけではなく、市内産米な\n      どを一定量確保することによって、生産者の安定した販売先の確保、食料安全保\n      障、米の消費拡大、防災を同時に進める仕組みができないか検討します。例えば、\n      市内産米を一定量備蓄し、保存期間や更新時期に合わせて学校給食、食育、福祉、\n      地域活動などに活用し、その分を新たに生産者から購入するような循環が可能かど\n      うか、調査・研究していきたいと考えます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":27,"text":"会派研修報告書\n\n\n      ③ 金芽米などを活用した食による健康支援\n      泉大津市や近隣自治体での取り組みを参考に、金芽米など、栄養面や健康面に特徴\n      のある米を、学校給食、妊産婦、高齢者、食育、備蓄などに活用する可能性につい\n      て調査します。\n      ただし、金芽米の導入そのものを目的とするのではなく、「食を通じて市民の健康\n      を守る」という視点から、費用、栄養面、導入効果、市内産米との組み合わせ、官\n      民連携の可能性などを検証した上で、大崎市に適した仕組みを考えていきたいと思\n      います。\n\n\n      ④ 既存の地域資源をつなぐまちづくり\n      新しい施設を一からつくるだけではなく、図書館、吉野作造記念館、スポーツ施\n      設、温泉、農業、自然、歴史、文化、地域イベント、マルシェなど、すでに大崎市\n      にある資源を組み合わせ、地域の価値を高めることを検討します。\n      また、古川、岩出山、三本木、松山、鳴子、鬼首、田尻、鹿島台など、それぞれの\n総 括    地域が持つ特色を「地域から地域へ」とつなぎ、人の流れや情報の流れを生み出す\n      ことも重要だと考えます。\n      ⑤ 公民連携と「挑戦する人」を支える仕組み\n      地域で「やってみたい」と考える市民や事業者が活動しやすいよう、活動場所だけ\n      でなく、相談、情報提供、行政との調整、地域の人や事業者とのマッチングなどを\n      支える仕組みについても検討します。\n      行政がすべてを担うのではなく、民間企業、生産者、市民、地域団体など、それぞ\n      れの強みをつなぐことで、既存の取り組みをさらに大きな地域の力へと発展させて\n      いきたいと考えます。\n\n\n      ⑥ 生成AIを活用した「声を政策につなぐ議会」\n       生成AIを活用し、議会情報の整理・発信、住民意見の収集・分析、政策調査などを\n      高度化し、「情報を公開する議会」から「必要な情報が届く議会」、「声を聴く議\n      会」から「声を政策につなぐ議会」への発展を目指します。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":28,"text":"会派研修報告書\n\n\n      ４．市内調査\n      今後は、政策提言を行う前に、大崎市の現状を具体的に調査し、実現可能性や効果\n      を確認していきたいと考えます。\n      特に、以下の項目について調査・確認を行います。\n      大崎市の現在の食料・米の備蓄量、保存方法、更新方法\n      市内産米を災害備蓄に活用する可能性\n      備蓄米の更新時に学校給食、福祉、食育等へ活用できる可能性\n      金芽米等の導入事例、費用、栄養面、導入効果\n      学校給食、妊産婦、高齢者などへの食を通じた健康支援の現状\n      市内の有機農産物の生産量、販路、学校給食や公共施設での利用状況\n      生産者と小売店、飲食店、学校等との連携状況\n      市内の公共施設の利用状況、維持管理費、施設周辺への経済波及\n      各地域で行われているマルシェ、イベント、市民活動と行政との連携状況\n      地域活動を支援するコーディネート機能の現状\n      図書館、駅、文化施設、商店街などをつなぐ人の流れの可能性\n      議会報告会・意見交換会等で出された市民意見が政策にどう反映されているか\n       生成AIを議会活動や情報発信に活用するための環境と課題総 括\n      こうした調査を通じて、研修で得たアイデアを単なる「参考事例」で終わらせず、\n      大崎市の実情に合った政策へと具体化していきたいと考えます。\n\n      ５．今後の改善点\n      今回の研修を通して、改善すべき点が見えてきました。\n      一つ目は、政策を分野ごとに縦割りで考えすぎないことです。例えば、高齢者の孤\n      立という課題一つをとっても、福祉だけではなく、公共交通、健康、デジタル、公\n      共施設、地域コミュニティ、食など、複数の分野が関係しています。今後は、一つ\n      の課題を複数の政策分野から捉え、横断的に考えることを意識します。\n      二つ目は、「事業を実施しているか」だけではなく、「その事業によってどのよう\n      な価値が生まれているか」を見ることです。公共施設についても、建設費や維持管\n      理費だけではなく、利用者、周辺経済、地域交流、将来の資産価値などを含めて考\n      えていきたいと思います。\n      三つ目は、研修で得た先進事例を、そのまま大崎市に当てはめないことです。泉大\n      津市や紫波町などの取り組みを参考にしながらも、「大崎市には何があるのか」\n      「大崎市なら何ができるのか」という視点で、市内の実情を確認した上で政策を考\n      えていきます。","method":"pdf-text","status":"ok","manual_supplement":false},{"id":"0522674c2515f938","year":2026,"faction":"希望の会","kind":"activity","title":"報告書(PDFファイル:603KB)","url":"https://www.city.osaki.miyagi.jp/material/files/group/62/kibounokai_20260727_28.pdf","page":29,"text":"会派研修報告書\n\n\n      ６．議会としての対応の要否\n\n      今回の研修で得たテーマには、議員個人の政策研究として取り組むものだけでな\n      く、議会全体として検討する必要があるものもあると考えます。\n       生成AIの議会活用、議会情報の分かりやすい発信、住民意見の収集・分析などにつ\n      いては、個々の議員だけではなく、議会全体として情報共有し、活用方法やルール\n      を検討することが望ましいと考えます。\n      一方、食の備蓄、金芽米、有機農業、公共施設の活用、地域資源をつなぐ仕組み、\n      公民連携などについては、まず市内調査を行い、一般質問や委員会での調査・議論\n      を通じて政策提言につなげていくことが考えられます。\n      また、公共施設やアリーナなど大きな財政負担を伴う事業については、「建設でき\n      るか」だけではなく、「将来にわたって運営できるか」「どのような地域価値を生\n      み出すのか」「誰が責任を持つのか」という視点から、議会として継続的に検証し\n      ていく必要があります。総 括\n      今回の研修を通して、議員として大切なのは、単に「新しい政策を提案すること」\n      ではなく、地域にすでにある人、場所、情報、資源、活動を見つけ、それらをつな\n      ぎ、必要なところに新しい力を加え、政策として形にしていくことだと学びまし\n      た。\n\n\n      「ないものをつくる」のではなく、「あるものを見つけ、つなぎ、活かし、価値を\n      高める」。\n      市民の声を聴き、人と人をつなぎ、地域と地域をつなぎ、行政と民間をつなぎ、さ\n      らに政策と政策をつなぐ。その先に、市民の暮らしや健康、地域産業、豊かな自然\n      を次の世代につないでいくことができると考えます。\n      今回の研修で得た学びを、研修だけで終わらせることなく、市内調査、一般質問、\n      委員会活動、政策提言へとつなげ、「声を聴き、つなぎ、カタチにする」議員活動\n      を積み重ねていきたいと考えます。","method":"pdf-text","status":"ok","manual_supplement":false}];
